/* Tạo tự động bởi tools/build-vocab.js từ sheet "SAT Vocab (Cũ)" – đừng sửa tay */
Vocab.addDeck({"id":"old6","sets":[{"n":"Buổi 1","c":[{"t":"Myriad","p":"adjective","d":"Nhiều, số lượng lớn","e":"It was difficult to decide what to do Friday night because the city presented us with myriad possibilities for fun.","ev":"Thật khó quyết định phải làm gì vào tối thứ Sáu vì thành phố đã mang đến cho chúng tôi vô số cơ hội vui chơi.","k":"myriad"},{"t":"Unclassifiable","p":"adjective","d":"Không thể được chỉ định vào một danh mục","e":"His art style was unclassifiable.","ev":"Phong cách nghệ thuật của ông không thể phân loại được.","k":"unclassifiable"},{"t":"Domestication","p":"noun","d":"Quá trình thuần hóa động vật hoặc trồng cây hoang dã","e":"The domestication of wild animals has a long history.","ev":"Việc thuần hóa động vật hoang dã có một lịch sử lâu dài.","k":"domestication"},{"t":"Refute","p":"verb","d":"Bác bỏ","e":"Maria refuted the president’s argument as she yelled and gesticulated at the Tverb","ev":"Maria bác bỏ lập luận của tổng thống khi cô ấy hét lên và khoa tay múa chân trước Tverb","k":"refute"},{"t":"Capacity","p":"noun","d":"Khả năng","e":"I was impressed by her capacity for hard work","ev":"Tôi rất ấn tượng bởi khả năng làm việc chăm chỉ của cô ấy","k":"capacity"},{"t":"Embroider","p":"verb","d":"xuyên tạc, bịa ra những câu chuyện về","e":"she embroidered her stories with colorful detail","ev":"cô ấy thêu dệt những câu chuyện của mình với những chi tiết đầy màu sắc","k":"embroider"},{"t":"Illusory","p":"adjective","d":"Không có thật; ảo tưởng","e":"The sense of security was illusory.","ev":"Cảm giác an toàn thật ảo tưởng.","k":"illusory"},{"t":"Static","p":"adjective","d":"Không thay đổi","e":"The image on the TV screen was static.","ev":"Hình ảnh trên màn hình TV tĩnh.","k":"static"},{"t":"Hamper","p":"verb","d":"cản đường hoặc cản trở","e":"The bad weather hampered our progress.","ev":"Thời tiết xấu đã cản trở sự tiến bộ của chúng tôi.","k":"hamper"},{"t":"Foster","p":"verb","d":"kích thích, thúc đẩy, khuyến khích","e":"To foster good health in the city, the mayor started a “Get out and exercise!” campaign.","ev":"tăng cường sức khỏe tốt cho thành phố, thị trưởng đã phát động chiến dịch “Hãy ra ngoài và tập thể dục!” chiến dịch.","k":"foster"},{"t":"Innocuous","p":"adjective","d":"Vô hại","e":"The innocuous remark was taken out of context and caused unnecessary drama.","ev":"Nhận xét vô hại đã bị hiểu sai trong ngữ cảnh và gây ra những rắc rối không cần thiết.","k":"innocuous"},{"t":"Polar","p":"adjective","d":"cực của Trái đất, phân hóa","e":"The polar regions are very cold.","ev":"Các vùng cực rất lạnh.","k":"polar"},{"t":"Heterogeneous","p":"adjective","d":"đa dạng, đa dạng về tính cách","e":"I hate having only one flavor so I always buy the swirled, or should I say heterogeneous, type of ice cream.","ev":"Tôi ghét chỉ có một hương vị nên tôi luôn mua loại kem xoáy, hay tôi nên nói là loại kem không đồng nhất.","k":"heterogeneous"},{"t":"Collaboration","p":"noun","d":"Sự hợp tác","e":"Their collaboration produced outstanding results.","ev":"Sự hợp tác của họ đã tạo ra kết quả nổi bật.","k":"collaboration"},{"t":"Disperse","p":"verb","d":"làm phân tán","e":"When the rain began to pour, the crowd at the baseball game quickly dispersed.","ev":"Khi trời bắt đầu đổ mưa, đám đông tại trận đấu bóng chày nhanh chóng giải tán.","k":"disperse"},{"t":"Prescient","p":"adjective","d":"biết trước về các sự kiện, tiên tri","e":"Questioning the fortune cookie’s prediction, Ray went in search of the old hermit who was rumored to be prescient.","ev":"Đặt câu hỏi về dự đoán của chiếc bánh quy may mắn, Ray đi tìm vị ẩn sĩ già được đồn đại là có khả năng tiên tri.","k":"prescient"},{"t":"Prodigious","p":"verb","d":"phi thường","e":"The prodigious talent of the young musician amazed everyone at the concert.","ev":"Tài năng phi thường của nhạc sĩ trẻ đã khiến mọi người kinh ngạc tại buổi hòa nhạc.","k":"prodigious"},{"t":"Confine","p":"verb","d":"Hạn chế trong phạm vi có hạn, giam hãm","e":"He was confined to his room for the day.","ev":"Anh ta bị nhốt trong phòng cả ngày.","k":"confine"},{"t":"Sound","p":"adjective","d":"Chắc chắn, ổn định, đáng tin cậy, có giá trị (ví dụ: một lập luận đúng đắn)","e":"The argument is sound and logical.","ev":"Lập luận có vẻ đáng tin cậy và hợp lý.","k":"sound"},{"t":"Superfluous","p":"adjective","d":"thừa","e":"The report was full of superfluous information that was not necessary.","ev":"Báo cáo đầy rẫy thông tin thừa thãi mà không cần thiết.","k":"superfluous"}]},{"n":"Buổi 2","c":[{"t":"Conjecture","p":"noun","d":"sự phỏng đoán","e":"His conjecture about the future was based on little evidence, making it speculative and uncertain.","ev":"Phỏng đoán của ông về tương lai dựa trên rất ít bằng chứng, khiến nó trở nên suy đoán và không chắc chắn.","k":"conjecture"},{"t":"Ruffle","p":"verb","d":"Bối rối, làm bực mình khó chịu","e":"His feathers were ruffled by the criticism.","ev":"Lông của anh ta bị xù lên bởi những lời chỉ trích.","k":"ruffle"},{"t":"Laconic","p":"adjective","d":"Vắn tắt, ngắn gọn","e":"The speaker was laconic, delivering his message in just a few words.","ev":"Người phát biểu rất ngắn gọn, truyền đạt thông điệp của mình chỉ trong vài từ.","k":"laconic"},{"t":"Bolster","p":"verb","d":"tăng cường","e":"They implemented changes to bolster their defenses.","ev":"Họ đã thực hiện các thay đổi củng cố phòng thủ.","k":"bolster"},{"t":"Grill","p":"verb","d":"Đặt câu hỏi một cách mãnh liệt và lặp đi lặp lại","e":"the police officers grilled the suspect thoroughly","ev":"cảnh sát hỏi cung nghi phạm một cách kỹ lưỡng","k":"grill"},{"t":"Discernible","p":"adjective","d":"Dễ thấy; có thể phát hiện được","e":"There was no discernible change in his condition.","ev":"Không có sự thay đổi rõ rệt nào trong tình trạng của anh ấy.","k":"discernible"},{"t":"Deplete","p":"verb","d":"sử dụng hết nguồn cung cấp hoặc tài nguyên của","e":"The drought depleted the water supply.","ev":"Hạn hán làm cạn kiệt nguồn cung cấp nước.","k":"deplete"},{"t":"Appraise","p":"verb","d":"Thẩm định","e":"A realtor will come over tonight to appraise our house.","ev":"Một nhân viên bất động sản sẽ đến tối nay định giá ngôi nhà của chúng tôi.","k":"appraise"},{"t":"Hinder","p":"verb","d":"làm cản trở, ngăn cản, làm chậm tiến độ","e":"The heavy rain hindered their progress.","ev":"Cơn mưa lớn đã cản trở bước tiến của họ.","k":"hinder"},{"t":"Galvanize","p":"verb","d":"tiếp thêm sinh lực; thúc đẩy hành động, kích hoạt","e":"The speech galvanized the community to take action.","ev":"Bài phát biểu đã thúc đẩy cộng đồng hành động.","k":"galvanize"},{"t":"Vacillate","p":"verb","d":"dao động, do dự","e":"I prefer a definite answer, but my boss kept vacillating between the distinct options available to us.","ev":"Tôi thích một câu trả lời rõ ràng hơn, nhưng sếp của tôi cứ lưỡng lự giữa các lựa chọn riêng biệt có sẵn cho chúng tôi.","k":"vacillate"},{"t":"Ingenious","p":"adjective","d":"thông minh, tháo vát","e":"Her ingenious use of walnuts instead of the peanuts called for by the recipe was lauded by the other garden club members who found her cake delicious.","ev":"Việc cô sử dụng quả óc chó một cách khéo léo thay vì đậu phộng theo công thức đã được các thành viên câu lạc bộ làm vườn khác khen ngợi vì thấy chiếc bánh của cô rất ngon.","k":"ingenious"},{"t":"Realize","p":"verb","d":"đạt được (một mục tiêu)","e":"realize one's dreams","ev":"thực hiện ước mơ của một người","k":"realize"},{"t":"Coalesce","p":"noun/verb","d":"kết hợp lại","e":"The two rivers coalesce into one larger river at the valley.","ev":"Hai con sông hợp nhất thành một con sông lớn hơn tại thung lũng.","k":"coalesce"},{"t":"Verisimilitude","p":"noun","d":"Chân thực, chân thật","e":"The novel’s characters have a sense of verisimilitude.","ev":"Các nhân vật của cuốn tiểu thuyết có cảm giác chân thực.","k":"verisimilitude"},{"t":"Execute","p":"verb","d":"thực hiện","e":"The plan was executed flawlessly.","ev":"Kế hoạch đã được thực hiện một cách hoàn hảo.","k":"execute"},{"t":"Dexterous","p":"adjective","d":"Khéo léo","e":"The dexterous artist crafted an intricate sculpture.","ev":"Người nghệ sĩ khéo léo đã tạo ra một tác phẩm điêu khắc phức tạp.","k":"dexterous"},{"t":"Unequivocal","p":"adjective","d":"Chắn chắn, rõ ràng","e":"She gave an unequivocal answer to the question.","ev":"Cô ấy đã đưa ra một câu trả lời rõ ràng cho câu hỏi.","k":"unequivocal"},{"t":"Explicit","p":"adjective","d":"Rõ ràng trực tiếp","e":"The rules were made explicit to avoid confusion.","ev":"Các quy tắc đã được thực hiện rõ ràng tránh nhầm lẫn.","k":"explicit"},{"t":"Mitigate","p":"verb","d":"làm giảm, bớt","e":"When I had an awful sore throat, only warm tea would mitigate the pain.","ev":"Khi tôi bị đau họng khủng khiếp, chỉ có trà ấm mới có thể làm dịu cơn đau.","k":"mitigate"}]},{"n":"Buổi 3","c":[{"t":"Scrutinize","p":"verb","d":"kiểm tra một ai đó hoặc một cái gì đó rất cẩn thận","e":"The police scrutinized the crime scene, looking for clues and evidence.","ev":"Cảnh sát đã khám nghiệm hiện trường vụ án, tìm kiếm manh mối và bằng chứng.","k":"scrutinize"},{"t":"Entice","p":"verb /ɪnˈtaɪs/","d":"dụ cám dỗ, cám dỗ, bị lôi kéo thuyết phục ai đó làm điều gì đó bằng cách đưa ra cho họ điều gì đó dễ chịu","e":"entice someone into something: The adverts entice the customer into buying things they don't really want. \nBe enticed away from: People are being enticed away from the profession by higher salaries elsewhere.","ev":"lôi kéo ai đó vào thứ gì đó: Quảng cáo lôi kéo khách hàng mua những thứ họ không thực sự muốn. \nBị lôi kéo khỏi: Mọi người đang bị lôi kéo rời bỏ nghề bởi mức lương cao hơn ở nơi khác.","k":"entice"},{"t":"Prolific","p":"adjective","d":"sung mãn","e":"He is a prolific writer, publishing several books each year.","ev":"Anh là một nhà văn phong phú, xuất bản nhiều cuốn sách mỗi năm.","k":"prolific"},{"t":"Prioritize","p":"verb","d":"Liệt kê hoặc xếp hạng theo thứ tự quan trọng","e":"You need to prioritize your tasks for the day.","ev":"Bạn cần ưu tiên các nhiệm vụ trong ngày.","k":"prioritize"},{"t":"Façade","p":"noun","d":"bức tường của một tòa nhà, bề ngoài","e":"Meet me in front of the museum’s main façade.","ev":"Gặp tôi trước mặt tiền chính của bảo tàng.","k":"façade"},{"t":"Precipitate","p":"verb","d":"Kết tủa","e":"Heavy rains can precipitate landslides in hilly areas.","ev":"Mưa lớn có thể gây ra lở đất ở các khu vực đồi núi.","k":"precipitate"},{"t":"Imminent","p":"adjective","d":"Sắp xảy ra","e":"A storm is imminent in the region.","ev":"Một cơn bão sắp xảy ra trong khu vực.","k":"imminent"},{"t":"Irreproachable","p":"adjective","d":"Không chê trách được, không có lỗi","e":"His conduct was irreproachable.","ev":"Hành vi của anh ta không thể chê trách được.","k":"irreproachable"},{"t":"Couch","p":"verb","d":"Ẩn dấu","e":"He couched his criticism in polite terms.","ev":"Anh ấy diễn đạt những lời chỉ trích của mình bằng những lời lẽ lịch sự.","k":"couch"},{"t":"Scrupulous","p":"adjective","d":"cẩn thận","e":"She was scrupulous in her research, ensuring all data was accurate and reliable.","ev":"Cô rất cẩn trọng trong nghiên cứu của mình, đảm bảo tất cả dữ liệu đều chính xác và đáng tin cậy.","k":"scrupulous"},{"t":"Substantiate","p":"verb","d":"Chứng minh","e":"They need evidence to substantiate their claims.","ev":"Họ cần bằng chứng chứng minh các tuyên bố của mình.","k":"substantiate"},{"t":"Cease","p":"verb","d":"Dừng lại; dừng lại","e":"Production will cease immediately.","ev":"Việc sản xuất sẽ ngừng ngay lập tức.","k":"cease"},{"t":"Ambiguous","p":"adjective","d":"mơ hồ","e":"Some believe Caesar married Cleopatra for her power; others think it was her beauty. His actual reasons are ambiguous.","ev":"Một số người cho rằng Caesar kết hôn với Cleopatra vì quyền lực của cô; những người khác nghĩ rằng đó là vì sắc đẹp của cô.","k":"ambiguous"},{"t":"Exploit","p":"verb","d":"tận dụng tối đa (một nguồn tài nguyên), sử dụng (một người) một cách không công bằng hoặc ích kỷ","e":"The company exploited its workers, paying them low wages and forcing them to work long hours.","ev":"Công ty bóc lột công nhân của mình, trả lương thấp cho họ và buộc họ phải làm việc nhiều giờ.","k":"exploit"},{"t":"Irrevocable","p":"adjective","d":"không thể lấy lại được","e":"The Bill of Rights is an irrevocable part of American law.","ev":"Tuyên ngôn Nhân quyền là một phần không thể hủy bỏ của luật pháp Hoa Kỳ.","k":"irrevocable"},{"t":"Intriguing","p":"adjective","d":"Khơi dậy sự tò mò hoặc quan tâm","e":"Her story was intriguing and captured everyone’s attention.","ev":"Câu chuyện của cô rất hấp dẫn và thu hút sự chú ý của mọi người.","k":"intriguing"},{"t":"Scrap","p":"verb","d":"Loại bỏ, loại bỏ cái gì đó không còn hữu ích hoặc không còn cần thiết","e":"Hundreds of nuclear weapons have been scrapped.","ev":"Hàng trăm vũ khí hạt nhân đã bị loại bỏ.","k":"scrap"},{"t":"Detractor","p":"noun","d":"Người chỉ trích một yêu cầu hoặc một hành động","e":"Detractors argue that the policy will have negative side effects.","ev":"Những người gièm pha cho rằng chính sách này sẽ có tác dụng phụ tiêu cực.","k":"detractor"},{"t":"Animosity","p":"noun","d":"Thù địch, căm ghét","e":"There was evident animosity between the two rivals.","ev":"Có sự thù địch rõ ràng giữa hai đối thủ.","k":"animosity"},{"t":"Momentous","p":"adjective","d":"rất quan trọng (liên quan đến một quyết định hoặc sự kiện)","e":"The decision was momentous, having a profound impact on the future of the country.","ev":"Quyết định này rất quan trọng, có tác động sâu sắc đến tương lai của đất nước.","k":"momentous"}]},{"n":"Buổi 4","c":[{"t":"Shelve/Table","p":"verb","d":"Từ chối hoặc loại bỏ (ví dụ: một ý tưởng hoặc đề xuất)","e":"The proposal was shelved for further consideration.","ev":"Đề xuất này đã được gác lại xem xét thêm.","k":"shelve/table"},{"t":"Synopsis","p":"noun","d":"Bản tóm tắt","e":"The book’s synopsis gave an overview of the plot.","ev":"Bản tóm tắt của cuốn sách đã đưa ra một cái nhìn tổng quan về cốt truyện.","k":"synopsis"},{"t":"Consensus","p":"noun","d":"Sự đồng thuận","e":"The jury was able to reach a consensus only after days of deliberation.","ev":"Bồi thẩm đoàn cuối cùng đã đồng ý sau nhiều cuộc thảo luận.","k":"consensus"},{"t":"Reserve","p":"verb","d":"giữ lại","e":"(e.g., to reserve judgment)","ev":"(ví dụ: bảo lưu phán quyết)","k":"reserve"},{"t":"Analogy","p":"noun","d":"sự so sánh giữa hai thứ","e":"He used an analogy to explain the complex concept, comparing it to something more familiar and easier to understand.","ev":"Ông đã sử dụng một phép loại suy giải thích khái niệm phức tạp, so sánh nó với một thứ gì đó quen thuộc và dễ hiểu hơn.","k":"analogy"},{"t":"Migration","p":"noun","d":"Sự di cư","e":"Seasonal migration of birds is fascinating to observe.","ev":"Sự di cư theo mùa của các loài chim rất thú vị quan sát.","k":"migration"},{"t":"Despondent","p":"adjective","d":"chán nản","e":"After losing his job, he felt despondent and lost.","ev":"Sau khi mất việc, anh cảm thấy tuyệt vọng và lạc lõng.","k":"despondent"},{"t":"Anomaly","p":"noun","d":"sự bất thường","e":"That rip in the space-time continuum is certainly a spatial anomaly.","ev":"Vết rách trong không-thời gian đó chắc chắn là một bất thường không gian.","k":"anomaly"},{"t":"Abrupt","p":"adjective","d":"đột ngột, bất ngờ, không báo trước","e":"The conversation came to an abrupt end when the phone rang, startling everyone present.","ev":"Cuộc trò chuyện kết thúc đột ngột khi điện thoại reo lên khiến tất cả những người có mặt đều giật mình.","k":"abrupt"},{"t":"Assert","p":"verb","d":"tuyên bố một sự thật hoặc niềm tin một cách tự tin và mạnh mẽ, khẳng định","e":"She asserted her authority as the leader, demanding respect and obedience.","ev":"Cô khẳng định quyền lực của mình với tư cách là người lãnh đạo, đòi hỏi sự tôn trọng và phục tùng.","k":"assert"},{"t":"Subjective","p":"adjective","d":"Bị ảnh hưởng bởi sở thích, ý kiến ​​hoặc cảm xúc cá nhân","e":"The review was highly subjective.","ev":"Việc đánh giá mang tính chủ quan cao.","k":"subjective"},{"t":"Spare, Severe","p":"adjective","d":"Không trang trí, rất đơn giản","e":"a very severe style of architecture","ev":"một phong cách kiến ​​trúc đơn giản","k":"spare, severe"},{"t":"discount","p":"verb","d":"Xem nhẹ","e":"Don’t discount his opinion just because he is young; he may have valuable insights.","ev":"Đừng xem nhẹ ý kiến của anh chỉ vì anh còn trẻ; anh có thể có những hiểu biết quý giá.","k":"discount"},{"t":"Prohibitive","p":"adjective","d":"Quá cao (độ khó hoặc mức giá) đến mức ngăn cản điều gì đó xảy ra","e":"The cost of the trip was prohibitive.","ev":"Chi phí của chuyến đi rất cao.","k":"prohibitive"},{"t":"Satiate","p":"verb","d":"Làm thoả mãn","e":"The dessert was rich enough to satiate even the sweetest tooth.","ev":"Món tráng miệng đủ phong phú làm thỏa mãn cả những người thích ngọt nhất.","k":"satiate"},{"t":"Offhand","p":"adjective","d":"Thực hiện một cách bốc đồng, không cần suy nghĩ trước","e":"He gave an offhand remark that surprised everyone.","ev":"Anh ấy đưa ra một nhận xét thẳng thắn khiến mọi người ngạc nhiên.","k":"offhand"},{"t":"Vindicate","p":"verb","d":"bào chữa, minh oan","e":"The attorney had no chance of vindicating the defendant with all of the strong evidence presented by the state.","ev":"Luật sư không có cơ hội bào chữa cho bị cáo với tất cả những bằng chứng thuyết phục mà nhà nước đưa ra.","k":"vindicate"},{"t":"Coarseness","p":"noun","d":"Sự thô ráp, sự khắc nghiệt","e":"The fabric’s coarseness made it uncomfortable to wear.","ev":"Độ thô của vải khiến người mặc cảm thấy khó chịu.","k":"coarseness"},{"t":"Profound","p":"adjective","d":"sâu sắc, mãnh liệt","e":"The book had a profound impact on me.","ev":"Cuốn sách đã có tác động sâu sắc đến tôi.","k":"profound"},{"t":"Indulgent","p":"adjective","d":"nuông chiều","e":"The indulgent parents often spoiled their children with extravagant gifts.","ev":"Các bậc phụ huynh nuông chiều thường làm hư con cái mình bằng những món quà xa xỉ.","k":"indulgent"}]},{"n":"Buổi 5","c":[{"t":"Enhance","p":"verb","d":"cải thiện hoặc tăng cường","e":"She took a course to enhance her skills.","ev":"Cô đã tham gia một khóa học nâng cao kỹ năng của mình.","k":"enhance"},{"t":"Sabotage","p":"verb","d":"phá hủy, làm hư hỏng","e":"The enemy attempted to sabotage the mission.","ev":"Kẻ thù cố gắng phá hoại nhiệm vụ.","k":"sabotage"},{"t":"Disparate","p":"adjective","d":"khác nhau rõ rệt, chứa các yếu tố tương phản rõ rệt","e":"Having widely varying interests, the students had disparate responses toward the novel.","ev":"Với những sở thích rất khác nhau, học sinh có những phản ứng khác nhau đối với cuốn tiểu thuyết.","k":"disparate"},{"t":"Tenuous","p":"adjective","d":"mong manh","e":"The connection between the two theories is quite tenuous and needs further investigation.","ev":"Mối liên hệ giữa hai lý thuyết này khá mong manh và cần được điều tra thêm.","k":"tenuous"},{"t":"Fabricate","p":"verb","d":"thêu dệt, bịa đặt","e":"When I arrived an hour late to class, I fabricated some excuse about my car breaking down on the way to school.","ev":"Khi đến lớp muộn một tiếng, tôi bịa ra một số lý do về việc xe của tôi bị hỏng trên đường đến trường.","k":"fabricate"},{"t":"Constitution","p":"noun","d":"Thể chất","e":"a football player has a solid constitution.","ev":"một cầu thủ bóng đá có thể chất vững chắc.","k":"constitution"},{"t":"Reconcile","p":"verb","d":"hòa hợp, hoà giải","e":"The feuding neighbors finally reconciled when one brought the other a delicious tuna noodle casserole.","ev":"Những người hàng xóm thù địch cuối cùng đã hòa giải khi người này mang cho người kia món mì cá ngừ hầm thơm ngon.","k":"reconcile"},{"t":"Imposing","p":"adjective","d":"Sừng sững","e":"The castle was imposing against the skyline.","ev":"Lâu đài sừng sững trên nền trời.","k":"imposing"},{"t":"Unqualified","p":"adjective","d":"tuyệt đối, không chút giữ lại","e":"She gave him her unqualified support.","ev":"Cô đã dành cho anh sự hỗ trợ tuyệt đối của mình.","k":"unqualified"},{"t":"Retrospect","p":"noun","d":"nhìn lại","e":"In retrospect, the decision made sense.","ev":"Nhìn lại, quyết định này có ý nghĩa.","k":"retrospect"},{"t":"Insight","p":"noun","d":"Hiểu biết sâu sắc","e":"He offered valuable insight during the discussion.","ev":"Ông đã đưa ra cái nhìn sâu sắc có giá trị trong cuộc thảo luận.","k":"insight"},{"t":"Unresolvable","p":"adjective","d":"Không thể giải quyết hoặc giải quyết","e":"The conflict seemed unresolvable.","ev":"Cuộc xung đột dường như không thể giải quyết được.","k":"unresolvable"},{"t":"Surpass","p":"verb","d":"Vượt quá; vượt xa hơn","e":"She aimed to surpass her previous achievements.","ev":"Cô đặt mục tiêu vượt qua những thành tích trước đây của mình.","k":"surpass"},{"t":"Impeccable","p":"adjective","d":"mẫu mực, hoàn hảo","e":"If your grades were as impeccable as your sister’s, then you too would receive a car for a graduation present.","ev":"Nếu điểm số của bạn cũng hoàn hảo như chị gái bạn thì bạn cũng sẽ nhận được một chiếc ô tô làm quà tốt nghiệp.","k":"impeccable"},{"t":"Replenish","p":"verb","d":"bổ sung, tiếp tế","e":"They needed to replenish their water supply.","ev":"Họ cần phải bổ sung nguồn cung cấp nước.","k":"replenish"},{"t":"Profusion","p":"noun","d":"Số lượng lớn, vô số","e":"There was a profusion of flowers in the garden.","ev":"Trong vườn có rất nhiều hoa.","k":"profusion"},{"t":"Catastrophic","p":"adjective","d":"Thảm khốc","e":"The earthquake was a catastrophic event.","ev":"Trận động đất là một sự kiện thảm khốc.","k":"catastrophic"},{"t":"Infallible","p":"adjective","d":"Không thể phạm sai lầm","e":"He believed his judgment to be infallible.","ev":"Anh tin rằng phán đoán của mình là không thể sai lầm.","k":"infallible"},{"t":"Indoctrinate","p":"verb","d":"Dạy một người/những người chấp nhận niềm tin một cách không phê phán, truyền bá, nhồi sọ","e":"The regime tried to indoctrinate citizens with its ideology.","ev":"Chế độ đã cố gắng truyền bá hệ tư tưởng của nó cho người dân.","k":"indoctrinate"},{"t":"Nefarious","p":"adjective","d":"bất chính, hiểm ác","e":"The villain's nefarious plans were finally revealed.","ev":"Kế hoạch tội ác của kẻ phản diện cuối cùng đã bị lộ.","k":"nefarious"}]},{"n":"Buổi 6","c":[{"t":"Impenetrable","p":"adjective","d":"Không thể đi qua, xuyên qua","e":"The thick forest was impenetrable.","ev":"Rừng rậm không thể xuyên thủng.","k":"impenetrable"},{"t":"Commonplace","p":"adjective","d":"Thông thường, tầm thường","e":"Cell phones are now commonplace in society.","ev":"Điện thoại di động hiện nay đã trở nên phổ biến trong xã hội.","k":"commonplace"},{"t":"Surmise","p":"verb","d":"suy luận, phỏng đoán","e":"After speaking to only one of the students, the teacher was able to surmise what had caused the fight.","ev":"Sau khi chỉ nói chuyện với một học sinh, giáo viên đã có thể phỏng đoán nguyên nhân gây ra vụ đánh nhau.","k":"surmise"},{"t":"Irate","p":"adjective","d":"giận dữ","e":"He became irate when he found out his car had been towed.","ev":"Anh trở nên tức giận khi phát hiện ra xe của mình đã bị kéo đi.","k":"irate"},{"t":"Paucity","p":"noun","d":"sự khan hiếm","e":"The paucity of information made it challenging to draw any conclusions.","ev":"Sự thiếu hụt thông tin đã khiến việc rút ra bất kỳ kết luận nào trở nên khó khăn.","k":"paucity"},{"t":"Insurmountable","p":"adjective","d":"Không thể vượt qua","e":"The challenges seemed insurmountable.","ev":"Những thử thách dường như không thể vượt qua.","k":"insurmountable"},{"t":"Sway","p":"verb","d":"thuyết phục làm theo","e":"He tried to sway the jury with his arguments.","ev":"Anh ta cố gắng thuyết phục bồi thẩm đoàn bằng những lập luận của mình.","k":"sway"},{"t":"Nebulous","p":"adjective","d":"Mơ hồ","e":"The directions were nebulous, making it hard to find the location.","ev":"Các chỉ dẫn rất mơ hồ, khiến việc tìm kiếm địa điểm trở nên khó khăn.","k":"nebulous"},{"t":"Advantageous","p":"adjective","d":"Thuận lợi","e":"This is a very advantageous situation.","ev":"Đây là một tình huống rất thuận lợi.","k":"advantageous"},{"t":"Uncanny","p":"adjective","d":"kỳ lạ","e":"There was an uncanny resemblance between the two sisters, almost as if they were twins.","ev":"Có một sự tương đồng kỳ lạ giữa hai chị em, gần như họ là sinh đôi.","k":"uncanny"},{"t":"Legacy","p":"noun","d":"Di sản","e":"He left a legacy of kindness and generosity.","ev":"Ông đã lại một di sản về lòng tốt và sự hào phóng.","k":"legacy"},{"t":"Advance","p":"verb","d":"đưa ra (quan điểm, ý kiến)","e":"She decided to advance her argument during the debate.","ev":"Cô quyết định đưa ra lập luận của mình trong cuộc tranh luận.","k":"advance"},{"t":"Buttress","p":"verb","d":"Củng cố","e":"The new law will buttress existing regulations.","ev":"Luật mới sẽ củng cố các quy định hiện có.","k":"buttress"},{"t":"Compromise","p":"verb","d":"Thoả hiệp","e":"We were not prepared to compromise on safety","ev":"Chúng tôi không sẵn sàng thỏa hiệp về vấn đề an toàn","k":"compromise"},{"t":"Untenable","p":"adjective","d":"Không vững, không được hỗ trợ (lập luận)","e":"His position in the argument was untenable.","ev":"Vị trí của ông trong cuộc tranh luận là không thể bảo vệ được.","k":"untenable"},{"t":"Idealize","p":"verb","d":"Lý tưởng hoá","e":"It is easy to idealize life in a big city.","ev":"Thật dễ dàng lý tưởng hóa cuộc sống ở một thành phố lớn.","k":"idealize"},{"t":"Corroborate","p":"verb","d":"chứng thực","e":"The witness was called to corroborate the evidence presented in court.","ev":"Nhân chứng đã được mời đến xác nhận bằng chứng được trình bày tại tòa.","k":"corroborate"},{"t":"Contingent","p":"adjective","d":"Phụ thuộc vào; tùy thuộc vào","e":"The success of the project is contingent on the budget approval.","ev":"Sự thành công của dự án phụ thuộc vào việc phê duyệt ngân sách.","k":"contingent"},{"t":"Debacle","p":"noun","d":"sự cố, thảm hoạ","e":"The debacle at the event led to a lot of negative publicity for the organization.","ev":"Cuộc khủng hoảng tại sự kiện đã dẫn đến nhiều tin tức tiêu cực cho tổ chức.","k":"debacle"},{"t":"Impoverished","p":"adjective","d":"Nghèo","e":"The impoverished community needs support.","ev":"Cộng đồng nghèo khó cần được hỗ trợ.","k":"impoverished"}]},{"n":"Buổi 7","c":[{"t":"Misconstrue","p":"verb","d":"Hiểu lầm","e":"His words were easily misconstrued by the audience.","ev":"Lời nói của anh dễ bị khán giả hiểu sai.","k":"misconstrue"},{"t":"Precursor","p":"noun","d":"Một người hoặc vật có trước; tiền thân","e":"The typewriter was a precursor to modern computers.","ev":"Máy đánh chữ là tiền thân của máy tính hiện đại.","k":"precursor"},{"t":"Overshadow","p":"verb","d":"làm lu mờ; làm cho ai đó hoặc cái gì đó có vẻ không quan trọng","e":"Her achievements were overshadowed by her brother’s success.","ev":"Thành tích của cô bị lu mờ bởi thành công của anh trai cô.","k":"overshadow"},{"t":"Ominous","p":"adjective","d":"điềm gở, đáng ngại","e":"There was an ominous silence when I asked whether my contract was going to be renewed.","ev":"Có một sự im lặng đáng ngại khi tôi hỏi liệu hợp đồng của tôi có được gia hạn hay không.","k":"ominous"},{"t":"Conviction","p":"noun","d":"Sự chắc chắn, quyết tâm. Niềm tin vững chắc","e":"she takes pride in stating her political convictions.","ev":"cô ấy tự hào khi nêu quan điểm chính trị của mình.","k":"conviction"},{"t":"Assume","p":"verb","d":"Chịu trách nhiệm, có được (ví dụ: đảm nhận một vị trí mới)","e":"The new CEO assumed her role on January 1st.","ev":"Giám đốc điều hành mới đảm nhận vai trò của mình vào ngày 1 tháng 1.","k":"assume"},{"t":"Acknowledge","p":"verb","d":"chấp nhận, thừa nhận","e":"She acknowledged the challenges posed by the project.","ev":"Cô thừa nhận những thách thức mà dự án đặt ra.","k":"acknowledge"},{"t":"Waive","p":"verb","d":"Từ bỏ, không áp dụng (quyền lợi, phí)","e":"He decided to waive his right to a trial.","ev":"Anh quyết định từ bỏ quyền được xét xử.","k":"waive"},{"t":"Acclaim","p":"verb/noun","d":"Hoan hô, khen ngợi","e":"Greg’s poem won the acclaim of his friends.","ev":"Bài thơ của Greg đã nhận được sự khen ngợi từ bạn bè.","k":"acclaim"},{"t":"Infer","p":"verb","d":"suy luận hoặc kết luận từ bằng chứng và lý luận","e":"From the clues, she was able to infer what had happened.","ev":"Từ những manh mối đó, cô có thể suy ra chuyện gì đã xảy ra.","k":"infer"},{"t":"Approximate","p":"verb/adjective","d":"Ước tính","e":"The approximate cost of the project is $5,000.","ev":"Chi phí ước tính của dự án là 5.000 USD.","k":"approximate"},{"t":"Overload","p":"verb/noun","d":"Quá tải","e":"The workload caused him to feel overloaded.","ev":"Khối lượng công việc khiến anh cảm thấy quá tải.","k":"overload"},{"t":"Resurgence","p":"noun","d":"Sự trở lại (sau một thời gian sụt giảm)","e":"There was a resurgence of interest in classic films.","ev":"Sự quan tâm trở lại đối với các bộ phim cổ điển.","k":"resurgence"},{"t":"Discriminating","p":"adjective","d":"Có khả năng phân biệt rõ ràng, tinh tế","e":"She has a discriminating taste in music.","ev":"Cô ấy có gu âm nhạc rất tinh tế.","k":"discriminating"},{"t":"Imperative","p":"adjective/noun","d":"cần thiết, bắt buộc","e":"It is imperative that you have these folders organized by midday.","ev":"Điều bắt buộc là bạn phải sắp xếp các thư mục này trước giữa trưa.","k":"imperative"},{"t":"Waver","p":"verb","d":"lưỡng lự","e":"She wavered between taking the job offer and staying.","ev":"Cô ấy lưỡng lự giữa việc nhận lời mời làm việc và ở lại.","k":"waver"},{"t":"Meticulous","p":"adjective","d":"Tỉ mỉ, cẩn thận","e":"The ornate needlework in the bride’s gown was a product of meticulous handiwork.","ev":"Những đường thêu trang trí công phu trên váy cô dâu là sản phẩm của sự thủ công tỉ mỉ.","k":"meticulous"},{"t":"Appease","p":"verb","d":"Xoa dịu","e":"The mother gave her child candy to appease him when he cried.","ev":"Người mẹ đã cho đứa trẻ kẹo làm dịu nó khi nó khóc.","k":"appease"},{"t":"Juxtaposition","p":"noun","d":"việc sắp đặt hai thứ cạnh nhau (đặt vật A cạnh vật B)","e":"The interior designer admired my juxtaposition of the yellow couch and green table.","ev":"Nhà thiết kế nội thất ngưỡng mộ sự sắp xếp cạnh nhau của chiếc ghế dài màu vàng và chiếc bàn màu xanh lá cây.","k":"juxtaposition"},{"t":"Amorphous","p":"adjective","d":"vô định hình, không rõ ràng","e":"The effort was doomed from the start because the reasons behind it were amorphous.","ev":"Nỗ lực đã bị thất bại ngay từ đầu vì lý do phía sau nó không rõ ràng.","k":"amorphous"}]},{"n":"Buổi 8","c":[{"t":"Speculate","p":"verb","d":"Suy đoán","e":"The police speculated about the motive for the crime, considering various possibilities but ultimately unable to determine the truth.","ev":"Cảnh sát suy đoán về động cơ gây án, xem xét nhiều khả năng khác nhau nhưng cuối cùng không thể xác định được sự thật.","k":"speculate"},{"t":"Revelation","p":"noun","d":"Tiết lộ","e":"The revelation shocked everyone present.","ev":"Tiết lộ này đã gây sốc cho tất cả những người có mặt.","k":"revelation"},{"t":"Latent","p":"adjective","d":"Tiềm tàng, không rõ ràng","e":"Sigmund’s dream represented his latent paranoid obsession with other people’s shoes.","ev":"Giấc mơ của Sigmund thể hiện nỗi ám ảnh hoang tưởng tiềm ẩn của anh về đôi giày của người khác.","k":"latent"},{"t":"Pretentious","p":"adjective","d":"Kiêu căng","e":"His pretentious speech annoyed many of the guests.","ev":"Lời nói kiêu căng của anh ta khiến nhiều quan khách khó chịu.","k":"pretentious"},{"t":"Harbor","p":"verb","d":"ấp ủ, nuôi dưỡng (niềm tin, suy nghĩ thường là tiêu cực)","e":"e.g., to harbor a belief","ev":"nuôi dưỡng một niềm tin","k":"harbor"},{"t":"Exorbitant","p":"adjective","d":"thái quá, (giá) cắt cổ","e":"The exorbitant prices of luxury goods can deter many consumers.","ev":"Giá cả quá cao của hàng hóa xa xỉ có thể làm nhiều người tiêu dùng chùn bước.","k":"exorbitant"},{"t":"Evade","p":"verb","d":"trốn tránh","e":"He managed to evade capture for years.","ev":"Anh ta đã trốn tránh bị bắt trong nhiều năm.","k":"evade"},{"t":"Reciprocate","p":"verb","d":"đáp lại, có qua có lại","e":"When Steve gave Samantha a sweater for Christmas, she reciprocated by giving him a kiss.","ev":"Khi Steve tặng Samantha một chiếc áo len nhân dịp Giáng sinh, cô ấy đã đáp lại bằng một nụ hôn.","k":"reciprocate"},{"t":"Rebut","p":"verb","d":"bác bỏ","e":"The lawyer rebutted the accusations with strong evidence.","ev":"Luật sư bác bỏ lời cáo buộc bằng bằng chứng thuyết phục.","k":"rebut"},{"t":"Credulous","p":"adjective","d":"Dễ bị lừa, cả tin","e":"He was too credulous to see through the scam.","ev":"Anh ta quá cả tin có thể nhìn thấu được trò lừa đảo.","k":"credulous"},{"t":"Annotate","p":"verb","d":"chú thích","e":"The teacher asked us to annotate the text.","ev":"Giáo viên yêu cầu chúng tôi chú thích văn bản.","k":"annotate"},{"t":"Replicate","p":"verb","d":"sao chép","e":"Scientists were able to replicate the experiment’s results.","ev":"Các nhà khoa học đã có thể tái tạo kết quả của thí nghiệm.","k":"replicate"},{"t":"Upset","p":"verb/noun","d":"làm đảo lộn, làm hỏng","e":"Any mechanical problems would upset our plans of driving across the desert.","ev":"Bất kỳ sự cố máy móc nào cũng có thể làm đảo lộn kế hoạch lái xe băng qua sa mạc của chúng tôi.","k":"upset"},{"t":"Comprise","p":"verb","d":"bao gồm hoặc được tạo thành từ","e":"The team was comprised of players from different countries.","ev":"Đội bao gồm các cầu thủ đến từ các quốc gia khác nhau.","k":"comprise"},{"t":"Augment","p":"verb","d":"Tăng cường","e":"The student seeks to augment his knowledge of French by reading literature.","ev":"Sinh viên đó muốn mở rộng kiến thức tiếng Pháp bằng cách đọc văn học.","k":"augment"},{"t":"Fruitful/Fruitless","p":"adjective","d":"Có hiệu quả/không hiệu quả","e":"Their discussion was fruitful, resulting in a new plan.","ev":"Cuộc thảo luận của họ đã có kết quả, dẫn đến một kế hoạch mới.","k":"fruitful/fruitless"},{"t":"Prescribe","p":"verb","d":"đặt ra một quy tắc, quy định","e":"The duke prescribed that from this point further all of the peasants living on his lands would have to pay higher taxes.","ev":"Công tước quy định rằng kể từ thời điểm này trở đi, tất cả nông dân sống trên đất của ông sẽ phải nộp thuế cao hơn.","k":"prescribe"},{"t":"Accentuate","p":"verb","d":"nhấn mạnh, emphasize","e":"Psychologists say happy people accentuate the positive in life.","ev":"Các nhà tâm lý học nói rằng những người hạnh phúc nhấn mạnh điều tích cực trong cuộc sống. (Họ luôn nhìn vào mặt tích cực)","k":"accentuate"},{"t":"Pretext","p":"noun","d":"lý do bao biện","e":"He used a pretext to avoid the meeting.","ev":"Anh ta đã dùng lý do giả tránh cuộc họp.","k":"pretext"},{"t":"Diverge","p":"verb","d":"Phân nhánh","e":"The roads diverged at the intersection.","ev":"Các con đường phân nhánh ở ngã tư.","k":"diverge"}]},{"n":"Buổi 9","c":[{"t":"Mobilize","p":"verb","d":"Huy động","e":"The army was mobilized in response to the threat.","ev":"Quân đội đã được huy động đối phó với mối đe dọa.","k":"mobilize"},{"t":"Skeptic","p":"noun","d":"Hoài nghi","e":"As a skeptic, she demanded more proof before agreeing.","ev":"Là một người hoài nghi, cô yêu cầu thêm bằng chứng trước khi đồng ý.","k":"skeptic"},{"t":"Induce","p":"verb","d":"gây ra","e":"The medication may induce drowsiness, so be cautious when driving.","ev":"Thuốc có thể gây buồn ngủ, vì vậy hãy cẩn thận khi lái xe.","k":"induce"},{"t":"Spurious","p":"adjective","d":"giả mạo","e":"The claims turned out to be spurious.","ev":"Các tuyên bố hóa ra là giả mạo.","k":"spurious"},{"t":"Resilient","p":"adjective","d":"kiên cường","e":"The resilient ballplayer quickly recovered from his wrist injury.","ev":"Cầu thủ chơi bóng kiên cường đã nhanh chóng bình phục chấn thương cổ tay.","k":"resilient"},{"t":"Aesthetic","p":"adjective","d":"Thẩm mỹ","e":"We hired Susan for her excellent aesthetic sense in decorating.","ev":"Chúng tôi đã thuê Susan vì khả năng thẩm mỹ tuyệt vời của cô trong việc trang trí.","k":"aesthetic"},{"t":"Intricate","p":"adjective","d":"Rất phức tạp","e":"The design is intricate and beautiful.","ev":"Thiết kế rất phức tạp và đẹp.","k":"intricate"},{"t":"Grave/ Gravity","p":"adjective/noun","d":"(sự nghiêm trọng)","e":"The situation was grave.","ev":"Tình hình thật nghiêm trọng.","k":"grave/ gravity"},{"t":"Orthodox","p":"adjective","d":"chính thống","e":"His orthodox views on education often clashed with innovative teaching methods.","ev":"Quan điểm chính thống của ông về giáo dục thường mâu thuẫn với các phương pháp giảng dạy sáng tạo.","k":"orthodox"},{"t":"Draconian","p":"adjective","d":"Hà khắc, khắc nghiệt","e":"The new regulations were considered draconian by many.","ev":"Nhiều quy định mới được nhiều người coi là hà khắc.","k":"draconian"},{"t":"Bent","p":"noun","d":"Có năng khiếu, khuynh hướng về","e":"He has a bent for mathematics.","ev":"Anh ấy có năng khiếu về toán học.","k":"bent"},{"t":"Idiosyncratic","p":"adjective","d":"đặc biệt đối với một người; mang tính cá nhân hóa cao","e":"I know you had trouble with the last test, but because your mistakes were highly idiosyncratic, I’m going to deny your request that the class be given a new test.","ev":"Tôi biết bạn đã gặp khó khăn với bài kiểm tra vừa rồi, nhưng vì những lỗi của bạn rất đặc trưng nên tôi sẽ từ chối yêu cầu của bạn về việc cho cả lớp làm một bài kiểm tra mới.","k":"idiosyncratic"},{"t":"Chance","p":"verb","d":"cố gắng","e":"She waited a few seconds and chanced another look","ev":"Cô đợi vài giây và cố gắng nhìn lại","k":"chance"},{"t":"Prevail","p":"verb","d":"Thắng thế","e":"She hoped that good would ultimately prevail.","ev":"Cô hy vọng rằng điều tốt đẹp cuối cùng sẽ thắng thế.","k":"prevail"},{"t":"(Pre)Supposition","p":"noun","d":"Giả định","e":"The study was based on the presupposition that people act rationally.","ev":"Nghiên cứu này dựa trên giả định rằng mọi người hành động một cách hợp lý.","k":"(pre)supposition"},{"t":"Infinitesimal","p":"adjective","d":"Cực kỳ nhỏ; tiến tới số không","e":"The risk of error was infinitesimal.","ev":"Nguy cơ xảy ra lỗi là vô cùng nhỏ.","k":"infinitesimal"},{"t":"Pragmatic","p":"adjective","d":"Thiết thực","e":"The politician argued that while increased security measures might not fit with the lofty ideals of the nation, they were a pragmatic necessity to ensure everyone’s safety.","ev":"Chính trị gia này lập luận rằng mặc dù các biện pháp an ninh được tăng cường có thể không phù hợp với lý tưởng cao cả của quốc gia, nhưng chúng là một điều cần thiết thực tế đảm bảo an toàn cho mọi người.","k":"pragmatic"},{"t":"Austere","p":"adjective","d":"khắc khổ","e":"The austere furniture in the abandoned house made it feel haunted.","ev":"Đồ nội thất đơn giản trong ngôi nhà bị bỏ hoang khiến nó cảm thấy ám ảnh.","k":"austere"},{"t":"Renounce","p":"verb","d":"Từ bỏ","e":"He chose to renounce his previous lifestyle and start anew.","ev":"Anh quyết định từ bỏ lối sống trước đây và bắt đầu lại.","k":"renounce"},{"t":"Ameliorate","p":"verb","d":"cải thiện","e":"The tense situation was ameliorated when Sam proposed a solution everyone could agree upon.","ev":"Tình huống căng thẳng đã được cải thiện khi Sam đề xuất một giải pháp mà mọi người có thể đồng ý.","k":"ameliorate"}]},{"n":"Buổi 10","c":[{"t":"Intuition","p":"noun","d":"bản năng, khả năng hiểu điều gì đó ngay lập tức","e":"She had a strong intuition that something was wrong, even though there was no concrete evidence to support her suspicion.","ev":"Cô có trực giác mạnh mẽ rằng có điều gì đó không ổn, mặc dù không có bằng chứng cụ thể nào chứng minh cho sự nghi ngờ của cô.","k":"intuition"},{"t":"Unattainable","p":"adjective","d":"Không thể đạt được","e":"Perfection is often considered unattainable.","ev":"Sự hoàn hảo thường được coi là không thể đạt được.","k":"unattainable"},{"t":"Invasive","p":"adjective","d":"Lan truyền một cách có hại, xâm lấn","e":"The invasive species threatened the native plants.","ev":"Các loài xâm lấn đe dọa thực vật bản địa.","k":"invasive"},{"t":"Discord","p":"noun","d":"sự bất đồng giữa mọi người","e":"The discord between the two factions led to a civil war.","ev":"Sự bất hòa giữa hai phe đã dẫn đến một cuộc nội chiến.","k":"discord"},{"t":"Moribund","p":"adjective","d":"Đang đến gần cái chết; trên bờ vực trở nên lỗi thời","e":"The technology was considered moribund.","ev":"Công nghệ này được coi là lỗi thời.","k":"moribund"},{"t":"Rudimentary","p":"adjective","d":"Cơ bản, sơ cấp","e":"He had a rudimentary understanding of the language.","ev":"Anh ấy có sự hiểu biết sơ bộ về ngôn ngữ.","k":"rudimentary"},{"t":"Substantial","p":"adjective","d":"có tầm quan trọng, quy mô hoặc giá trị đáng kể.","e":"a substantial amount of cash","ev":"một lượng tiền mặt đáng kể","k":"substantial"},{"t":"Outsized","p":"adjective","d":"Lớn không cân xứng","e":"The house was outsized compared to its surroundings.","ev":"Ngôi nhà có kích thước quá lớn so với xung quanh.","k":"outsized"},{"t":"Erratic","p":"adjective","d":"không thể đoán trước, không nhất quán, bất thường","e":"The erratic weather made it difficult to plan outdoor activities.","ev":"Thời tiết thất thường khiến việc lên kế hoạch cho các hoạt động ngoài trời trở nên khó khăn.","k":"erratic"},{"t":"Relay","p":"verb","d":"truyền lại cho người khác (ví dụ: chuyển tiếp thông tin)","e":"The message was relayed to the troops.","ev":"Thông điệp đã được chuyển đến quân đội.","k":"relay"},{"t":"Ruminate About","p":"verb","d":"Suy nghĩ sâu sắc về điều gì đó","e":"The writer ruminated about the meaning of life while sitting by the lake.","ev":"Nhà văn ngẫm nghĩ về ý nghĩa cuộc sống khi ngồi bên hồ.","k":"ruminate about"},{"t":"Exacerbate","p":"verb","d":"làm cho bạo lực hơn, dữ dội hơn","e":"The gruesome and scary movie I saw last night exacerbated my fears of the dark.","ev":"Bộ phim khủng khiếp và đáng sợ mà tôi xem tối qua càng làm tăng thêm nỗi sợ bóng tối của tôi.","k":"exacerbate"},{"t":"Ambivalence","p":"noun","d":"N. tình trạng không chắc chắn hoặc bị mắc kẹt giữa hai hoặc nhiều lựa chọn","e":"ambivalence toward marriage","ev":"Sự không chắc chắn về việc kết hôn","k":"ambivalence"},{"t":"Strenuous","p":"adjective","d":"đòi hỏi năng lượng hoặc sức chịu đựng to lớn","e":"Running a marathon is quite a strenuous task. So is watching an entire Star Trek marathon.","ev":"Chạy marathon là một công việc khá vất vả. Việc xem toàn bộ cuộc thi marathon Star Trek cũng vậy.","k":"strenuous"},{"t":"Indifferent","p":"adjective","d":"Không có sự quan tâm hoặc quan tâm; thờ ơ","e":"He was indifferent to the outcome of the game.","ev":"Anh ấy thờ ơ với kết quả của trận đấu.","k":"indifferent"},{"t":"Deviation","p":"noun","d":"Sai lệch","e":"There was a slight deviation from the original plan.","ev":"Có một chút sai lệch so với kế hoạch ban đầu.","k":"deviation"},{"t":"Lucrative","p":"adjective","d":"sinh lời","e":"The new startup proved to be a lucrative venture for its founders.","ev":"Công ty khởi nghiệp mới đã chứng tỏ là một dự án sinh lời cho các nhà sáng lập.","k":"lucrative"},{"t":"Engulf","p":"verb","d":"Bao trùm","e":"The flames engulfed the house, destroying it completely.","ev":"Ngọn lửa bao trùm ngôi nhà, thiêu rụi hoàn toàn.","k":"engulf"},{"t":"Insuperable","p":"adjective","d":"Không thể vượt qua được","e":"They faced insuperable obstacles.","ev":"Họ phải đối mặt với những trở ngại không thể vượt qua.","k":"insuperable"},{"t":"Indecipherable","p":"adjective","d":"Không thể đọc hoặc hiểu được","e":"The old manuscript was indecipherable.","ev":"Bản thảo cũ không thể giải mã được.","k":"indecipherable"}]},{"n":"Buổi 11","c":[{"t":"Badger","p":"verb","d":"quấy rầy hoặc làm phiền","e":"She badgered him until he agreed to help.","ev":"Cô nài nỉ anh cho đến khi anh đồng ý giúp đỡ.","k":"badger"},{"t":"Affinity","p":"noun","d":"Mối liên hệ, sự thân thiết","e":"Jerry didn’t know why, but he felt an incredible affinity for Kramer the first time they met.","ev":"Jerry không biết tại sao, nhưng anh cảm thấy một mối liên hệ đặc biệt với Kramer lần đầu họ gặp nhau.","k":"affinity"},{"t":"Cite","p":"verb","d":"Trích dẫn","e":"Please cite your sources in the essay.","ev":"Hãy trích dẫn nguồn của bạn trong bài luận.","k":"cite"},{"t":"Economy","p":"noun","d":"Tiết kiệm","e":"We must learn to practice economy.","ev":"Chúng ta phải học cách thực hành tiết kiệm.","k":"economy"},{"t":"Catalyze","p":"verb","d":"Xúc tác, truyền cảm hứng","e":"The president’s speech catalyzed the nation and resuscitated the economy.","ev":"Bài phát biểu của tổng thống đã xúc tác đất nước và vực dậy nền kinh tế.","k":"catalyze"},{"t":"Indigenous","p":"adjective","d":"bản địa","e":"The indigenous people of the region have a rich cultural heritage.","ev":"Người bản địa của khu vực này có một di sản văn hóa phong phú.","k":"indigenous"},{"t":"Pervasive","p":"adjective","d":"có xu hướng lan rộng khắp, tràn khắp","e":"Stepping off the plane in Havana, I recognized the pervasive odor of sugar cane fields on fire.","ev":"Bước xuống máy bay ở Havana, tôi ngửi thấy mùi hôi nồng nặc của cánh đồng mía cháy.","k":"pervasive"},{"t":"Imperceptible","p":"adjective","d":"Không thể nhìn thấy hoặc cảm nhận được","e":"The changes in his behavior were almost imperceptible.","ev":"Những thay đổi trong hành vi của anh ấy gần như không thể nhận ra.","k":"imperceptible"},{"t":"Unconventional","p":"adjective","d":"không tuân theo các quy tắc truyền thống hoặc được chấp nhận","e":"He had an unconventional approach to teaching.","ev":"Ông có một cách tiếp cận giảng dạy độc đáo.","k":"unconventional"},{"t":"Mercurial","p":"adjective","d":"Thất thường","e":"His mercurial temperament made it hard for people to know how he would react.","ev":"Tính cách thất thường của anh khiến mọi người khó đoán được anh sẽ phản ứng như thế nào.","k":"mercurial"},{"t":"Plastic","p":"adjective","d":"Có thể thay đổi, dễ uốn nắn","e":"brain plasticity","ev":"sự linh hoạt của não (việc cấu trúc não thay đổi để đáp ứng và ghi nhớ các kiến thức mới trong đời người)","k":"plastic"},{"t":"Haphazard","p":"adjective","d":"không có kế hoạch nào, ngẫu nhiên","e":"The books were arranged in a haphazard manner, making it hard to find anything.","ev":"Các cuốn sách được sắp xếp lộn xộn, khó tìm được thứ gì.","k":"haphazard"},{"t":"Elicit","p":"verb","d":"Gợi mở, thu hút","e":"The teacher aimed to elicit responses from all the students during the discussion.","ev":"Giáo viên nhằm mục đích thu hút phản hồi từ tất cả học sinh trong cuộc thảo luận.","k":"elicit"},{"t":"Channel","p":"verb","d":"Hướng một cái gì đó (ví dụ: năng lượng, tiền bạc) vào một mục đích cụ thể","e":"A lot of money has been channeled into cancer research.","ev":"Rất nhiều tiền đã được chuyển vào nghiên cứu ung thư.","k":"channel"},{"t":"Ubiquitous","p":"adjective","d":"khắp nơi","e":"Smartphones have become ubiquitous in modern society.","ev":"Điện thoại thông minh đã trở nên phổ biến trong xã hội hiện đại.","k":"ubiquitous"},{"t":"Credible","p":"adjective","d":"đáng tin cậy","e":"The witness provided a credible testimony.","ev":"Nhân chứng đã đưa ra lời khai đáng tin cậy.","k":"credible"},{"t":"Abundant","p":"adjective","d":"dồi dào","e":"The resources were abundant in the region, providing a rich and plentiful supply for the people.","ev":"Nguồn tài nguyên trong vùng dồi dào, cung cấp nguồn cung dồi dào và dồi dào cho người dân.","k":"abundant"},{"t":"Relate","p":"verb","d":"Kể lại (một câu chuyện)","e":"He related the events of his childhood.","ev":"Anh kể lại những sự kiện thời thơ ấu của mình.","k":"relate"},{"t":"Eclipse","p":"verb","d":"làm lu mờ hoặc chặn","e":"Her success eclipsed all other achievements.","ev":"Thành công của cô làm lu mờ tất cả những thành tựu khác.","k":"eclipse"},{"t":"Affecting","p":"adjective","d":"Chạm vào cảm xúc; sâu sắc","e":"The movie’s ending was deeply affecting.","ev":"Cái kết của bộ phim gây ấn tượng sâu sắc.","k":"affecting"}]},{"n":"Buổi 12","c":[{"t":"Unobtrusive","p":"adjective","d":"Không dễ thấy; không thu hút sự chú ý","e":"He tried to be unobtrusive at the event.","ev":"Anh cố gắng tỏ ra kín đáo tại sự kiện.","k":"unobtrusive"},{"t":"Equitable","p":"adjective","d":"Công bằng","e":"The judge aimed to ensure an equitable distribution of resources among the community.","ev":"Thẩm phán nhắm đến việc đảm bảo phân phối công bằng tài nguyên giữa các thành viên trong cộng đồng.","k":"equitable"},{"t":"Evince","p":"verb","d":"hiển thị, tiết lộ","e":"Christopher’s hand-wringing and nail-biting evince how nervous he is about the upcoming English test.","ev":"Việc Christopher vặn tay và cắn móng tay cho thấy anh ấy lo lắng như thế nào về bài kiểm tra tiếng Anh sắp tới.","k":"evince"},{"t":"Thwart","p":"verb","d":"Chặn hoặc cản trở điều gì đó tiêu cực","e":"They worked to thwart the enemy’s plans.","ev":"Họ làm việc ngăn chặn kế hoạch của kẻ thù.","k":"thwart"},{"t":"Sap","p":"verb","d":"tiêu hao (ví dụ: năng lượng)","e":"our energy is being sapped by bureaucrats and politicians","ev":"năng lượng của chúng ta đang bị các quan chức và chính trị gia làm hao mòn","k":"sap"},{"t":"Obscure","p":"adjective/verb","d":"không rõ ràng, ẩn một phần","e":"Because he was standing in the shadows, his features were obscure.","ev":"Vì đứng trong bóng tối nên đường nét của anh ta bị che khuất.","k":"obscure"},{"t":"Superficial","p":"adjective","d":"nông, trên bề mặt","e":"Their relationship was superficial, lacking depth and emotional connection.","ev":"Mối quan hệ của họ rất hời hợt, thiếu chiều sâu và sự kết nối tình cảm.","k":"superficial"},{"t":"Adaptation","p":"noun","d":"Một sự thay đổi được thực hiện phù hợp với hoàn cảnh mới","e":"His adaptation to the new environment was impressive.","ev":"Sự thích nghi của anh ấy với môi trường mới thật ấn tượng.","k":"adaptation"},{"t":"Trivial","p":"adjective","d":"Tầm thường","e":"He dismissed the issue as trivial.","ev":"Ông coi vấn đề này là tầm thường.","k":"trivial"},{"t":"Lineage","p":"noun","d":"Xuất thân từ một tổ tiên chung hoặc người tiền nhiệm","e":"Her royal lineage dates back centuries.","ev":"Dòng dõi hoàng gia của cô có từ nhiều thế kỷ trước.","k":"lineage"},{"t":"Indelible","p":"adjective","d":"Đáng nhớ; không thể quên","e":"The trip left an indelible mark on her.","ev":"Chuyến đi đã lại dấu ấn khó phai mờ trong cô.","k":"indelible"},{"t":"Check","p":"verb","d":"hạn chế, kiểm soát hoặc giảm bớt","e":"They have begun to vaccinate children in an attempt to check the spread of the disease.","ev":"Họ đã bắt đầu tiêm chủng cho trẻ em nhằm kiểm soát sự lây lan của căn bệnh này.","k":"check"},{"t":"Conspicuous","p":"adjective","d":"Rõ ràng có thể nhìn thấy; đáng chú ý","e":"The error was conspicuous in the final report.","ev":"Lỗi này rất dễ thấy trong báo cáo cuối cùng.","k":"conspicuous"},{"t":"Impede","p":"verb","d":"gây khó khăn cho ai đó hoặc cái gì đó, dẫn đến sự chậm trễ","e":"The heavy traffic impeded their progress, delaying their arrival.","ev":"Giao thông đông đúc đã cản trở bước tiến của họ, khiến việc đến nơi của họ bị trì hoãn.","k":"impede"},{"t":"Recant","p":"verb","d":"rút lại","e":"After much consideration, he decided to recant his earlier statement.","ev":"Sau nhiều cân nhắc, anh đã quyết định thu hồi tuyên bố trước đó của mình.","k":"recant"},{"t":"Innovative","p":"adjective","d":"mới và khác biệt","e":"The company's innovative products were a success, setting new standards for the industry and attracting a loyal customer base.","ev":"Các sản phẩm đổi mới của công ty đã thành công, đặt ra các tiêu chuẩn mới cho ngành và thu hút lượng khách hàng trung thành.","k":"innovative"},{"t":"Excavation","p":"noun","d":"Quá trình đào lên, thường là một di tích lịch sử","e":"The excavation revealed ancient artifacts.","ev":"Cuộc khai quật đã tiết lộ những hiện vật cổ xưa.","k":"excavation"},{"t":"Palpable","p":"adjective","d":"Theo nghĩa đen, có thể chạm vào được; thường được sử dụng mô tả một cảm giác rất mãnh liệt. Rõ ràng, hiển nhiên","e":"There was a palpable sense of excitement in the room.","ev":"Trong phòng tràn ngập cảm giác hưng phấn.","k":"palpable"},{"t":"Multifaceted","p":"adjective","d":"Có nhiều khía cạnh","e":"He is a multifaceted individual with many talents.","ev":"Anh ấy là một cá nhân đa diện và có nhiều tài năng.","k":"multifaceted"},{"t":"Undermine","p":"verb","d":"Làm suy yếu","e":"The scandal undermined his reputation, making it difficult for him to regain the public's trust.","ev":"Vụ bê bối đã làm suy yếu danh tiếng của anh, khiến anh khó lấy lại được lòng tin của công chúng.","k":"undermine"}]},{"n":"Buổi 13","c":[{"t":"Proponent","p":"noun","d":"Người đề xuất, ủng hộ","e":"She is a strong proponent of environmental protection and sustainability.","ev":"Cô ấy là một người ủng hộ mạnh mẽ cho việc bảo vệ môi trường và sự bền vững.","k":"proponent"},{"t":"Monetize","p":"verb","d":"kiếm tiền từ","e":"She found a way to monetize her hobby.","ev":"Cô đã tìm ra cách kiếm tiền từ sở thích của mình.","k":"monetize"},{"t":"Installation","p":"noun","d":"Triển lãm nghệ thuật bao gồm các đồ vật lớn được đặt trong không gian công cộng","e":"The installation drew crowds at the gallery.","ev":"Việc sắp đặt đã thu hút đám đông tại phòng trưng bày.","k":"installation"},{"t":"Validate","p":"verb","d":"xác nhận, ủng hộ, chứng thực","e":"Yoko’s chemistry lab partner was asleep during the experiment and could not validate the accuracy of her methods.","ev":"Đối tác trong phòng thí nghiệm hóa học của Yoko đã ngủ trong suốt cuộc thí nghiệm và không thể xác nhận tính chính xác của phương pháp của cô ấy.","k":"validate"},{"t":"Engender","p":"verb","d":"mang lại, tạo ra, gây ra","e":"During the Olympics, the victories of U.S. athletes engender a patriotic spirit among Americans.","ev":"Trong Thế vận hội, chiến thắng của các vận động viên Hoa Kỳ đã khơi dậy tinh thần yêu nước của người Mỹ.","k":"engender"},{"t":"Underscore","p":"verb","d":"nhấn mạnh tầm quan trọng của một cái gì đó","e":"He underscored the importance of education.","ev":"Ông nhấn mạnh tầm quan trọng của giáo dục.","k":"underscore"},{"t":"Tedious","p":"adjective","d":"buồn tẻ, nhàm chán","e":"As time passed and the history professor continued to drone on and on, the lecture became increasingly tedious.","ev":"Thời gian trôi qua và giáo sư lịch sử tiếp tục lải nhải liên tục, bài giảng ngày càng trở nên tẻ nhạt.","k":"tedious"},{"t":"Confound","p":"verb","d":"làm bối rối","e":"MacGuyver confounded the policemen pursuing him by covering his tracks.","ev":"Anh đã làm cho cảnh sát bối rối và trốn thoát.","k":"confound"},{"t":"Outmoded","p":"adjective","d":"Không còn thời trang nữa; lỗi thời","e":"The design is considered outmoded by today's standards.","ev":"Thiết kế này được coi là lỗi thời so với tiêu chuẩn ngày nay.","k":"outmoded"},{"t":"Adamant","p":"adjective","d":"kiên quyết, cứng đầu","e":"She remained adamant about her decision to move forward with the project.","ev":"Cô kiên quyết về quyết định tiếp tục thực hiện dự án.","k":"adamant"},{"t":"Arrest","p":"verb","d":"ngăn chặn","e":"The police arrested the spread of the disease with strict quarantine measures.","ev":"Cảnh sát đã ngăn chặn sự lây lan của dịch bệnh bằng các biện pháp cách ly nghiêm ngặt.","k":"arrest"},{"t":"Tally","p":"noun","d":"Bản ghi lại, kiểm kê","e":"She kept a tally of all the expenses.","ev":"Cô ấy giữ một bản kiểm kê tất cả các chi phí.","k":"tally"},{"t":"Circumvent","p":"verb","d":"Tránh, lách (luật)","e":"She tried to circumvent the rules.","ev":"Cô ấy cố gắng lách luật.","k":"circumvent"},{"t":"Nuance","p":"noun","d":"sắc thái","e":"The nuances of her expression revealed her true feelings about the situation.","ev":"Những sắc thái trong biểu cảm của cô ấy tiết lộ cảm xúc thật sự của cô về tình huống.","k":"nuance"},{"t":"Stipulate","p":"verb","d":"yêu cầu hoặc chỉ định như một phần của thỏa thuận","e":"The contract stipulated that payments must be made on time.","ev":"Hợp đồng quy định rằng việc thanh toán phải được thực hiện đúng thời hạn.","k":"stipulate"},{"t":"Facility","p":"noun","d":"Khả năng thực hiện điều gì đó một cách dễ dàng","e":"He had a facility for languages","ev":"Anh ta có khả năng học ngoại ngữ.","k":"facility"},{"t":"Copious","p":"adjective","d":"dồi dào","e":"The researcher took copious notes during the lecture to ensure she didn't miss any details.","ev":"Nhà nghiên cứu đã ghi chép rất nhiều trong suốt bài giảng đảm bảo không bỏ lỡ chi tiết nào.","k":"copious"},{"t":"Peripheral","p":"adjective","d":"Ngoại vi","e":"The peripheral devices were not functioning correctly with the computer.","ev":"Các thiết bị ngoại vi đã không hoạt động chính xác với máy tính.","k":"peripheral"},{"t":"Provocative","p":"adjective","d":"Khiêu khích","e":"His provocative remarks sparked a heated debate.","ev":"Lời nhận xét đầy khiêu khích của ông đã làm dấy lên một cuộc tranh luận sôi nổi.","k":"provocative"},{"t":"Scheme","p":"noun","d":"Kế hoạch","e":"He devised a scheme to win the contest.","ev":"Anh ta nghĩ ra một kế hoạch giành chiến thắng trong cuộc thi.","k":"scheme"}]},{"n":"Buổi 14","c":[{"t":"Preclude","p":"verb","d":"ngăn chặn","e":"His lack of experience does not preclude him from applying for the job.","ev":"Thiếu kinh nghiệm của anh không ngăn cản anh nộp đơn xin việc.","k":"preclude"},{"t":"Synchronize","p":"verb","d":"đồng bộ hoá","e":"The dancers synchronized their movements perfectly.","ev":"Các vũ công đã đồng bộ hóa các động tác của họ một cách hoàn hảo.","k":"synchronize"},{"t":"Register","p":"verb","d":"ghi lại, hiển thị hoặc thể hiện một cái gì đó","e":"Her face registered disapproval","ev":"Vẻ mặt cô tỏ vẻ không hài lòng","k":"register"},{"t":"Nurture","p":"verb","d":"hỗ trợ sự phát triển của","e":"Although Serena had never watered the plant, which was about to die, Javier was able to nurture it back to life.","ev":"Mặc dù Serena chưa bao giờ tưới nước cho cái cây sắp chết nhưng Javier vẫn có thể nuôi dưỡng nó sống lại.","k":"nurture"},{"t":"Hobble","p":"verb","d":"Ngăn chặn, cản trở","e":"A long list of amendments have hobbled the new legislation.","ev":"Một danh sách dài các sửa đổi đã cản trở luật mới.","k":"hobble"},{"t":"Incongruous","p":"adjective","d":"Không phù hợp","e":"His casual attire was incongruous with the formal event.","ev":"Trang phục giản dị của anh ấy không phù hợp với sự kiện trang trọng.","k":"incongruous"},{"t":"Transcend","p":"verb","d":"vượt lên trên những giới hạn bình thường","e":"Her work transcends traditional boundaries.","ev":"Công việc của cô vượt qua ranh giới truyền thống.","k":"transcend"},{"t":"Mundane","p":"adjective","d":"trần tục, tầm thường nhỏ nhặt","e":"He is more concerned with the mundane issues of day-to-day life than with spiritual topics.","ev":"Ông quan tâm đến những vấn đề trần tục của cuộc sống hàng ngày hơn là những chủ đề tâm linh.","k":"mundane"},{"t":"Grapple With","p":"verb","d":"vật lộn (suy nghĩ)","e":"The philosopher grappled with the complex ethical implications of artificial intelligence.","ev":"Nhà triết học vật lộn với những tác động đạo đức phức tạp của trí tuệ nhân tạo.","k":"grapple with"},{"t":"Disposition","p":"noun","d":"Tính cách hoặc đặc điểm vốn có","e":"She has a sunny disposition that brightens everyone's day.","ev":"Cô ấy có tính cách vui vẻ, có thể làm bừng sáng cả ngày của mọi người.","k":"disposition"},{"t":"Predatory","p":"adjective","d":"săn mồi","e":"The predatory animal stalked its prey.","ev":"Động vật săn mồi rình rập con mồi.","k":"predatory"},{"t":"Contrive","p":"verb","d":"Nghĩ ra, xoay xở, trù tính","e":"The prisoners contrived a way to escape.","ev":"Các tù nhân tìm cách trốn thoát.","k":"contrive"},{"t":"Intermediate","p":"adjective","d":"Đứng giữa hai thứ","e":"This course is for intermediate learners.","ev":"Khóa học này dành cho người học ở trình độ trung cấp.","k":"intermediate"},{"t":"Manifestation","p":"noun","d":"Sự thể hiện","e":"The sculpture was a manifestation of his creativity.","ev":"Tác phẩm điêu khắc là sự thể hiện sự sáng tạo của ông.","k":"manifestation"},{"t":"Orientation","p":"noun","d":"Sở thích hoặc sự thích thú, thiên hướng","e":"She has an orientation towards creative work.","ev":"Cô ấy có định hướng về công việc sáng tạo.","k":"orientation"},{"t":"Elusive","p":"adjective","d":"khó nắm bắt","e":"Her thoughts were elusive, hard to pin down.","ev":"Những suy nghĩ của cô ấy rất khó nắm bắt.","k":"elusive"},{"t":"Watershed","p":"noun","d":"Một bước ngoặt","e":"The new policy marked a watershed moment in their history.","ev":"Chính sách mới đã đánh dấu một bước ngoặt trong lịch sử của họ.","k":"watershed"},{"t":"Eccentric","p":"adjective","d":"không phổ biến, kỳ lạ","e":"His eccentric behavior often made him the center of attention, but also made it difficult to maintain friendships.","ev":"Hành vi lập dị của anh thường khiến anh trở thành trung tâm của sự chú ý nhưng cũng gây khó khăn cho việc duy trì tình bạn.","k":"eccentric"},{"t":"Consumption","p":"noun","d":"Sự tiêu thụ","e":"Consumption of intoxicating beverages is not permitted on these premises.","ev":"Việc uống rượu bị cấm trong khu vực này.","k":"consumption"},{"t":"Coin","p":"verb","d":"phát minh (ví dụ: tạo ra một cụm từ)","e":"He coined the term \"user interface.\"","ev":"Ông đặt ra thuật ngữ \"giao diện người dùng\".","k":"coin"}]},{"n":"Buổi 15","c":[{"t":"Antithetical","p":"adjective","d":"Đặc trưng bởi sự tương phản cực độ,","e":"Their views are antithetical to each other.","ev":"Quan điểm của họ trái ngược nhau.","k":"antithetical"},{"t":"Exposure","p":"noun","d":"Phơi bày, xuất hiện trên truyền thông","e":"The media exposure helped the company gain recognition.","ev":"Việc xuất hiện trên các phương tiện truyền thông đã giúp công ty được công nhận.","k":"exposure"},{"t":"Doctor","p":"verb","d":"can thiệp vào","e":"The hacker doctored the data to support their theory.","ev":"Hacker đã chỉnh sửa dữ liệu hỗ trợ lý thuyết của họ.","k":"doctor"},{"t":"Supplement","p":"verb/noun","d":"(n.) Sự bổ sung hoặc tăng cường; (v.) Thêm vào","e":"He took a vitamin supplement daily.","ev":"Anh ấy uống bổ sung vitamin hàng ngày.","k":"supplement"},{"t":"Supplant","p":"verb","d":"thay thế","e":"They hoped to supplant the old technology with something more efficient.","ev":"Họ hy vọng thay thế công nghệ cũ bằng một cái gì đó hiệu quả hơn.","k":"supplant"},{"t":"Ineluctable","p":"adjective","d":"Không thể tránh khỏi; không thể tránh khỏi","e":"The passage of time is ineluctable.","ev":"Thời gian trôi qua là điều không thể tránh khỏi.","k":"ineluctable"},{"t":"Relevant/Irrelevant","p":"adjective","d":"Liên quan / không liên quan","e":"The example was relevant to the discussion.","ev":"Ví dụ có liên quan đến cuộc thảo luận.","k":"relevant/irrelevant"},{"t":"Uniform","p":"adjective","d":"Hằng số, không thay đổi","e":"The laws for adopting a child are not uniform among the states.","ev":"Luật nhận con nuôi không thống nhất giữa các bang.","k":"uniform"},{"t":"Afford","p":"verb","d":"Cấp (ví dụ: một cơ hội)","e":"The new law will afford protection to employees.","ev":"Luật mới sẽ đủ khả năng bảo vệ người lao động.","k":"afford"},{"t":"Concede","p":"verb","d":"Thừa nhận","e":"Andrew had to concede that what his mother said about Diana made sense.","ev":"Andrew phải thừa nhận rằng những gì mẹ anh nói về Diana đều có lý.","k":"concede"},{"t":"Ephemeral","p":"adjective","d":"Ngắn ngủn","e":"The beauty of the sunset was ephemeral.","ev":"Vẻ đẹp của hoàng hôn thật ngắn ngủi.","k":"ephemeral"},{"t":"Reservations","p":"noun","d":"Nghi ngờ","e":"I have some reservations about the plan.","ev":"Tôi có một số nghi ngờ về kế hoạch này.","k":"reservations"},{"t":"Delusional","p":"adjective","d":"Có niềm tin hoặc ý kiến ​​sai lầm hoặc không thực tế.","e":"He was delusional in thinking he could win the lottery without buying a ticket.","ev":"Anh ta bị ảo tưởng khi nghĩ rằng mình có thể trúng số mà không cần mua vé.","k":"delusional"},{"t":"incredulous, \nincredulity","p":"adjective, noun","d":"không tin, \nsự hoài nghi","e":"He was incredulous when he heard the news.","ev":"Anh ta tỏ ra hoài nghi khi nghe tin tức.","k":"incredulous, incredulity"},{"t":"Venerate","p":"verb","d":"tôn trọng, tôn kính, sùng kính","e":"The tribute to John Lennon sought to venerate his music, his words, and his legend.","ev":"Việc tưởng nhớ John Lennon nhằm tôn vinh âm nhạc, lời nói và huyền thoại của ông.","k":"venerate"},{"t":"Denounce","p":"verb","d":"chỉ trích công khai","e":"The senator denounced her opponent as a greedy politician.","ev":"Thượng nghị sĩ tố cáo đối thủ của bà là một chính trị gia tham lam.","k":"denounce"},{"t":"Skeptically","p":"adverb","d":"Với sự nghi ngờ hoặc do dự.","e":"He looked at the proposal skeptically, unsure of its feasibility.","ev":"Anh ta nhìn đề xuất này một cách hoài nghi, không chắc chắn về tính khả thi của nó.","k":"skeptically"},{"t":"melancholy","p":"noun/adjective","d":"u sầu","e":"A sense of melancholy hung over the town after the festival ended.","ev":"Một cảm giác u buồn bao trùm thị trấn sau khi lễ hội kết thúc.","k":"melancholy"},{"t":"Discount","p":"verb","d":"Quyết định rằng điều gì đó hoặc ai đó không đáng xem xét hoặc chú ý, coi nhẹ","e":"She discounted his opinion because of his lack of experience.","ev":"Cô ấy bác bỏ ý kiến ​​​​của anh ấy vì anh ấy thiếu kinh nghiệm.","k":"discount"},{"t":"divergent","p":"adjective","d":"khác nhau","e":"Their divergent opinions led to a heated discussion.","ev":"Ý kiến khác nhau của họ đã dẫn đến một cuộc thảo luận sôi nổi.","k":"divergent"}]},{"n":"Buổi 16","c":[{"t":"Contrivance","p":"noun","d":"Một vật được tạo ra một cách khéo léo và sáng tạo phục vụ một mục đích cụ thể; việc sử dụng kỹ năng tạo ra một cái gì đó hoặc mang lại một kết quả.","e":"The story was full of plot contrivances that strained credibility.","ev":"Câu chuyện chứa đầy những tình tiết phức tạp làm giảm uy tín.","k":"contrivance"},{"t":"unwarranted","p":"adjective","d":"thiếu lý do chính đáng; không cần thiết","e":"They denounced the investigation as an unwarranted interference with their business.","ev":"Họ tố cáo cuộc điều tra là sự can thiệp không chính đáng vào hoạt động kinh doanh của họ.","k":"unwarranted"},{"t":"Equivocal","p":"adjective","d":"Không phân minh","e":"His equivocal response left everyone unsure about his true intentions.","ev":"Phản ứng không rõ ràng của anh ấy khiến mọi người không chắc chắn về ý định thực sự của anh.","k":"equivocal"},{"t":"empiric(al)","p":"adjective","d":"thực nghiệm","e":"The research is based on empirical evidence gathered from experiments.","ev":"Nghiên cứu này dựa trên bằng chứng thực nghiệm thu thập từ các cuộc thí nghiệm.","k":"empiric(al)"},{"t":"Supersede","p":"verb","d":"Thay thế (một người hoặc vật trước đây có thẩm quyền hoặc quyền sử dụng); thay thế.","e":"The new policy will supersede the old one starting next month.","ev":"Chính sách mới sẽ thay thế chính sách cũ bắt đầu từ tháng tới.","k":"supersede"},{"t":"profound, \nprofundity","p":"adjective, noun","d":"sâu, \nsự sâu sắc","e":"Her profound insights into human nature were well-received by the audience.","ev":"Những hiểu biết sâu sắc của cô về bản chất con người đã được khán giả đón nhận nồng nhiệt.","k":"profound, profundity"},{"t":"Contemptuously","p":"adverb","d":"Một cách khinh bỉ thể hiện sự khinh thường","e":"She glanced contemptuously at the messy room.","ev":"Cô khinh thường liếc nhìn căn phòng bừa bộn.","k":"contemptuously"},{"t":"Capitalize On","p":"verb","d":"tận dụng một tình huống hoặc cơ hội cụ thể.","e":"The company capitalized on the growing demand for electric cars.","ev":"Công ty tận dụng nhu cầu ngày càng tăng về ô tô điện.","k":"capitalize on"},{"t":"Intimate","p":"adjective","d":"Quen biết chặt chẽ; quen thuộc, gần gũi; riêng tư và cá nhân.","e":"They shared an intimate conversation about their future plans.","ev":"Họ đã trò chuyện thân mật về kế hoạch tương lai của mình.","k":"intimate"},{"t":"Pivotal","p":"adjective","d":"Có tầm quan trọng cốt yếu liên quan đến sự phát triển hoặc thành công của một cái gì đó khác.","e":"The invention of the internet was a pivotal moment in human history.","ev":"Việc phát minh ra Internet là một thời điểm quan trọng trong lịch sử loài người.","k":"pivotal"},{"t":"Amplify","p":"verb","d":"Làm cho cái gì đó to hơn hoặc mạnh hơn; tăng kích thước hoặc tác dụng của một cái gì đó","e":"The musician used a microphone to amplify his voice during the concert.","ev":"Nhạc sĩ đã sử dụng micro khuếch đại giọng hát của mình trong buổi hòa nhạc.","k":"amplify"},{"t":"Extraneous","p":"adjective","d":"không liên quan, thêm, không cần thiết","e":"Personal political ambitions should always remain extraneous to legislative policy, but, unfortunately, they rarely are.","ev":"Tham vọng chính trị cá nhân luôn luôn không liên quan đến chính sách lập pháp, nhưng thật không may, chúng hiếm khi như vậy.","k":"extraneous"},{"t":"Contingent On","p":"adjective","d":"Tùy thuộc vào cơ hội; chỉ xảy ra hoặc tồn tại nếu (một số trường hợp nhất định) xảy ra; phụ thuộc vào.","e":"The success of the project is contingent on securing adequate funding.","ev":"Sự thành công của dự án phụ thuộc vào việc đảm bảo đủ nguồn vốn.","k":"contingent on"},{"t":"Heterotrophic","p":"adjective","d":"Dị dưỡng","e":"Humans are heterotrophic organisms, relying on other organisms for food.","ev":"Con người là sinh vật dị dưỡng, sống dựa vào sinh vật khác có thức ăn.","k":"heterotrophic"},{"t":"Unyielding","p":"adjective","d":"Kiên quyết, không lung lay","e":"She remained unyielding in her opposition to the plan.","ev":"Cô vẫn kiên quyết phản đối kế hoạch này.","k":"unyielding"},{"t":"Inexplicable","p":"adjective","d":"Không thể giải thích hoặc giải thích được.","e":"The sudden disappearance of the files was inexplicable.","ev":"Sự biến mất đột ngột của các tập tin là không thể giải thích được.","k":"inexplicable"},{"t":"Pugnacious","p":"adjective","d":"hay gây gổ","e":"Aaron’s pugnacious nature led him to start several barroom brawls each month.","ev":"Bản tính hiếu chiến của Aaron đã khiến anh ta bắt đầu nhiều cuộc ẩu đả trong quán bar mỗi tháng.","k":"pugnacious"},{"t":"Inadvertent","p":"adjective","d":"ngoài ý muốn.","e":"An inadvertent error caused the data loss.","ev":"Một lỗi vô ý gây ra mất dữ liệu.","k":"inadvertent"},{"t":"Propagate","p":"verb","d":"nhân lên, trải rộng ra","e":"Rumors of Paul McCartney’s demise propagated like wildfire throughout the world.","ev":"Tin đồn về cái chết của Paul McCartney lan truyền như cháy rừng khắp thế giới.","k":"propagate"},{"t":"Corollary","p":"noun","d":"cái gì đó là kết quả của cái gì khác","e":"Unfortunately, violence is the inevitable corollary of such a revolutionary change in society.","ev":"Thật không may, bạo lực là hệ quả tất yếu của một sự thay đổi mang tính cách mạng như vậy trong xã hội.","k":"corollary"}]},{"n":"Buổi 17","c":[{"t":"Elide","p":"verb","d":"Bỏ qua","e":"In casual speech, people often elide the 't' in 'often'.","ev":"Trong cách nói thông thường, người ta thường bỏ chữ 't' trong 'thường'.","k":"elide"},{"t":"Reverential","p":"adjective","d":"Về bản chất, do hoặc đặc trưng bởi sự tôn kính.","e":"He spoke in a reverential tone about his mentor.","ev":"Anh ấy nói với giọng tôn kính về người thầy của mình.","k":"reverential"},{"t":"Notional","p":"adjective","d":"(tính từ) Chỉ tồn tại trên lý thuyết hoặc dưới dạng gợi ý, ý tưởng; tưởng tượng.","e":"The notional value of the company's assets was much higher than their actual market value.","ev":"Giá trị danh nghĩa của tài sản công ty cao hơn nhiều so với giá trị thị trường thực tế của chúng.","k":"notional"},{"t":"Restive","p":"adjective","d":"chống cự, bướng bỉnh, thiếu kiên nhẫn, không yên, khó bảo","e":"The restive audience pelted the band with mud and yelled nasty comments.","ev":"Những khán giả phản kháng đã ném bùn vào ban nhạc và hét lên những bình luận khó chịu.","k":"restive"},{"t":"Vacillating","p":"adjective","d":"Dao động giữa các ý kiến ​​hoặc hành động khác nhau; không kiên quyết.","e":"His vacillating stance on the issue confused his supporters.","ev":"Lập trường bỏ trống của ông về vấn đề này khiến những người ủng hộ ông bối rối.","k":"vacillating"},{"t":"Tentative","p":"adjective","d":"chưa được xác nhận, có thể thay đổi","e":"The agreement was tentative and could be changed, as both parties were still negotiating the terms.","ev":"Thỏa thuận này chỉ là dự kiến ​​và có thể thay đổi vì cả hai bên vẫn đang đàm phán các điều khoản.","k":"tentative"},{"t":"Disinterested","p":"adjective","d":"Không bị ảnh hưởng bởi những cân nhắc về lợi ích cá nhân; có hoặc cảm thấy không quan tâm đến một cái gì đó Không có lợi","e":"A disinterested third party mediated the dispute.","ev":"Một bên thứ ba không có lợi ích đã đứng ra hòa giải tranh chấp.","k":"disinterested"},{"t":"Longitudinal Study","p":"noun","d":"Một thiết kế nghiên cứu bao gồm việc quan sát lặp đi lặp lại các biến số giống nhau trong thời gian dài.","e":"The longitudinal study tracked participants' health over two decades.","ev":"Nghiên cứu theo chiều dọc theo dõi sức khỏe của người tham gia trong hơn hai thập kỷ.","k":"longitudinal study"},{"t":"stately","p":"adjective","d":"có dáng vẻ trang nghiêm, thong thả, cao thượng; hùng vĩ về dáng vẻ và vẻ bề ngoài.","e":"a stately sight to behold","ev":"một cảnh tượng trang nghiêm chiêm ngưỡng","k":"stately"},{"t":"Irrefutable","p":"adjective","d":"Không thể phủ nhận hay bác bỏ.","e":"The evidence presented in court was irrefutable.","ev":"Những bằng chứng được đưa ra trước tòa là không thể chối cãi.","k":"irrefutable"},{"t":"Misanthropic","p":"adjective","d":"(tính từ) Ghét loài người và xa lánh xã hội loài người.","e":"His misanthropic views made it difficult for him to maintain friendships.","ev":"Quan điểm lệch lạc của anh ấy khiến anh ấy khó duy trì tình bạn.","k":"misanthropic"},{"t":"Demarcated","p":"verb/adjective","d":"(động từ) Đặt ranh giới hoặc giới hạn của; tách biệt hoặc phân biệt với. Phân vùng ranh giới","e":"The property was demarcated by a white fence.","ev":"Khu đất được phân giới bằng hàng rào màu trắng.","k":"demarcated"},{"t":"Precede","p":"verb","d":"Đến trước (cái gì đó) đúng lúc; đứng trước về thứ tự hoặc vị trí.","e":"A brief introduction preceded the main presentation.","ev":"Phần giới thiệu ngắn gọn trước phần trình bày chính.","k":"precede"},{"t":"Meager","p":"adjective","d":"thiếu kích thước hoặc chất lượng","e":"My meager portion of food did nothing to satisfy my appetite.","ev":"Phần thức ăn ít ỏi của tôi không làm thỏa mãn cơn thèm ăn của tôi.","k":"meager"},{"t":"Outlier","p":"noun","d":"Một người hoặc vật khác với tất cả các thành viên khác của một nhóm hoặc tập hợp cụ thể.","e":"In the data set, there was one outlier that skewed the results.","ev":"Trong tập dữ liệu, có một ngoại lệ làm sai lệch kết quả.","k":"outlier"},{"t":"Regard","p":"verb/noun","d":"Xem xét hoặc nghĩ về (ai đó hoặc cái gì đó) theo một cách cụ thể; chú ý đến hoặc quan tâm đến một cái gì đó.","e":"He is highly regarded by his colleagues.","ev":"Anh được đồng nghiệp đánh giá cao.","k":"regard"},{"t":"Placate","p":"verb","d":"Xoa dịu","e":"She offered a small gift to placate her friend after their argument.","ev":"Cô đã tặng một món quà nhỏ xoa dịu người bạn của mình sau cuộc tranh cãi.","k":"placate"},{"t":"Malign","p":"verb/adjective","d":"nói xấu vu vu","e":"She was known to malign her enemies, spreading rumors and lies about them to ruin their reputations.","ev":"Cô nổi tiếng là hay nói xấu kẻ thù của mình, tung tin đồn và dối trá về họ hủy hoại danh tiếng của họ.","k":"malign"},{"t":"Nonsensical","p":"adjective","d":"Không có ý nghĩa; không có ý nghĩa gì","e":"The explanation was nonsensical and confused everyone.","ev":"Lời giải thích thật vô lý và khiến mọi người bối rối.","k":"nonsensical"},{"t":"Intercede In","p":"verb","d":"can thiệp thay mặt cho người khác.","e":"She interceded in the argument to help resolve it.","ev":"Cô ấy đã can thiệp vào cuộc tranh luận giúp giải quyết nó.","k":"intercede in"}]},{"n":"Buổi 18","c":[{"t":"Invaluable","p":"adjective","d":"Quý giá, vô giá","e":"an invaluable source of information","ev":"Một thông tin quý giá, quan trọng","k":"invaluable"},{"t":"In Turn","p":"Phrase","d":"Liên tiếp; cái này đến cái khác; là kết quả của một cái gì đó trong một chuỗi các sự kiện.","e":"She spoke to each of the guests in turn.","ev":"Cô lần lượt nói chuyện với từng vị khách.","k":"in turn"},{"t":"Promulgate","p":"verb","d":"tuyên bố, truyền bá","e":"The film professor promulgated that both in terms of sex appeal and political intrigue, Sean Connery’s James Bond was superior to Roger Moore’s.","ev":"Giáo sư điện ảnh tuyên bố rằng cả về độ hấp dẫn giới tính lẫn mưu đồ chính trị, James Bond của Sean Connery đều vượt trội hơn của Roger Moore.","k":"promulgate"},{"t":"immaterial","p":"adjective","d":"không cần thiết, không liên quan","e":"the source of a claim is immaterial: it has no direct bearing on whether the claim is true.","ev":"nguồn của một tuyên bố là không quan trọng: nó không ảnh hưởng trực tiếp đến việc tuyên bố đó có đúng hay không.","k":"immaterial"},{"t":"Protractor","p":"noun","d":"Thước đo góc","e":"In geometry class, we used a protractor to measure angles.","ev":"Trong lớp hình học, chúng em dùng thước đo góc đo góc.","k":"protractor"},{"t":"Deferential","p":"adjective","d":"Tôn trọng, tôn kính","e":"His deferential attitude toward her made her more confident in her ability to run the company.","ev":"Thái độ tôn trọng của anh đối với cô khiến cô tự tin hơn vào khả năng điều hành công ty của mình.","k":"deferential"},{"t":"Impugn","p":"verb","d":"Nghi ngờ, công kích","e":"The lawyer impugned the witness's credibility during cross-examination.","ev":"Luật sư đã nghi ngờ độ tin cậy của nhân chứng trong quá trình thẩm vấn chéo.","k":"impugn"},{"t":"Tangible","p":"adjective","d":"thật và có thể nhìn thấy hoặc chạm vào được, hữu hình","e":"The benefits of the program were tangible and measurable, improving the lives of countless people.","ev":"Lợi ích của chương trình là hữu hình và có thể đo lường được, giúp cải thiện cuộc sống của vô số người.","k":"tangible"},{"t":"Apprise","p":"verb","d":"thông báo","e":"Please apprise me of any updates to the project timeline.","ev":"Vui lòng thông báo cho tôi về bất kỳ cập nhật nào về dòng thời gian của dự án.","k":"apprise"},{"t":"Proclivity","p":"noun","d":"một khuynh hướng mạnh mẽ đối với một cái gì đó","e":"In a sick twist of fate, Harold’s childhood proclivity for torturing small animals grew into a desire to become a surgeon.","ev":"Trong một vòng xoay bệnh hoạn của số phận, thiên hướng tra tấn động vật nhỏ thời thơ ấu của Harold đã phát triển thành mong muốn trở thành bác sĩ phẫu thuật.","k":"proclivity"},{"t":"Uncompromising","p":"adjective","d":"Không khoan nhượng, không nhượng bộ","e":"His uncompromising stance made negotiations difficult.","ev":"Lập trường không khoan nhượng của ông khiến các cuộc đàm phán trở nên khó khăn.","k":"uncompromising"},{"t":"Forestall","p":"verb","d":"ngăn chặn, cản trở, trì hoãn, ngăn chặn trước đó","e":"I forestalled the cold I was getting by taking plenty of vitamin C pills and wearing a scarf.","ev":"Tôi đã ngăn ngừa cảm lạnh bằng cách uống nhiều viên vitamin C và quàng khăn quàng cổ.","k":"forestall"},{"t":"Attrition","p":"noun","d":"(danh từ) Quá trình làm giảm dần sức mạnh hoặc hiệu quả của ai đó hoặc điều gì đó thông qua sự tấn công hoặc áp lực liên tục. Tiêu hao.","e":"Attrition War","ev":"Chiến tranh tiêu hao","k":"attrition"},{"t":"Disseminate","p":"verb","d":"Phổ biến","e":"The organization aims to disseminate information about health and wellness.","ev":"Tổ chức này nhằm mục đích truyền bá thông tin về sức khỏe và sự lành mạnh.","k":"disseminate"},{"t":"Mandatory","p":"adjective","d":"bắt buộc","e":"Attendance at the meeting is mandatory for all staff members.","ev":"Việc tham dự cuộc họp là bắt buộc đối với tất cả nhân viên.","k":"mandatory"},{"t":"Jettison","p":"verb","d":"Vứt bỏ, loại bỏ","e":"The crew had to jettison excess cargo to lighten the ship.","ev":"Thủy thủ đoàn đã phải vứt bớt hàng hóa dư thừa làm nhẹ tàu.","k":"jettison"},{"t":"Behold","p":"verb","d":"Nhìn thấy hoặc quan sát (một vật hoặc một người, đặc biệt là một vật hoặc vật đáng chú ý hoặc ấn tượng).","e":"The sunset was a sight to behold.","ev":"Hoàng hôn là một cảnh tượng đáng chú ý.","k":"behold"},{"t":"Litany","p":"noun","d":"(danh từ) Một loạt lời thỉnh cầu được sử dụng trong các buổi lễ nhà thờ; một chuỗi độc tấu hoặc lặp đi lặp lại tẻ nhạt","e":"She recited a litany of complaints about the service.","ev":"Cô kể lại một loạt lời phàn nàn về dịch vụ.","k":"litany"},{"t":"Repository","p":"noun","d":"Nơi hoặc nơi chứa đựng mọi thứ đang hoặc có thể được cất giữ.","e":"The library serves as a repository of historical documents.","ev":"Thư viện phục vụ như một kho lưu trữ các tài liệu lịch sử.","k":"repository"},{"t":"Exclusive To","p":"Phrase","d":"Giới hạn ở một người, nhóm hoặc khu vực cụ thể.","e":"This offer is exclusive to our premium members.","ev":"Ưu đãi này chỉ dành riêng cho các thành viên cao cấp của chúng tôi.","k":"exclusive to"}]},{"n":"Buổi 19","c":[{"t":"Comprehensive","p":"adjective","d":"đầy đủ","e":"She sent me a comprehensive list of the ingredients needed to cook rabbit soufflé.","ev":"Cô ấy gửi cho tôi một danh sách đầy đủ các nguyên liệu cần thiết nấu món soufflé thỏ.","k":"comprehensive"},{"t":"Endure","p":"verb","d":"tiếp tục tồn tại trong một thời gian dài","e":"The political system established in 1400 endured until about 1650.","ev":"Hệ thống chính trị được thành lập năm 1400 tồn tại cho đến khoảng năm 1650.","k":"endure"},{"t":"A Profusion Of","p":"Phrase","d":"Sự phong phú hoặc số lượng lớn của một cái gì đó.","e":"The garden boasts a profusion of flowers in spring.","ev":"Khu vườn có rất nhiều hoa vào mùa xuân.","k":"a profusion of"},{"t":"Dismiss","p":"verb","d":"Quyết định rằng điều gì đó hoặc ai đó không quan trọng và không đáng xem xét.","e":"The manager dismissed the proposal as impractical.","ev":"Người quản lý bác bỏ đề xuất này vì cho rằng nó không thực tế.","k":"dismiss"},{"t":"Compound","p":"verb/noun","d":"làm cho một vấn đề hoặc tình huống khó khăn trở nên tồi tệ hơn","e":"His financial problems were compounded when he unexpectedly lost his job.","ev":"Vấn đề tài chính của anh càng trở nên phức tạp khi anh bất ngờ bị mất việc.","k":"compound"},{"t":"Ongoing","p":"adjective","d":"Tiếp tục; vẫn đang được tiến hành.","e":"The investigation is ongoing and no conclusions have been reached yet.","ev":"Cuộc điều tra đang diễn ra và chưa có kết luận nào được đưa ra.","k":"ongoing"},{"t":"Salient","p":"adjective","d":"đáng kể, dễ thấy","e":"One of the salient differences between Alison and Nancy is that Alison is a foot taller.","ev":"Một trong những điểm khác biệt nổi bật giữa Alison và Nancy là Alison cao hơn một foot.","k":"salient"},{"t":"Recollect","p":"verb","d":"nhớ (cái gì đó); kêu gọi tâm trí.","e":"I can still recollect the day we first met.","ev":"Tôi vẫn có thể nhớ lại ngày đầu tiên chúng tôi gặp nhau.","k":"recollect"},{"t":"Propitiate","p":"verb","d":"Ngăn chặn ai đó khỏi tức giận bằng cách cố gắng làm hài lòng họ. Làm nguôi","e":"They offered sacrifices to propitiate the gods.","ev":"Họ dâng lễ vật cầu xin các vị thần.","k":"propitiate"},{"t":"Unnerved","p":"adjective","d":"(tính từ) Làm cho người ta cảm thấy lo lắng hoặc khó chịu.","e":"He was unnerved by the sudden change in plans.","ev":"Anh ấy cảm thấy lo lắng trước sự thay đổi đột ngột trong kế hoạch.","k":"unnerved"},{"t":"Mediocre","p":"adjective","d":"Tầm thường","e":"The movie received mediocre reviews from critics.","ev":"Bộ phim nhận được đánh giá tầm thường từ các nhà phê bình.","k":"mediocre"},{"t":"Equalize","p":"verb","d":"Thực hiện giống nhau về số lượng, quy mô hoặc mức độ trên khắp một địa điểm hoặc một nhóm.","e":"The new law aims to equalize opportunities for all citizens.","ev":"Luật mới nhằm mục đích bình đẳng hóa cơ hội cho mọi công dân.","k":"equalize"},{"t":"Assent","p":"verb/noun","d":"(danh từ) Sự thể hiện sự tán thành hoặc đồng ý; (Động từ) Thể hiện sự tán thành hoặc đồng ý.","e":"The board gave its assent to the proposed changes.","ev":"Hội đồng đã đồng ý với những thay đổi được đề xuất.","k":"assent"},{"t":"Penchant","p":"noun","d":"thiên hướng","e":"He had a penchant for collecting rare coins from around the world.","ev":"Anh có sở thích sưu tầm những đồng tiền hiếm từ khắp nơi trên thế giới.","k":"penchant"},{"t":"Counteract","p":"verb","d":"chống lại","e":"The antidote counteracted the effect of the poison.","ev":"Thuốc giải độc đã làm mất tác dụng của chất độc.","k":"counteract"},{"t":"Sanction","p":"verb/noun","d":"Biện pháp trừng phạt (trừng phạt kinh tế)","e":"The government imposed sanctions on the country for its actions.","ev":"Chính phủ đã áp đặt các biện pháp trừng phạt đối với đất nước vì hành động của mình.","k":"sanction"},{"t":"Magnify","p":"verb","d":"Làm cho cái gì đó trông lớn hơn thực tế, đặc biệt là khi nhìn nó qua một ống kính.","e":"The scientist used a microscope to magnify the cells for closer examination.","ev":"Nhà khoa học đã sử dụng kính hiển vi phóng to các tế bào kiểm tra kỹ hơn.","k":"magnify"},{"t":"Integrate","p":"verb","d":"Kết hợp (thứ này) với thứ khác tạo thành một tổng thể; đưa (những người hoặc nhóm có đặc điểm hoặc nhu cầu cụ thể) tham gia bình đẳng hoặc là thành viên của một nhóm xã hội hoặc tổ chức.","e":"The new policy aims to integrate immigrants into the community.","ev":"Chính sách mới nhằm mục đích hòa nhập người nhập cư vào cộng đồng.","k":"integrate"},{"t":"Omit","p":"verb","d":"Không bao gồm hoặc làm điều gì đó.","e":"She omitted to inform the authorities of their visit. He modestly omits to mention that he was pole-vault champion","ev":"Cô ấy đã bỏ qua việc thông báo cho chính quyền về chuyến thăm của họ. Anh khiêm tốn không đề cập đến việc mình là nhà vô địch nhảy sào","k":"omit"}]},{"n":"Buổi 20","c":[{"t":"A Paucity Of","p":"Phrase","d":"Sự khan hiếm hoặc thiếu một cái gì đó.","e":"There is a paucity of information on the subject.","ev":"Có rất ít thông tin về chủ đề này.","k":"a paucity of"},{"t":"Circumscribe","p":"verb","d":"Giới hạn","e":"The regulations circumscribe the activities of the organization to ensure compliance.","ev":"Các quy định giới hạn hoạt động của tổ chức đảm bảo tuân thủ.","k":"circumscribe"},{"t":"Discretion","p":"noun","d":"cẩn trọng, thận trọng","e":"Not wanting her patient to get overly anxious, the doctor used discretion in deciding how much to tell the patient about his condition.","ev":"Không muốn bệnh nhân của mình lo lắng quá mức, bác sĩ đã thận trọng quyết định nên nói với bệnh nhân bao nhiêu về tình trạng của mình.","k":"discretion"},{"t":"Constrict","p":"verb","d":"Bóp, siết chặt","e":"The snake constricted its prey before swallowing it.","ev":"Con rắn siết chặt con mồi trước khi nuốt chửng.","k":"constrict"},{"t":"Yield","p":"verb/noun","d":"1) tạo ra hoặc tạo ra (kết quả) 2) đầu hàng","e":"She refused to yield to his demands, standing her ground and refusing to compromise.","ev":"Cô không chịu khuất phục trước những yêu cầu của anh, giữ vững lập trường và không chịu thỏa hiệp.","k":"yield"},{"t":"Recurrent","p":"adjective","d":"Xảy ra thường xuyên hoặc lặp đi lặp lại.","e":"She suffered from recurrent headaches.","ev":"Cô bị chứng đau đầu tái phát.","k":"recurrent"},{"t":"That Said","p":"Phrase","d":"Dùng giới thiệu một quan điểm khiến điều vừa nói có vẻ kém thuyết phục hơn. Bất chấp những gì người ta vừa nói.","e":"The job is challenging. That said, I enjoy the work.","ev":"Công việc đầy thử thách. Tuy vậy, tôi yêu thích công việc.","k":"that said"},{"t":"Palliate","p":"verb","d":"giảm mức độ nghiêm trọng của","e":"The doctor trusted that the new medication would palliate her patient’s discomfort.","ev":"Bác sĩ tin tưởng rằng loại thuốc mới sẽ làm giảm bớt sự khó chịu của bệnh nhân.","k":"palliate"},{"t":"Intransigent","p":"adjective","d":"từ chối thỏa hiệp, cứng đầu","e":"The intransigent child said he would have 12 scoops of ice cream, or he would bang his head against the wall until his mother fainted from fear.","ev":"Đứa trẻ cứng đầu cho biết sẽ ăn 12 muỗng kem hoặc sẽ đập đầu vào tường cho đến khi mẹ ngất đi vì sợ hãi.","k":"intransigent"},{"t":"Pristine","p":"adjective","d":"nguyên bản và tinh khiết; không hư hỏng hoặc hao mòn khi sử dụng, hoang sơ","e":"The beach was pristine, with white sand and crystal-clear water.","ev":"Bãi biển còn hoang sơ với cát trắng và nước trong vắt.","k":"pristine"},{"t":"Daunting","p":"adjective","d":"đáng sợ","e":"He kept delaying the daunting act of asking for a promotion.","ev":"Anh cứ trì hoãn việc đáng sợ là yêu cầu thăng chức.","k":"daunting"},{"t":"Incongruous With","p":"Phrase","d":"Không hòa hợp hoặc không hòa hợp với môi trường xung quanh hoặc các khía cạnh khác của điều gì đó.","e":"His casual attire was incongruous with the formal event.","ev":"Trang phục giản dị của anh ấy không phù hợp với sự kiện trang trọng.","k":"incongruous with"},{"t":"Homogeneous","p":"adjective","d":"Cùng loại; như nhau; bao gồm các bộ phận cùng loại.","e":"The population of the small town was fairly homogeneous.","ev":"Dân số của thị trấn nhỏ khá đồng nhất.","k":"homogeneous"},{"t":"Banal","p":"adjective","d":"tầm thường","e":"The movie was criticized for its banal dialogue and predictable plot.","ev":"Bộ phim bị chỉ trích vì lời thoại tầm thường và cốt truyện dễ đoán.","k":"banal"},{"t":"Counterfactual","p":"adjective","d":"Phản thực tế","e":"The historian presented a counterfactual scenario where the war had never occurred. Counterfactual thinking: tư duy phản thực tế (what if...)","ev":"Nhà sử học đã đưa ra một kịch bản phản thực tế trong đó chiến tranh chưa bao giờ xảy ra. Tư duy phản thực tế: tư duy phản thực tế (nếu...)","k":"counterfactual"},{"t":"Spectacle","p":"noun","d":"Màn trình diễn hoặc màn trình diễn ấn tượng về mặt thị giác; một sự kiện hoặc cảnh được coi là về mặt tác động trực quan của nó.","e":"The fireworks were a magnificent spectacle.","ev":"Pháo hoa là một cảnh tượng tuyệt vời.","k":"spectacle"},{"t":"belie","p":"verb","d":"Che giấu","e":"His calm demeanor belies the chaos within.","ev":"Vẻ điềm tĩnh của anh ta che giấu sự hỗn loạn bên trong.","k":"belie"},{"t":"Expostulate","p":"verb","d":"phản đối đừng làm","e":"He expostulated with his friend about the risks of the plan.","ev":"Anh ấy đã phản đối với bạn mình về những rủi ro của kế hoạch.","k":"expostulate"},{"t":"Inconsequential","p":"adjective","d":"Không quan trọng hoặc đáng kể.","e":"The error was inconsequential and did not affect the outcome.","ev":"Lỗi này không nghiêm trọng và không ảnh hưởng đến kết quả.","k":"inconsequential"},{"t":"Repudiate","p":"verb","d":"Bác bỏ, từ chối","e":"The politician chose to repudiate the rumors about his involvement in the scandal.","ev":"Chính trị gia đã chọn bác bỏ những tin đồn về sự tham gia của mình vào vụ bê bối.","k":"repudiate"}]},{"n":"Buổi 21","c":[{"t":"Unscrupulous","p":"adjective","d":"Không có nguyên tắc đạo đức; không trung thực hoặc công bằng.","e":"The unscrupulous salesman lied about the car's history.","ev":"Người bán hàng vô đạo đức đã nói dối về lịch sử của chiếc xe.","k":"unscrupulous"},{"t":"Propriety","p":"noun","d":"đứng đắn","e":"Erma’s old-fashioned parents believed that her mini-skirt lacked the propriety expected of a “nice” girl.","ev":"Cha mẹ cổ hủ của Erma tin rằng chiếc váy ngắn của cô thiếu sự đứng đắn như mong đợi của một cô gái “ngoan”.","k":"propriety"},{"t":"Unflattering","p":"adjective","d":"Không tâng bốc","e":"The article gave an unflattering portrayal of the politician.","ev":"Bài báo đã miêu tả không mấy hay ho về chính trị gia này.","k":"unflattering"},{"t":"Ostentatious","p":"adjective","d":"phô trương quá mức, tài khoản","e":"On the palace tour, the guide focused on the ostentatious decorations and spoke little of the royal family’s history.","ev":"Trong chuyến tham quan cung điện, hướng dẫn viên tập trung vào cách trang trí phô trương và nói rất ít về lịch sử của gia đình hoàng gia.","k":"ostentatious"},{"t":"Discrepancy","p":"noun","d":"sự khác biệt, sự thất bại của sự vật tương ứng","e":"He was troubled by the discrepancy between what he remembered paying for the appliance and what his receipt showed he paid for it.","ev":"Anh ấy gặp rắc rối vì sự khác biệt giữa số tiền anh ấy nhớ đã trả cho thiết bị và số tiền trên biên lai cho thấy anh ấy đã trả tiền cho nó.","k":"discrepancy"},{"t":"Recalcitrant","p":"adjective","d":"ngoan cố","e":"The recalcitrant student refused to comply with the school rules.","ev":"Học sinh cứng đầu đã từ chối tuân thủ các quy định của trường.","k":"recalcitrant"},{"t":"To That End","p":"Phrase","d":"To achieve it; Để làm được điều đó.","e":"We need to cut costs; to that end, we are implementing a hiring freeze.","ev":"Chúng ta cần cắt giảm chi phí; vì mục đích đó, chúng tôi đang thực hiện việc đình chỉ tuyển dụng.","k":"to that end"},{"t":"Disingenuous","p":"adjective","d":"gian dối","e":"Her disingenuous smile made me suspicious.","ev":"Nụ cười không chân thật của cô ấy khiến tôi nghi ngờ.","k":"disingenuous"},{"t":"Intractable","p":"adjective","d":"khó thao túng, không thể quản lý được","e":"There was no end in sight to the intractable conflict between the warring countries.","ev":"Cuộc xung đột dai dẳng giữa các quốc gia tham chiến chưa có hồi kết.","k":"intractable"},{"t":"Presage","p":"verb","d":"một điềm báo","e":"When my uncle’s old war injury ached, he interpreted it as a presage of bad weather approaching.","ev":"Khi vết thương chiến tranh cũ của chú tôi nhức nhối, ông giải thích đó là điềm báo thời tiết xấu đang đến gần.","k":"presage"},{"t":"Desultory","p":"adjective","d":"(tính từ) Thiếu kế hoạch, mục đích hoặc sự nhiệt tình; xảy ra ngẫu nhiên hoặc thỉnh thoảng. Lung tung, rời rạc","e":"Their desultory conversation wandered from topic to topic.","ev":"Cuộc trò chuyện rời rạc của họ lang thang từ chủ đề này sang chủ đề khác.","k":"desultory"},{"t":"Disparage","p":"verb","d":"chê bai","e":"She disparaged his work, claiming it lacked originality.","ev":"Cô đã coi thường công việc của anh, cho rằng nó thiếu tính sáng tạo.","k":"disparage"},{"t":"Solicit","p":"verb","d":"Yêu cầu hoặc cố gắng lấy (cái gì) từ ai đó.","e":"They solicited donations for the charity event.","ev":"Họ kêu gọi quyên góp cho sự kiện từ thiện.","k":"solicit"},{"t":"Unanimous","p":"adjective","d":"Hoàn toàn đồng ý","e":"The committee reached a unanimous decision on the proposal.","ev":"Ủy ban đã đạt được quyết định nhất trí về đề xuất này.","k":"unanimous"},{"t":"Supposition","p":"noun","d":"giả thiết","e":"His supposition was correct.","ev":"Giả định của ông đã đúng.","k":"supposition"},{"t":"Brood Over","p":"Phrase","d":"Suy nghĩ sâu sắc về điều gì đó khiến người ta không vui.","e":"He brooded over the mistakes he had made.","ev":"Anh trăn trở về những lỗi lầm mình đã mắc phải.","k":"brood over"},{"t":"Subvert","p":"verb","d":"làm tổn hại hoặc làm suy yếu quyền lực của một hệ thống đã được thiết lập","e":"The rebels attempted to subvert the government, overthrowing the existing regime.","ev":"Phiến quân âm mưu lật đổ chính quyền, lật đổ chế độ hiện tại.","k":"subvert"},{"t":"Absurd","p":"adjective","d":"vô lý hoặc hoàn toàn vô lý","e":"The idea of flying cars was absurd, seeming impossible and ridiculous.","ev":"Ý tưởng về ô tô bay thật vô lý, dường như không thể thực hiện được và buồn cười.","k":"absurd"},{"t":"Ascribe","p":"verb","d":"Ghi tên, gán cho","e":"Many ascribe the invention of dynamite to Alfred Nobel.","ev":"Nhiều người cho rằng việc phát minh ra thuốc nổ là của Alfred Nobel.","k":"ascribe"},{"t":"Deficient","p":"adjective","d":"không có đủ thứ gì đó, đặc biệt là thứ gì đó cần thiết","e":"a diet that is deficient in vitamin A","ev":"chế độ ăn thiếu vitamin A","k":"deficient"}]},{"n":"Buổi 22","c":[{"t":"Benign","p":"adjective","d":"lành tính","e":"The tests determined her tumor was benign.","ev":"Các xét nghiệm đã xác định rằng khối u của cô là lành tính.","k":"benign"},{"t":"Permeate","p":"verb","d":"lan rộng khắp, thấm","e":"Mrs. Huxtable was annoyed that the wet dog’s odor had permeated the furniture’s upholstery.","ev":"Bà Huxtable khó chịu vì mùi chó ướt đã thấm vào vải bọc đồ nội thất.","k":"permeate"},{"t":"Possess","p":"verb","d":"sở hữu; có (khả năng, phẩm chất, đặc tính).","e":"She possesses a rare talent for music.","ev":"Cô sở hữu năng khiếu âm nhạc hiếm có.","k":"possess"},{"t":"Consequential","p":"adjective","d":"Theo sau như một kết quả hoặc hiệu quả; quan trọng; có ý nghĩa.","e":"The court's decision had consequential implications for the law.","ev":"Quyết định của tòa án có ý nghĩa quan trọng đối với pháp luật.","k":"consequential"},{"t":"Specious","p":"adjective","d":"Bề ngoài thì có vẻ hợp lý nhưng thực ra lại sai; gây hiểu lầm về ngoại hình. Mã tốt, chỉ có bề ngoài.","e":"The argument was specious and lacked real evidence.","ev":"Lập luận này chỉ có vẻ bề ngoài và thiếu bằng chứng xác thực.","k":"specious"},{"t":"Concurrently","p":"adverb","d":"(trạng từ) Đồng thời; đồng thời.","e":"The two events will be held concurrently on different floors of the building.","ev":"Hai sự kiện sẽ được tổ chức đồng thời ở các tầng khác nhau của tòa nhà.","k":"concurrently"},{"t":"Unassuming","p":"adjective","d":"khiêm tốn, ít nói","e":"She was an unassuming person who never boasted about her accomplishments, preferring to let her actions speak for themselves.","ev":"Cô ấy là một người khiêm tốn, không bao giờ khoe khoang về thành tích của mình, thích hành động của mình tự nói lên điều đó.","k":"unassuming"},{"t":"Stymie","p":"verb","d":"ngăn chặn hoặc cản trở sự tiến bộ của.","e":"The lack of funding stymied the research project.","ev":"Việc thiếu kinh phí đã cản trở dự án nghiên cứu.","k":"stymie"},{"t":"Profane","p":"adjective","d":"dâm dục, không đứng đắn, báng bổ sung","e":"Jacob’s profane act of dumping frogs in the holy water in the chapel at his boarding school resulted in his dismissal.","ev":"Hành động tục tĩu của Jacob là thả ếch vào nước thánh trong nhà nguyện ở trường nội trú của anh đã khiến anh bị đuổi việc.","k":"profane"},{"t":"Serenely","p":"adverb","d":"Một cách bình tĩnh, yên bình và không gặp rắc rối.","e":"She smiled serenely as she accepted the award.","ev":"Cô mỉm cười thanh thản khi nhận giải thưởng.","k":"serenely"},{"t":"Fallacy","p":"noun","d":"Ngụy biện","e":"The fallacy of that statement is clear.","ev":"Sự sai lầm trong phát biểu đó là rõ ràng.","k":"fallacy"},{"t":"Obligate","p":"verb","d":"Làm cho ai đó cảm thấy bị buộc phải làm điều gì đó về mặt đạo đức hoặc pháp lý.","e":"The contract obligates the company to pay for all damages.","ev":"Hợp đồng bắt buộc công ty phải bồi thường mọi thiệt hại.","k":"obligate"},{"t":"Epitomize","p":"verb","d":"trở thành một ví dụ hoàn hảo về","e":"She epitomizes elegance and grace.","ev":"Cô ấy là hình ảnh thu nhỏ của sự thanh lịch và duyên dáng.","k":"epitomize"},{"t":"Convoluted","p":"adjective","d":"phức tạp","e":"Grace’s story was so convoluted that I couldn’t follow it.","ev":"Câu chuyện của Grace phức tạp đến mức tôi không thể theo kịp.","k":"convoluted"},{"t":"Oversee","p":"verb","d":"giám sát (một người hoặc công việc), đặc biệt là với tư cách chính thức.","e":"She was appointed to oversee the project's development.","ev":"Cô được bổ nhiệm giám sát sự phát triển của dự án.","k":"oversee"},{"t":"Analog","p":"noun","d":"Một người hoặc vật được coi là có thể so sánh được với người hoặc vật khác; (trong điện tử) tín hiệu hoặc dữ liệu liên tục.","e":"The human eye is an analog to a camera lens.","ev":"Mắt người là một cơ quan tương tự như ống kính máy ảnh.","k":"analog"},{"t":"Sanguine","p":"adjective","d":"lạc quan","e":"Despite the challenges ahead, she remained sanguine about the future.","ev":"Dù đối mặt với những thử thách phía trước, cô vẫn lạc quan về tương lai.","k":"sanguine"},{"t":"Retroactive","p":"adjective","d":"(tính từ) Có hiệu lực từ một ngày trong quá khứ.","e":"The new tax law is retroactive to January 1st, affecting all income earned since then.","ev":"Luật thuế mới có hiệu lực từ ngày 1 tháng 1, ảnh hưởng đến tất cả thu nhập kiếm được kể từ đó.","k":"retroactive"},{"t":"Indulgently","p":"adverb","d":"Một cách quá rộng lượng hay khoan dung, bao dung, nuông chiều","e":"The grandparents treated their grandchildren indulgently.","ev":"Ông bà đối xử với cháu rất mực ân cần.","k":"indulgently"},{"t":"Propensity","p":"noun","d":"Xu hướng","e":"He has a propensity for taking risks that often leads to unexpected outcomes.","ev":"Anh có xu hướng mạo hiểm, điều này thường dẫn đến những kết quả bất ngờ.","k":"propensity"}]},{"n":"Buổi 23","c":[{"t":"Discern","p":"verb","d":"nhận biết, phát hiện","e":"Though he hid his emotions, she discerned from his body language that he was angry.","ev":"Mặc dù anh che giấu cảm xúc của mình nhưng cô nhận ra từ ngôn ngữ cơ thể của anh rằng anh đang tức giận.","k":"discern"},{"t":"Harbinger","p":"noun","d":"Một người hoặc vật cho thấy điều gì đó sắp xảy ra, đặc biệt là điều gì đó tồi tệ.","e":"The sudden drop in temperature was a harbinger of the approaching storm.","ev":"Nhiệt độ giảm đột ngột là điềm báo cơn bão đang đến gần.","k":"harbinger"},{"t":"Ruminate On","p":"verb","d":"suy nghĩ sâu sắc về một cái gì đó.","e":"He ruminated on the implications of the decision.","ev":"Anh ngẫm nghĩ về ý nghĩa của quyết định này.","k":"ruminate on"},{"t":"Extricate","p":"verb","d":"Giải thoát","e":"She managed to extricate herself from the difficult situation with grace.","ev":"Cô đã thành công trong việc thoát khỏi tình huống khó khăn một cách duyên dáng.","k":"extricate"},{"t":"Breadth","p":"noun","d":"Khoảng cách hoặc phép đo từ bên này sang bên kia; chiều rộng; phạm vi rộng hoặc mức độ.","e":"The breadth of his knowledge is impressive.","ev":"Bề rộng kiến ​​​​thức của anh ấy thật ấn tượng.","k":"breadth"},{"t":"Protract","p":"verb","d":"Làm cho cái gì đó tồn tại lâu dài hoặc kéo dài hơn mức cần thiết.","e":"They protracted the negotiations to gain more time.","ev":"Họ kéo dài cuộc đàm phán có thêm thời gian.","k":"protract"},{"t":"Installment","p":"noun","d":"(danh từ) Một trong nhiều phần mà một khoản nợ hoặc số tiền phải trả khác được chia vào, sẽ được thanh toán vào những thời điểm cố định liên tiếp.","e":"She paid for the car in monthly installments over two years.","ev":"Cô trả góp chiếc xe hàng tháng trong vòng hai năm.","k":"installment"},{"t":"Reverberate","p":"verb","d":"vang vọng","e":"The sound of the explosion reverberated through the valley.","ev":"Âm thanh của vụ nổ vang vọng khắp thung lũng.","k":"reverberate"},{"t":"Invalidate","p":"verb","d":"Vô hiệu hoá","e":"The discovery of new evidence invalidated the previous theory.","ev":"Việc phát hiện ra bằng chứng mới đã vô hiệu hóa lý thuyết trước đó.","k":"invalidate"},{"t":"Have No Bearing On","p":"Phrase","d":"Không có sự liên quan hoặc ảnh hưởng đến một cái gì đó.","e":"His past mistakes have no bearing on his current performance.","ev":"Những sai lầm trong quá khứ không ảnh hưởng gì đến phong độ hiện tại của anh ấy.","k":"have no bearing on"},{"t":"Wreak Havoc On","p":"Phrase","d":"Gây ra một lượng lớn thiệt hại hoặc tổn hại.","e":"The storm wreaked havoc on the coastal towns.","ev":"Cơn bão tàn phá các thị trấn ven biển.","k":"wreak havoc on"},{"t":"Rectify","p":"verb","d":"đặt (cái gì đó) đúng; Chính xác.","e":"The technician rectified the problem with the computer.","ev":"Kỹ thuật viên đã khắc phục sự cố với máy tính.","k":"rectify"},{"t":"Imperfect","p":"adjective","d":"Không hoàn hảo; bị lỗi hoặc không đầy đủ.","e":"The system is still imperfect and requires further testing.","ev":"Hệ thống vẫn chưa hoàn hảo và cần được thử nghiệm thêm.","k":"imperfect"},{"t":"Intrinsic To","p":"Phrase","d":"Thuộc về một cách tự nhiên; thiết yếu.","e":"Creativity is intrinsic to the artistic process.","ev":"Sáng tạo là bản chất của quá trình nghệ thuật.","k":"intrinsic to"},{"t":"Convene","p":"verb","d":"Triệu tập","e":"Jason convened his entire extended family for a discussion.","ev":"Jason đã triệu tập cả gia đình thảo luận.","k":"convene"},{"t":"Dictate","p":"verb","d":"Nói hoặc đọc to điều gì đó được người viết ra hoặc ghi lại bằng máy; tuyên bố hoặc ra lệnh một cách có thẩm quyền.","e":"The general dictated a letter to his secretary.","ev":"Vị tướng viết một lá thư cho thư ký của mình.","k":"dictate"},{"t":"Candor","p":"noun","d":"trung thực, thẳng thắn","e":"We were surprised by the candor of the mayor’s speech because he is usually rather evasive.","ev":"Chúng tôi rất ngạc nhiên trước sự thẳng thắn trong bài phát biểu của thị trưởng vì ông ấy thường khá lảng tránh.","k":"candor"},{"t":"Denigrate","p":"verb","d":"hạ thấp","e":"It's unfair to denigrate someone's work without understanding their effort.","ev":"Thật không công bằng khi hạ thấp công việc của ai đó mà không hiểu được nỗ lực của họ.","k":"denigrate"},{"t":"Irresolvable","p":"adjective","d":"Không thể giải quyết hoặc giải quyết được.","e":"The conflict between the two parties seemed irresolvable.","ev":"Mâu thuẫn giữa hai bên tưởng chừng như không thể giải quyết được.","k":"irresolvable"},{"t":"Unpalatable","p":"adjective","d":"Hương vị không dễ chịu; khó chịu đựng hoặc chấp nhận.","e":"The truth can sometimes be unpalatable.","ev":"Sự thật đôi khi có thể khó chấp nhận.","k":"unpalatable"}]},{"n":"Buổi 24","c":[{"t":"Dogmatic","p":"adjective","d":"giáo điều","e":"His dogmatic beliefs often led to heated arguments with others.","ev":"Những niềm tin giáo điều của anh thường dẫn đến những cuộc tranh cãi gay gắt với người khác.","k":"dogmatic"},{"t":"Palatable","p":"adjective","d":"hợp khẩu vị hoặc cảm giác, ngon","e":"Despite the unpleasant smell, the exotic cheese was quite palatable.","ev":"Mặc dù có mùi khó chịu nhưng loại pho mát lạ này khá ngon miệng.","k":"palatable"},{"t":"Counter","p":"verb","d":"Phản bác","e":"She countered his argument with solid evidence.","ev":"Cô phản bác lại lập luận của anh bằng bằng chứng chắc chắn.","k":"counter"},{"t":"Obviate The Need","p":"Phrase","d":"loại bỏ một nhu cầu hoặc khó khăn; làm một cái gì đó không cần thiết","e":"The new treatment obviates the need for surgery.","ev":"Phương pháp điều trị mới loại bỏ sự cần thiết phải phẫu thuật.","k":"obviate the need"},{"t":"Contemporaneous","p":"adjective","d":"Đương thời","e":"Though her novels do not feature the themes of Romanticism, Jane Austen’s work was contemporaneous with that of Wordsworth and Byron.","ev":"Tác phẩm của Austen diễn ra trong cùng một thời kỳ văn học với các tác giả này.","k":"contemporaneous"},{"t":"Summation","p":"noun","d":"(danh từ) Quá trình cộng các thứ lại với nhau; một bản tóm tắt các điểm hoặc sự kiện","e":"The lawyer's summation highlighted the key evidence presented during the trial.","ev":"Phần tóm tắt của luật sư nêu bật những bằng chứng quan trọng được đưa ra trong phiên tòa.","k":"summation"},{"t":"Earnest","p":"adjective","d":"chân thành và nghiêm túc","e":"She was an earnest student who was always eager to learn.","ev":"Cô là một học sinh nghiêm túc và luôn ham học hỏi.","k":"earnest"},{"t":"Cliched","p":"adjective","d":"Sáo rỗng","e":"He made some clichéd remark.","ev":"Anh ấy đã đưa ra một số nhận xét sáo rỗng.","k":"cliched"},{"t":"Inducement","p":"noun","d":"Một điều thuyết phục hoặc ảnh hưởng đến ai đó làm điều gì đó. Khuyến khích.","e":"The company offered financial inducements to attract new employees.","ev":"Công ty đưa ra các khuyến khích tài chính thu hút nhân viên mới.","k":"inducement"},{"t":"Divulge","p":"verb","d":"tiết lộ","e":"He refused to divulge any details.","ev":"Anh ta từ chối tiết lộ bất kỳ chi tiết nào.","k":"divulge"},{"t":"Inextricable","p":"adjective","d":"rối rắm hoặc vướng víu một cách vô vọng","e":"Unless I look at the solution manual, I have no way of solving this inextricable problem.","ev":"Trừ khi tôi nhìn vào hướng dẫn giải pháp, tôi không có cách nào giải quyết vấn đề khó hiểu này.","k":"inextricable"},{"t":"Exhaustive","p":"adjective","d":"Bao gồm hoặc xem xét tất cả các yếu tố hoặc khía cạnh; đầy đủ toàn diện.","e":"The report provided an exhaustive analysis of the issue.","ev":"Báo cáo đã cung cấp một phân tích toàn diện về vấn đề này.","k":"exhaustive"},{"t":"Defunct","p":"adjective","d":"không còn được sử dụng hoặc tồn tại","e":"They planned to turn the defunct schoolhouse into a community center.","ev":"Họ lên kế hoạch biến ngôi trường không còn tồn tại thành một trung tâm cộng đồng.","k":"defunct"},{"t":"Postulate","p":"verb","d":"gợi ý hoặc đề xuất điều gì đó là đúng (đưa ra làm đề)","e":"The theory postulated that the universe began with a Big Bang, a hypothesis that has been widely accepted by scientists.","ev":"Lý thuyết này cho rằng vũ trụ bắt đầu từ Vụ nổ lớn, một giả thuyết đã được các nhà khoa học chấp nhận rộng rãi.","k":"postulate"},{"t":"Austerity","p":"noun","d":"điều kiện kinh tế khó khăn được tạo ra bởi các chính sách của chính phủ nhằm cắt giảm chi tiêu công.","e":"War was followed by many years of austerity.","ev":"Tiếp theo chiến tranh là nhiều năm thắt lưng buộc bụng.","k":"austerity"},{"t":"Initiator","p":"noun","d":"Một người khiến một cái gì đó bắt đầu.","e":"She was the initiator of the community outreach program.","ev":"Cô là người khởi xướng chương trình tiếp cận cộng đồng.","k":"initiator"},{"t":"Qualify","p":"verb","d":"Đủ điều kiện","e":"She qualified for the scholarship based on her academic achievements.","ev":"Cô đủ điều kiện nhận học bổng dựa trên thành tích học tập của mình.","k":"qualify"},{"t":"Incongruity","p":"noun","d":"Tình trạng không phù hợp; sự không tương thích.","e":"The incongruity between his words and actions was evident.","ev":"Sự mâu thuẫn giữa lời nói và hành động của anh đã lộ rõ.","k":"incongruity"},{"t":"Trait","p":"noun","d":"Một chất lượng hoặc đặc điểm phân biệt, thường thuộc về một người.","e":"Patience is an essential trait for a teacher.","ev":"Kiên nhẫn là một đức tính cần thiết của một giáo viên.","k":"trait"},{"t":"Assuage","p":"verb","d":"Giảm đau","e":"She tried to assuage his fears about the upcoming exam.","ev":"Cô cố gắng làm dịu nỗi lo lắng của anh về kỳ thi sắp tới.","k":"assuage"}]},{"n":"Buổi 25","c":[{"t":"Putatively","p":"adverb","d":"Được coi là hoặc được coi là như vậy.","e":"The putative father of the child was called in for questioning.","ev":"Người cha giả định của đứa trẻ đã được gọi đến thẩm vấn.","k":"putatively"},{"t":"Conflate","p":"verb","d":"Kết hợp (hai hoặc nhiều văn bản, ý tưởng, verbverb) thành một.","e":"The editor conflated the two stories into a single narrative.","ev":"Người biên tập đã gộp hai câu chuyện thành một câu chuyện duy nhất.","k":"conflate"},{"t":"Rehabilitation","p":"noun","d":"quá trình trở lại trạng thái tốt (con người, tòa nhà)","e":"the rehabilitation of derelict buildings","ev":"việc phục hồi các tòa nhà bỏ hoang","k":"rehabilitation"},{"t":"Transpose","p":"verb","d":"Làm cho (hai hoặc nhiều vật) đổi chỗ cho nhau; chuyển đến một nơi hoặc bối cảnh khác.","e":"The editor transposed the paragraphs to improve the flow of the article.","ev":"Người biên tập đã chuyển đổi các đoạn văn cải thiện tính trôi chảy của bài viết.","k":"transpose"},{"t":"Insular","p":"adjective","d":"chỉ quan tâm đến đất nước, ý tưởng của mình, chứ không quan tâm đến những thứ từ bên ngoài, hẹp hòi thiển cận","e":"The British are often accused of being insular.","ev":"Người Anh thường bị buộc tội là thiển cận.","k":"insular"},{"t":"Subside","p":"verb","d":"Trở nên bớt căng thẳng, bạo lực hoặc nghiêm trọng hơn; giảm bớt.","e":"After the storm, the winds subsided, and the sea became calm.","ev":"Sau cơn bão, gió dịu dần và biển trở nên yên tĩnh.","k":"subside"},{"t":"Reverentially","p":"adverb","d":"Với sự tôn trọng sâu sắc hoặc kính sợ.","e":"The students listened reverentially to the professor's lecture.","ev":"Các sinh viên chăm chú lắng nghe bài giảng của giáo sư.","k":"reverentially"},{"t":"Verify","p":"verb","d":"đảm bảo hoặc chứng minh rằng (điều gì đó) là đúng, chính xác hoặc hợp lý.","e":"The results were verified by independent experts.","ev":"Kết quả đã được xác nhận bởi các chuyên gia độc lập.","k":"verify"},{"t":"Nullify","p":"verb","d":"Làm cho vô hiệu về mặt pháp lý; làm mất hiệu lực.","e":"The court's decision nullified the previous ruling.","ev":"Quyết định của tòa án đã vô hiệu hóa phán quyết trước đó.","k":"nullify"},{"t":"Nonplus","p":"verb","d":"làm ngạc nhiên và bối rối (ai đó) đến mức họ không biết phải phản ứng thế nào.","e":"Diane was nonplussed by such an odd question","ev":"Diane bối rối trước một câu hỏi kỳ lạ như vậy","k":"nonplus"},{"t":"Counterbalance","p":"verb","d":"Một trọng lượng cân bằng một trọng lượng khác; cân bằng","e":"The benefits of the policy counterbalance its costs.","ev":"Lợi ích của chính sách sẽ cân bằng chi phí của nó.","k":"counterbalance"},{"t":"Reprehensible","p":"adjective","d":"Đáng trách","e":"His reprehensible actions during the crisis drew widespread condemnation.","ev":"Hành động đáng lên án của anh trong cuộc khủng hoảng đã bị chỉ trích rộng rãi.","k":"reprehensible"},{"t":"Extirpate","p":"verb","d":"Diệt tận gốc và tiêu diệt hoàn toàn.","e":"The invasive species was extirpated from the region to protect native wildlife.","ev":"Các loài xâm lấn đã bị tuyệt chủng khỏi khu vực bảo vệ động vật hoang dã bản địa.","k":"extirpate"},{"t":"Alleviate","p":"verb","d":"giảm nhẹ","e":"This drug will alleviate the symptoms of the terrible disease, but only for a while.","ev":"Thuốc này sẽ làm giảm triệu chứng của căn bệnh khủng khiếp, nhưng chỉ trong một thời gian ngắn.","k":"alleviate"},{"t":"Dispassionate","p":"adjective","d":"vô tư","e":"He approached the situation with a dispassionate view, analyzing the facts without emotion.","ev":"Anh tiếp cận tình huống với cái nhìn lạnh lùng, phân tích các sự kiện mà không có cảm xúc.","k":"dispassionate"},{"t":"Undergo","p":"verb","d":"Trải nghiệm hoặc phải chịu (điều gì đó, điển hình là điều gì đó khó chịu hoặc khó khăn).","e":"He had to undergo surgery to repair the damage.","ev":"Anh ấy đã phải trải qua cuộc phẫu thuật sửa chữa những tổn thương.","k":"undergo"},{"t":"Deserving","p":"adjective","d":"xứng đáng","e":"She is deserving of all the accolades she has received.","ev":"Cô ấy xứng đáng với tất cả những lời khen ngợi mà cô ấy đã nhận được.","k":"deserving"},{"t":"Circumspect","p":"adjective","d":"thận trọng, cẩn trọng","e":"Though I promised Rachel’s father I would bring her home promptly by midnight, it would have been more circumspect not to have specified a time.","ev":"Mặc dù tôi đã hứa với cha của Rachel là sẽ đưa cô ấy về nhà ngay trước nửa đêm, nhưng sẽ thận trọng hơn nếu không xác định thời gian cụ thể.","k":"circumspect"},{"t":"Hesitant","p":"adjective","d":"Không chắc chắn hoặc chậm chạp trong hành động hoặc lời nói.","e":"She was hesitant to make a decision without more information.","ev":"Cô do dự khi đưa ra quyết định mà không có thêm thông tin.","k":"hesitant"},{"t":"Impart","p":"verb","d":"truyền đạt, kể cho hay, phổ biến","e":"to impart news","ev":"truyền đạt tin tức","k":"impart"},{"t":"Shrewd","p":"adjective","d":"Khôn ngoan, sắc sảo","e":"His shrewd investment decisions greatly increased his wealth.","ev":"Các quyết định đầu tư khôn ngoan của anh đã làm gia tăng đáng kể sự giàu có của mình.","k":"shrewd"}]},{"n":"Buổi 26","c":[{"t":"Subdued","p":"adjective","d":"yên tĩnh; (về màu sắc hoặc ánh sáng) mềm mại và kiềm chế; trầm","e":"The room was painted in subdued tones of blue and gray.","ev":"Căn phòng được sơn với tông màu nhẹ nhàng như xanh lam và xám.","k":"subdued"},{"t":"pundit","p":"noun","d":"học giả, chuyên gia","e":"The pundit offered insightful commentary on the political situation.","ev":"Chuyên gia đã đưa ra những nhận xét sâu sắc về tình hình chính trị.","k":"pundit"},{"t":"unfathomable","p":"adjective","d":"không thể hiểu được","e":"The depths of the ocean remain largely unfathomable to scientists.","ev":"Độ sâu của đại dương vẫn chủ yếu không thể hiểu được đối với các nhà khoa học.","k":"unfathomable"},{"t":"flippant, flippancy","p":"adjective, noun","d":"suồng sã, cợt nhả","e":"His flippant remarks during the serious discussion annoyed everyone.","ev":"Những lời nói cợt nhả của anh trong cuộc thảo luận nghiêm túc đã khiến mọi người khó chịu.","k":"flippant, flippancy"},{"t":"effervesce","p":"verb","d":"sủi bọt","e":"The soda began to effervesce as soon as the cap was removed.","ev":"Nước ngọt bắt đầu sủi bọt ngay khi nắp được mở.","k":"effervesce"},{"t":"jaded","p":"adjective","d":"mệt mỏi","e":"After years in the industry, she felt jaded and disillusioned.","ev":"Sau nhiều năm trong ngành, cô cảm thấy mệt mỏi và thất vọng.","k":"jaded"},{"t":"compliant, \ncompliance","p":"adjective, noun","d":"tuân thủ, \nTuân thủ","e":"Her compliant nature made her easy to work with, as she was always agreeable.","ev":"Tính cách dễ bảo của cô khiến việc làm việc cùng cô trở nên dễ dàng, vì cô luôn đồng thuận.","k":"compliant, compliance"},{"t":"ramshackle","p":"adjective","d":"xiêu vẹo","e":"The ramshackle house was falling apart.","ev":"Ngôi nhà tồi tàn đang bị sụp đổ.","k":"ramshackle"},{"t":"rouse, rousing","p":"verb, adjective","d":"đánh thức, đánh thức","e":"The coach's speech was meant to rouse the team's spirit before the big game.","ev":"Bài phát biểu của huấn luyện viên nhằm khơi dậy tinh thần của đội trước trận đấu lớn.","k":"rouse, rousing"},{"t":"idyllic","p":"adjective","d":"bình dị","e":"They spent their vacation in an idyllic village surrounded by mountains and rivers.","ev":"Họ đã dành kỳ nghỉ của mình ở một ngôi làng bình dị được bao quanh bởi núi và sông.","k":"idyllic"},{"t":"gallant(ry)","p":"adjective, noun","d":"dũng cảm (ry)","e":"The gallant rescue of the trapped hikers was reported in the news.","ev":"Hành động dũng cảm cứu hộ những người leo núi bị mắc kẹt đã được đưa tin trên báo.","k":"gallant(ry)"},{"t":"spartan","p":"adjective","d":"người Spartan","e":"He lived a spartan lifestyle, free of excess.","ev":"Anh ta sống một cuộc sống khắc khổ, không có sự dư thừa.","k":"spartan"},{"t":"exhibitionist, \nexhibitionistic","p":"noun, adjective","d":"nhà triển lãm, \nthích phô trương","e":"His exhibitionist tendencies made him the center of attention at every party.","ev":"Xu hướng thích phô trương của anh khiến anh trở thành tâm điểm chú ý tại mỗi bữa tiệc.","k":"exhibitionist, exhibitionistic"},{"t":"furor","p":"noun","d":"sự giận dữ","e":"The furor over the new policy caused widespread protests across the city.","ev":"Cuộc phẫn nộ về chính sách mới đã gây ra các cuộc biểu tình lan rộng khắp thành phố.","k":"furor"},{"t":"polemical","p":"adjective","d":"gây tranh cãi","e":"The polemical article sparked controversy and debate in the academic community.","ev":"Bài viết gây tranh cãi đã kích thích sự tranh luận và tranh cãi trong cộng đồng học thuật.","k":"polemical"},{"t":"duplicitous, \nduplicity","p":"adjective, noun","d":"trùng lặp, \nsự dối trá","e":"His duplicitous nature led to many betrayals.","ev":"Bản chất lừa dối của anh ta đã dẫn đến nhiều vụ phản bội.","k":"duplicitous, duplicity"},{"t":"torpor","p":"noun","d":"uể oải","e":"After a long period of torpor, she finally motivated herself to exercise again.","ev":"Sau một thời gian dài uể oải, cô đã tự thúc đẩy mình tập thể dục trở lại.","k":"torpor"},{"t":"scanty","p":"adjective","d":"ít ỏi","e":"The scanty clothing was not suitable for the cold weather.","ev":"Quần áo mỏng manh không phù hợp cho thời tiết lạnh.","k":"scanty"},{"t":"miserly","p":"adjective","d":"keo kiệt","e":"His miserly habits kept him from enjoying life to the fullest.","ev":"Thói quen keo kiệt của anh đã ngăn cản anh tận hưởng cuộc sống một cách trọn vẹn.","k":"miserly"},{"t":"cantankerous(ness)","p":"adjective, noun","d":"gắt gỏng, khó tính","e":"The cantankerous old man often argued with his neighbors over trivial matters.","ev":"Người đàn ông khó tính thường cãi nhau với hàng xóm về những vấn đề tầm thường.","k":"cantankerous(ness)"}]},{"n":"Buổi 27","c":[{"t":"squander","p":"verb","d":"phung phí","e":"Don’t squander your time on trivial matters; focus on what truly matters.","ev":"Đừng lãng phí thời gian vào những điều tầm thường; hãy tập trung vào những gì thực sự quan trọng.","k":"squander"},{"t":"disquiet(ing)","p":"verb/adjective","d":"không yên","e":"The disquieting silence in the room suggested that something was wrong.","ev":"Sự im lặng đáng lo ngại trong phòng cho thấy có điều gì đó không ổn.","k":"disquiet(ing)"},{"t":"waning","p":"adjective","d":"suy yếu","e":"Her enthusiasm for the project was waning as the deadline approached.","ev":"Sự hào hứng của cô với dự án đang giảm dần khi thời hạn đến gần.","k":"waning"},{"t":"derogatory, \nderogate","p":"adjective","d":"xúc phạm, \nxúc phạm","e":"The comments were derogatory and hurtful to the community.","ev":"Những bình luận đó đã xúc phạm và gây tổn thương cho cộng đồng.","k":"derogatory, derogate"},{"t":"cacophonous, \ncacophony","p":"adj/noun","d":"ồn ào, \ntạp âm","e":"The cacophonous sounds of the city can be overwhelming at times.","ev":"Âm thanh hỗn tạp của thành phố đôi khi có thể khiến ta choáng ngợp.","k":"cacophonous, cacophony"},{"t":"plasticity","p":"adjective","d":"tính dẻo","e":"The plasticity of the brain allows it to adapt to new experiences throughout life.","ev":"Độ dẻo dai của não cho phép nó thích nghi với những trải nghiệm mới trong suốt cuộc đời.","k":"plasticity"},{"t":"august","p":"adjective","d":"uy nghi, đáng ngưỡng mộ","e":"The august ceremony was attended by dignitaries from around the world.","ev":"Buổi lễ uy nghi được tham dự bởi các nhân vật quan trọng từ khắp nơi trên thế giới.","k":"august"},{"t":"stark(ness)","p":"noun","d":"(sự khắc nghiệt)","e":"The starkness of the landscape was breathtaking.","ev":"Sự trần trụi của phong cảnh thật đẹp mắt.","k":"stark(ness)"},{"t":"rebuttal","p":"noun","d":"sự bác bỏ","e":"The lawyer's rebuttal effectively countered the accusations made against her client.","ev":"Sự phản biện của luật sư đã bác bỏ hiệu quả những cáo buộc chống lại thân chủ của cô.","k":"rebuttal"},{"t":"pacifist","p":"adjective","d":"người theo chủ nghĩa hoà bình","e":"As a pacifist, she strongly opposed the use of violence in any form.","ev":"Là một người theo chủ nghĩa hòa bình, cô mạnh mẽ phản đối việc sử dụng bạo lực dưới bất kỳ hình thức nào.","k":"pacifist"},{"t":"reprimand","p":"verb","d":"khiển trách","e":"The manager issued a reprimand to the employee for being late.","ev":"Quản lý đã đưa ra một hình phạt cho nhân viên vì đến muộn.","k":"reprimand"},{"t":"simile","p":"noun","d":"sự so sánh","e":"The author used a simile to illustrate the character’s feelings, comparing her sadness to a rainstorm.","ev":"Tác giả đã sử dụng phép so sánh minh họa cảm xúc của nhân vật, so sánh nỗi buồn của cô với cơn bão mưa.","k":"simile"},{"t":"scrutinize, scrutiny","p":"verb/noun","d":"xem xét kỹ lưỡng, xem xét kỹ lưỡng","e":"She needed to scrutinize the document for any errors before submission.","ev":"Cô ấy cần xem xét kỹ lưỡng tài liệu tìm bất kỳ lỗi nào trước khi nộp.","k":"scrutinize, scrutiny"},{"t":"slight (verb)","p":"verb","d":"coi thường, xúc phạm","e":"He felt slighted when his contributions were ignored during the meeting.","ev":"Anh cảm thấy bị coi thường khi những đóng góp của mình bị phớt lờ trong cuộc họp.","k":"slight (verb)"},{"t":"demure, demurral","p":"adj/noun","d":"đoan trang, nền nã","e":"She had a demure smile that belied her confident personality.","ev":"Cô có một nụ cười đoan trang mà ẩn chứa tính cách tự tin của mình.","k":"demure, demurral"},{"t":"blighted","p":"adjective","d":"tàn lụi","e":"The crops were blighted by the drought.","ev":"Cây trồng đã bị thiệt hại do hạn hán.","k":"blighted"},{"t":"debilitate(d)","p":"verb/adjective","d":"suy nhược(d)","e":"The illness can debilitate even the strongest individuals.","ev":"Căn bệnh này có thể làm suy yếu ngay cả những người mạnh mẽ nhất.","k":"debilitate(d)"},{"t":"ignominy, \nignominious","p":"adj/noun","d":"sự ô nhục, \nô nhục","e":"The ignominy of his actions was hard to bear in front of his peers.","ev":"Sự nhục nhã của hành động của anh thật khó chịu trước mặt các đồng nghiệp.","k":"ignominy, ignominious"},{"t":"diminutive, \ndiminution","p":"adj/noun","d":"nhỏ bé, \nsự suy giảm","e":"The diminutive size of the puppy made it incredibly cute.","ev":"Kích thước nhỏ bé của chú chó con khiến nó trở nên rất dễ thương.","k":"diminutive, diminution"},{"t":"vacuous, vacuity","p":"adj/noun","d":"trống rỗng, trống rỗng","e":"The vacuous expression on his face showed he was not paying attention.","ev":"Biểu cảm trống rỗng trên khuôn mặt anh cho thấy anh không chú ý.","k":"vacuous, vacuity"}]},{"n":"Buổi 28","c":[{"t":"venal(ity)","p":"adjective","d":"tính tham nhũng","e":"His venality was evident when he accepted bribes from several companies.","ev":"Tính tham nhũng của anh rõ ràng khi anh nhận hối lộ từ một số công ty.","k":"venal(ity)"},{"t":"irreverent, \nirreverence","p":"adj/noun","d":"bất kính, \nsự bất kính","e":"His irreverent jokes about serious topics offended many people.","ev":"Những câu đùa không tôn trọng của anh về các chủ đề nghiêm túc đã khiến nhiều người bị xúc phạm.","k":"irreverent, irreverence"},{"t":"ascendancy","p":"noun","d":"uy thế","e":"The party regained ascendancy in the political landscape after the election.","ev":"Đảng đã lấy lại thế thượng phong trong bối cảnh chính trị sau cuộc bầu cử.","k":"ascendancy"},{"t":"finesse","p":"noun/verb","d":"sự khéo léo","e":"He handled the situation with finesse, ensuring a smooth resolution.","ev":"Anh đã xử lý tình huống một cách khéo léo, đảm bảo giải quyết suôn sẻ.","k":"finesse"},{"t":"inscrutable","p":"adjective","d":"không thể hiểu được","e":"His inscrutable expression made it hard to read him.","ev":"Biểu cảm bí ẩn của anh ta khiến việc đọc vị khó khăn.","k":"inscrutable"},{"t":"prohibitive, \nprohibition","p":"adj/noun","d":"cấm đoán, (giá cả) cao quá mức","e":"The prohibitive costs of living in the city discourage many from moving there.","ev":"Chi phí sinh hoạt cắt cổ ở thành phố khiến nhiều người không muốn chuyển đến đó.","k":"prohibitive, prohibition"},{"t":"profuse, profusion","p":"noun","d":"dồi dào, nhiều","e":"She offered profuse apologies for her mistake.","ev":"Cô đã gửi lời xin lỗi dồn dập về sai lầm của mình.","k":"profuse, profusion"},{"t":"byzantine","p":"adjective","d":"phức tạp và bí ẩn","e":"The byzantine structure of the organization made it hard to navigate.","ev":"Cấu trúc phức tạp của tổ chức khiến việc điều hướng trở nên khó khăn.","k":"byzantine"},{"t":"prevaricator","p":"noun","d":"người nói quanh co","e":"A prevaricator can never be trusted.","ev":"Kẻ quanh co không bao giờ có thể được tin cậy.","k":"prevaricator"},{"t":"laud, laudatory","p":"verb","d":"ca ngợi, khen ngợi","e":"He received laudatory reviews for his performance in the play.","ev":"Anh đã nhận được những đánh giá khen ngợi cho màn trình diễn của mình trong vở kịch.","k":"laud, laudatory"},{"t":"barrage","p":"noun","d":"một loại, nhiều (câu hỏi, cú đấm)","e":"The barrage of questions overwhelmed her.","ev":"Cơn mưa câu hỏi đã làm cô ấy choáng ngợp.","k":"barrage"},{"t":"philanthropist, \nphilanthropic","p":"adj/noun","d":"nhà từ thiện, \ntừ thiện","e":"The philanthropist donated millions to support education and healthcare initiatives.","ev":"Nhà từ thiện đã quyên góp hàng triệu đô la hỗ trợ các sáng kiến giáo dục và chăm sóc sức khỏe.","k":"philanthropist, philanthropic"},{"t":"scope","p":"noun","d":"phạm vi","e":"The scope of the project includes both research and implementation phases.","ev":"Phạm vi của dự án bao gồm cả giai đoạn nghiên cứu và thực hiện.","k":"scope"},{"t":"disheartening","p":"adjective","d":"làm nản lòng","e":"The disheartening news about the project’s funding made the team anxious.","ev":"Tin tức khiến đội ngũ chán nản về việc tài trợ cho dự án đã khiến họ lo lắng.","k":"disheartening"},{"t":"epiphany","p":"noun","d":"sự khai sáng, ngộ ra","e":"His epiphany about life changed his perspective completely.","ev":"Sự khai sáng về cuộc sống của anh đã thay đổi hoàn toàn quan điểm của anh.","k":"epiphany"},{"t":"bog","p":"noun","d":"đầm lầy","e":"The heavy rains caused the fields to bog down, making it difficult to plant crops.","ev":"Những trận mưa lớn khiến các cánh đồng lầy lội, làm khó khăn cho việc trồng trọt.","k":"bog"},{"t":"recessive","p":"adjective","d":"lặn","e":"Blue eyes are a recessive trait, meaning they can be masked by dominant traits.","ev":"Mắt xanh là một đặc điểm lặn, có nghĩa là nó có thể bị che khuất bởi các đặc điểm trội.","k":"recessive"},{"t":"sophistry","p":"noun","d":"sự ngụy biện","e":"His argument was nothing more than sophistry.","ev":"Lập luận của anh ta chẳng qua chỉ là lý lẽ ranh mãnh.","k":"sophistry"},{"t":"efface(ment)","p":"noun","d":"xoá nhoà","e":"The artist's work showed a gradual effacement of earlier styles as she developed her own.","ev":"Công việc của nghệ sĩ cho thấy sự xóa nhòa dần dần các phong cách trước đó khi cô phát triển phong cách riêng.","k":"efface(ment)"},{"t":"castigate","p":"verb","d":"chỉ trích, mắng nhiếc","e":"The teacher castigated the students for their poor performance on the exam.","ev":"Giáo viên đã chỉ trích học sinh vì thành tích kém trong kỳ thi.","k":"castigate"}]},{"n":"Buổi 29","c":[{"t":"proliferate, \nproliferation","p":"noun","d":"nảy nở, \nsự tăng sinh","e":"The use of social media has proliferated in recent years, changing how we communicate.","ev":"Việc sử dụng mạng xã hội đã gia tăng nhanh chóng trong những năm gần đây, thay đổi cách chúng ta giao tiếp.","k":"proliferate, proliferation"},{"t":"disillusionment","p":"noun","d":"sự vỡ mộng","e":"The disillusionment with the political system led many to lose faith in democracy.","ev":"Sự thất vọng với hệ thống chính trị đã khiến nhiều người mất niềm tin vào nền dân chủ.","k":"disillusionment"},{"t":"fathom (verb)","p":"verb","d":"hiểu được (động từ)","e":"It’s hard to fathom the depth of the ocean from the shore.","ev":"Thật khó hiểu được độ sâu của đại dương từ bờ biển.","k":"fathom (verb)"},{"t":"incriminate","p":"verb","d":"buộc tội","e":"The evidence seemed to incriminate him, making the case against him stronger.","ev":"Bằng chứng dường như buộc tội anh, làm cho vụ án chống lại anh trở nên mạnh mẽ hơn.","k":"incriminate"},{"t":"reap","p":"verb","d":"gặt hái","e":"If you work hard, you will reap the rewards of your efforts.","ev":"Nếu bạn làm việc chăm chỉ, bạn sẽ gặt hái được thành quả từ nỗ lực của mình.","k":"reap"},{"t":"impudence, \nimpudent","p":"noun/adj","d":"sự ngạo mạn, \ntrơ tráo","e":"His impudence in addressing the teacher shocked the entire class.","ev":"Sự vô lễ của anh khi nói chuyện với giáo viên đã làm cả lớp sốc.","k":"impudence, impudent"},{"t":"temperamental","p":"adjective","d":"thất thường","e":"His temperamental nature made it hard for his friends to predict his reactions.","ev":"Tính khí thất thường của anh khiến bạn bè khó đoán được phản ứng của anh.","k":"temperamental"},{"t":"indiscriminate","p":"adjective","d":"bừa bãi","e":"His indiscriminate use of resources led to waste and inefficiency.","ev":"Việc anh sử dụng tài nguyên một cách bừa bãi đã dẫn đến lãng phí và thiếu hiệu quả.","k":"indiscriminate"},{"t":"hamper (verb)","p":"verb","d":"cản trở (động từ)","e":"Heavy rains can hamper the construction process significantly.","ev":"Mưa lớn có thể cản trở quá trình xây dựng một cách đáng kể.","k":"hamper (verb)"},{"t":"teem, teeming","p":"verb","d":"đông đúc, đông đúc","e":"The lake was teeming with fish during the summer months.","ev":"Hồ đầy cá vào những tháng mùa hè.","k":"teem, teeming"},{"t":"piety, pious","p":"noun/adj","d":"sùng đạo, ngoan đạo","e":"His piety was evident in his daily rituals and charitable acts.","ev":"Tấm lòng sùng đạo của anh rõ ràng qua những nghi lễ hàng ngày và các hành động từ thiện của anh.","k":"piety, pious"},{"t":"eulogy, eulogize","p":"noun","d":"điếu văn, điếu văn","e":"At the funeral, a touching eulogy was delivered in honor of the deceased.","ev":"Tại đám tang, một bài điếu văn xúc động đã được đọc tôn vinh người đã khuất.","k":"eulogy, eulogize"},{"t":"perquisite","p":"noun","d":"bổng lộc, đặc quyền","e":"A company car is often considered a perquisite of the job.","ev":"Một chiếc xe công ty thường được coi là một đặc quyền của công việc.","k":"perquisite"},{"t":"parch","p":"adjective","d":"Làm khô","e":"The sun can parch the earth, making it difficult for plants to survive.","ev":"Mặt trời có thể làm khô cằn đất, khiến cây cối khó sống sót.","k":"parch"},{"t":"demonstrative","p":"adjective","d":"Mở lòng, không kiềm chế cảm xúc","e":"He was demonstrative in his affection, often hugging and kissing his friends.","ev":"Anh ấy thể hiện tình cảm một cách rõ ràng, thường ôm và hôn bạn bè.","k":"demonstrative"},{"t":"affected","p":"adjective","d":"giả tạo","e":"His affected mannerisms made him seem insincere to others.","ev":"Cách cư xử giả tạo của anh khiến anh có vẻ không chân thành trong mắt người khác.","k":"affected"},{"t":"pedant, pedantic, pedantry","p":"noun","d":"quá chú tâm tới chi tiết","e":"He was criticized for his pedantic approach to teaching, focusing too much on minor details.","ev":"Anh bị chỉ trích vì cách dạy học chú trọng quá nhiều vào những chi tiết nhỏ.","k":"pedant, pedantic, pedantry"},{"t":"provincial","p":"adjective","d":"tỉnh lẻ, quê mùa","e":"His provincial mindset made it difficult for him to understand broader perspectives.","ev":"Tư duy quê mùa của anh khiến anh khó hiểu được những quan điểm rộng hơn.","k":"provincial"},{"t":"conciliate, \nconciliatory","p":"v/adj","d":"hòa giải","e":"The mediator tried to conciliate both parties during the negotiation.","ev":"Người hòa giải đã cố gắng hòa giải cả hai bên trong quá trình đàm phán.","k":"conciliate, conciliatory"},{"t":"plausible, \nplausibility","p":"adjective","d":"hợp lý, \ntính hợp lý","e":"The explanation seemed plausible at first glance.","ev":"Giải thích có vẻ hợp lý ngay từ cái nhìn đầu tiên.","k":"plausible, plausibility"}]},{"n":"Buổi 30","c":[{"t":"indignant","p":"adjective","d":"phẫn nộ","e":"She felt indignant at the unfair treatment she received from her boss.","ev":"Cô cảm thấy phẫn nộ trước sự đối xử bất công mà cô nhận được từ sếp.","k":"indignant"},{"t":"oracle","p":"noun","d":"lời tiên tri","e":"The oracle foretold the future.","ev":"Người tiên tri đã dự đoán tương lai.","k":"oracle"},{"t":"egalitarian","p":"adjective","d":"bình đẳng","e":"The country promotes an egalitarian society where everyone has equal rights.","ev":"Quốc gia này thúc đẩy một xã hội bình đẳng nơi mọi người có quyền lợi như nhau.","k":"egalitarian"},{"t":"deference, \ndeferential","p":"noun/adjective","d":"sự tôn trọng, \ncung kính","e":"He showed great deference to his elders during the ceremony.","ev":"Anh đã thể hiện sự tôn trọng lớn đối với những người lớn tuổi hơn trong buổi lễ.","k":"deference, deferential"},{"t":"self-serving","p":"adjective","d":"vị kỷ","e":"Her self-serving motives were obvious to everyone in the room.","ev":"Động cơ vị kỷ của cô rõ ràng với mọi người trong phòng.","k":"self-serving"},{"t":"digress(ion)","p":"verb/noun","d":"lạc đề, ra ngoài đề","e":"During the presentation, she took a brief digression to share a personal story.","ev":"Trong buổi thuyết trình, cô ấy đã tạm thời lạc đề chia sẻ một câu chuyện cá nhân.","k":"digress(ion)"},{"t":"epitome, epitomize","p":"noun, verb","d":"điển hình, điển hình hóa","e":"She is the epitome of grace and elegance, and her performance perfectly epitomized the theme of the ballet.","ev":"Cô ấy là hình mẫu của sự duyên dáng và thanh lịch, và màn trình diễn của cô hoàn toàn tiêu biểu cho chủ đề của buổi ballet.","k":"epitome, epitomize"},{"t":"unwitting","p":"adjective","d":"vô tình","e":"The unwitting participant had no idea what was about to happen.","ev":"Người tham gia không hay biết đã không biết điều gì sắp xảy ra.","k":"unwitting"},{"t":"autocrat, autocratic","p":"noun","d":"chuyên quyền, chuyên quyền","e":"The autocrat ruled with an iron fist, leaving no room for dissent.","ev":"Nhà độc tài cai trị bằng bàn tay sắt, không lại chỗ cho sự bất đồng.","k":"autocrat, autocratic"},{"t":"germinate","p":"verb","d":"nảy mầm","e":"The seeds will germinate when the conditions are right.","ev":"Hạt sẽ nảy mầm khi các điều kiện thuận lợi.","k":"germinate"},{"t":"devoid","p":"adjective","d":"không có","e":"The area was devoid of wildlife due to extensive urban development.","ev":"Khu vực này hoàn toàn thiếu động vật hoang dã do sự phát triển đô thị rộng rãi.","k":"devoid"},{"t":"idiosyncracy, \nidiosyncratic","p":"noun/adj","d":"sự khác biệt, \ncó phong cách riêng","e":"Her idiosyncrasy of collecting vintage postcards made her unique among her friends.","ev":"Thói quen kỳ quặc của cô trong việc thu thập bưu thiếp cổ điển khiến cô trở nên độc đáo trong số bạn bè.","k":"idiosyncracy, idiosyncratic"},{"t":"charlatan","p":"noun","d":"lang băm","e":"The charlatan promised miraculous results.","ev":"Kẻ lừa đảo hứa hẹn kết quả kỳ diệu.","k":"charlatan"},{"t":"pliable, pliant","p":"adjective","d":"dẻo, dễ uốn","e":"The material is pliable and can be easily shaped into different forms.","ev":"Chất liệu này dẻo và có thể dễ dàng tạo hình thành các dạng khác nhau.","k":"pliable, pliant"},{"t":"gargantuan","p":"verb","d":"khổng lồ","e":"The gargantuan statue drew visitors from all over the world.","ev":"Bức tượng khổng lồ thu hút du khách từ khắp nơi trên thế giới.","k":"gargantuan"},{"t":"unabashed","p":"adjective","d":"không nao núng","e":"She was unabashed about her opinions, expressing them freely at the meeting.","ev":"Cô không hề xấu hổ về ý kiến của mình, tự do bày tỏ chúng trong cuộc họp.","k":"unabashed"},{"t":"virtuoso, virtuosity","p":"noun","d":"sự điêu luyện, sự điêu luyện","e":"The young musician displayed virtuosity beyond his years during the performance.","ev":"Nhạc sĩ trẻ đã thể hiện tài năng vượt trội hơn cả tuổi của mình trong buổi biểu diễn.","k":"virtuoso, virtuosity"},{"t":"stupefy, \nstupefaction","p":"verb/noun","d":"choáng váng, \nsửng sốt","e":"The magician's performance left the audience in a state of stupefaction.","ev":"Màn trình diễn của ảo thuật gia đã khiến khán giả rơi vào trạng thái choáng váng.","k":"stupefy, stupefaction"},{"t":"belligerent","p":"adjective","d":"hiếu chiến","e":"His belligerent attitude caused many conflicts.","ev":"Thái độ hiếu chiến của anh ta đã gây ra nhiều xung đột.","k":"belligerent"},{"t":"listless","p":"adjective","d":"bơ phờ, uể oải","e":"She felt listless and uninspired after a long week of work.","ev":"Cô cảm thấy uể oải và không có cảm hứng sau một tuần làm việc dài.","k":"listless"}]},{"n":"Buổi 31","c":[{"t":"discomfited","p":"adjective","d":"không thoải mái","e":"She felt discomfited by the unexpected question during the interview.","ev":"Cô cảm thấy khó chịu trước câu hỏi bất ngờ trong buổi phỏng vấn.","k":"discomfited"},{"t":"ravenous","p":"noun","d":"đói cồn cào","e":"After skipping breakfast, he felt ravenous by lunchtime.","ev":"Sau khi bỏ bữa sáng, anh cảm thấy đói cồn cào vào giờ ăn trưa.","k":"ravenous"},{"t":"self-righteous","p":"adjective","d":"tự cho mình là đúng","e":"His self-righteous attitude alienated his friends.","ev":"Thái độ tự mãn của anh đã khiến bạn bè xa lánh.","k":"self-righteous"},{"t":"gait","p":"noun","d":"dáng đi","e":"She walked with a graceful gait.","ev":"Cô ấy đi với dáng đi uyển chuyển.","k":"gait"},{"t":"provident","p":"adjective","d":"lo xa, tiết kiệm","e":"She was provident enough to save money for her children’s education.","ev":"Cô đủ khôn ngoan tiết kiệm tiền cho việc học của con cái.","k":"provident"},{"t":"repugnant","p":"adjective","d":"đáng ghét","e":"The repugnant behavior of the character in the film made it hard to watch.","ev":"Hành vi ghê tởm của nhân vật trong bộ phim khiến việc xem trở nên khó khăn.","k":"repugnant"},{"t":"satire, satirical, \nsatirize","p":"noun/adjective/verb","d":"châm biếm, châm biếm, \nchâm biếm","e":"The book is a satire that critiques societal norms with humor.","ev":"Cuốn sách là một tác phẩm châm biếm chỉ trích các quy tắc xã hội bằng sự hài hước.","k":"satire, satirical, satirize"},{"t":"depreciation, \ndepreciatory","p":"noun","d":"khấu hao, \nmất giá","e":"The depreciation of the currency has affected the economy negatively.","ev":"Sự giảm giá của đồng tiền đã ảnh hưởng tiêu cực đến nền kinh tế.","k":"depreciation, depreciatory"},{"t":"totalitarian","p":"noun","d":"toàn trị","e":"The totalitarian regime controlled every aspect of citizens’ lives.","ev":"Chế độ độc tài kiểm soát mọi khía cạnh trong cuộc sống của công dân.","k":"totalitarian"},{"t":"tribulation","p":"noun","d":"khổ cực, thử thách","e":"They faced many tribulations during their journey but persevered through them all.","ev":"Họ đã phải đối mặt với nhiều thử thách trong suốt hành trình nhưng đã kiên trì vượt qua tất cả.","k":"tribulation"},{"t":"saturate","p":"verb","d":"bão hòa","e":"The sponge will saturate with water if left in it for too long.","ev":"Bọt biển sẽ bão hòa với nước nếu trong đó quá lâu.","k":"saturate"},{"t":"mitigate, mitigator","p":"verb/noun","d":"giảm nhẹ, giảm nhẹ","e":"We need to find ways to mitigate the risks associated with the project.","ev":"Chúng ta cần tìm cách giảm thiểu những rủi ro liên quan đến dự án.","k":"mitigate, mitigator"},{"t":"sanction","p":"verb","d":"sự trừng phạt","e":"The government decided to sanction the new regulations to improve safety standards.","ev":"Chính phủ quyết định phê chuẩn các quy định mới cải thiện tiêu chuẩn an toàn.","k":"sanction"},{"t":"lackadaisical","p":"adjective","d":"thiếu quyết tâm, hời hợt","e":"His lackadaisical approach to studying resulted in low grades.","ev":"Cách tiếp cận thiếu quyết tâm của anh đối với việc học đã dẫn đến điểm số thấp.","k":"lackadaisical"},{"t":"ratify","p":"verb","d":"phê chuẩn","e":"The treaty must be ratified by both countries before it takes effect.","ev":"Hiệp ước phải được cả hai quốc gia phê chuẩn trước khi có hiệu lực.","k":"ratify"},{"t":"insolence, insolent","p":"noun/adj","d":"xấc xược, xấc xược","e":"The insolent behavior of the student earned him a detention.","ev":"Hành vi hỗn láo của học sinh đã khiến anh bị phạt ở lại lớp.","k":"insolence, insolent"},{"t":"burgeon","p":"verb","d":"đang phát triển","e":"The plant began to burgeon once the spring rains arrived.","ev":"Cây bắt đầu nảy nở khi những cơn mưa mùa xuân đến.","k":"burgeon"},{"t":"magnanimity, \nmagnanimous","p":"adj/noun","d":"sự hào hùng, \ncao thượng","e":"Her magnanimity in forgiving others made her well-respected in the community.","ev":"Tấm lòng rộng lượng của cô trong việc tha thứ cho người khác khiến cô được tôn trọng trong cộng đồng.","k":"magnanimity, magnanimous"},{"t":"heresy, heretic","p":"noun","d":"dị giáo, dị giáo","e":"Accusing him of heresy, the church declared him a heretic and excommunicated him.","ev":"Buộc tội anh dị giáo, nhà thờ tuyên bố anh là người dị giáo và đã tước bỏ quyền giáo hội của anh.","k":"heresy, heretic"},{"t":"fraudulent","p":"adjective","d":"lừa đảo","e":"The fraudulent scheme was uncovered by authorities.","ev":"Kế hoạch gian lận đã bị các cơ quan phát hiện.","k":"fraudulent"}]},{"n":"Buổi 32","c":[{"t":"rancor(ous)","p":"noun/adjective","d":"cay đắng","e":"There was rancor in his voice as he spoke about his former colleague.","ev":"Có sự cay đắng trong giọng nói của anh khi anh nói về người đồng nghiệp cũ.","k":"rancor(ous)"},{"t":"succulent","p":"adjective","d":"mọng nước","e":"The steak was juicy and succulent.","ev":"Miếng bít tết thật ngon và mọng nước.","k":"succulent"},{"t":"hasten","p":"verb","d":"nhanh lên","e":"Please hasten your response.","ev":"Xin vui lòng trả lời nhanh chóng.","k":"hasten"},{"t":"empathetic, \nempathy","p":"adjective/noun","d":"đồng cảm, \nsự đồng cảm","e":"His empathetic nature allowed him to connect with others easily.","ev":"Tính cách đồng cảm của anh giúp anh dễ dàng kết nối với người khác.","k":"empathetic, empathy"},{"t":"futile, futility","p":"adj/n","d":"vô ích, vô ích","e":"Their efforts to resolve the issue seemed futile in the face of such strong opposition.","ev":"Nỗ lực của họ giải quyết vấn đề có vẻ vô nghĩa trước sự phản đối mạnh mẽ như vậy.","k":"futile, futility"},{"t":"palliate, palliative","p":"noun","d":"làm dịu đi, xoa dịu","e":"They tried to palliate the pain with medication.","ev":"Họ đã cố gắng giảm nhẹ cơn đau bằng thuốc.","k":"palliate, palliative"},{"t":"relinquish","p":"verb","d":"từ bỏ","e":"He decided to relinquish his claim to the inheritance.","ev":"Anh quyết định từ bỏ quyền thừa kế của mình.","k":"relinquish"},{"t":"sanctity","p":"noun","d":"sự thánh thiện","e":"The sanctity of the ancient site was preserved by strict regulations.","ev":"Tính thiêng liêng của địa điểm cổ đại được bảo tồn bởi các quy định nghiêm ngặt.","k":"sanctity"},{"t":"virulent","p":"adjective","d":"độc ác","e":"The virus was particularly virulent this season.","ev":"Virus này đặc biệt mạnh mẽ trong mùa này.","k":"virulent"},{"t":"lull","p":"noun/verb","d":"ru ngủ","e":"The gentle lull of the waves made him feel relaxed and at peace.","ev":"Âm thanh nhẹ nhàng của sóng khiến anh cảm thấy thư giãn và bình yên.","k":"lull"},{"t":"inert, inertia","p":"adj/noun","d":"trơ, quán tính","e":"The inert materials in the reaction did not contribute to the outcome.","ev":"Các vật liệu bất động trong phản ứng không góp phần vào kết quả.","k":"inert, inertia"},{"t":"regressive","p":"adjective","d":"thoái lui, thụt lùi","e":"The policy was seen as regressive.","ev":"Chính sách đó được coi là thụt lùi.","k":"regressive"},{"t":"spurn","p":"verb","d":"bị hắt hủi","e":"She spurned his invitation to the party, preferring to stay home.","ev":"Cô đã từ chối lời mời của anh đến bữa tiệc, thích ở nhà hơn.","k":"spurn"},{"t":"anthropology","p":"noun","d":"nhân học","e":"Anthropology provides insights into human behavior and culture.","ev":"Nhân học cung cấp những hiểu biết về hành vi và văn hóa của con người.","k":"anthropology"},{"t":"latent, latency","p":"adjective","d":"tiềm ẩn, độ trễ","e":"The scientist studied the latent effects of the drug over several months.","ev":"Nhà khoa học đã nghiên cứu tác động tiềm ẩn của thuốc trong vài tháng.","k":"latent, latency"},{"t":"refutation, refute","p":"noun","d":"sự bác bỏ, bác bỏ","e":"The refutation of his argument was thorough.","ev":"Sự bác bỏ lập luận của anh ta rất thấu đáo.","k":"refutation, refute"},{"t":"plethora, plethoric","p":"noun","d":"sự dồi dào, phong phú","e":"There was a plethora of options available for consumers in the market.","ev":"Có rất nhiều sự lựa chọn cho người tiêu dùng trên thị trường.","k":"plethora, plethoric"},{"t":"hubris","p":"noun","d":"ngạo mạn","e":"His hubris ultimately led to his downfall.","ev":"Sự kiêu ngạo của anh cuối cùng đã dẫn đến sự sụp đổ của mình.","k":"hubris"},{"t":"encompass","p":"verb","d":"bao gồm","e":"The project aims to encompass a wide range of topics relevant to climate change.","ev":"Dự án nhằm bao quát nhiều chủ đề liên quan đến biến đổi khí hậu.","k":"encompass"},{"t":"prospective","p":"noun","d":"triển vọng","e":"They are prospective clients.","ev":"Họ là những khách hàng tiềm năng.","k":"prospective"}]},{"n":"Buổi 33","c":[{"t":"reticent, reticence","p":"adjective/noun","d":"sự dè dặt, sự dè dặt","e":"She was reticent about her personal life, preferring to keep her thoughts private.","ev":"Cô ấy rất kín đáo về cuộc sống cá nhân, thích giữ suy nghĩ của mình trong im lặng.","k":"reticent, reticence"},{"t":"buoyant","p":"adjective","d":"bồng bềnh","e":"Despite the challenges, she remained buoyant and optimistic about the future.","ev":"Mặc dù gặp nhiều khó khăn, cô vẫn giữ tinh thần phấn chấn và lạc quan về tương lai.","k":"buoyant"},{"t":"deterrent","p":"noun/adjective","d":"răn đe","e":"The new law was introduced as a deterrent against reckless driving.","ev":"Luật mới được giới thiệu như một biện pháp răn đe chống lại việc lái xe liều lĩnh.","k":"deterrent"},{"t":"histrionic","p":"adjective","d":"lịch sử","e":"His histrionic behavior during the meeting drew eye rolls from his colleagues.","ev":"Cách cư xử kịch tính của anh ấy trong cuộc họp đã khiến đồng nghiệp phải lắc đầu.","k":"histrionic"},{"t":"incongruity, \nincongruous","p":"noun/adjective","d":"sự không nhất quán, \nkhông thích hợp","e":"The incongruity of wearing a winter coat in summer made everyone laugh.","ev":"Sự không phù hợp của việc mặc áo khoác mùa đông vào mùa hè khiến mọi người buồn cười.","k":"incongruity, incongruous"},{"t":"marred","p":"adjective","d":"bị hỏng, bị hư hại","e":"The painting was marred by water damage.","ev":"Bức tranh bị hư hại bởi nước.","k":"marred"},{"t":"credulity, \ncredulous","p":"noun","d":"hay tin, \ncả tin","e":"His credulity made him an easy target for scams and fraud.","ev":"Sự cả tin của anh khiến anh trở thành mục tiêu dễ dàng cho những vụ lừa đảo.","k":"credulity, credulous"},{"t":"rhetoric(al), \nrhetorician","p":"noun/adjective","d":"hùng biện(al), \nnhà hùng biện","e":"His rhetorical skills captivated the audience during the debate.","ev":"Kỹ năng hùng biện của anh ấy đã thu hút sự chú ý của khán giả trong cuộc tranh luận.","k":"rhetoric(al), rhetorician"},{"t":"folly","p":"noun","d":"sự điên rồ, dại dột","e":"It was sheer folly to invest all her savings in a single venture.","ev":"Đó là sự ngu dốt khi đầu tư tất cả tiền tiết kiệm của cô vào một dự án duy nhất.","k":"folly"},{"t":"elated, elation","p":"adjective/noun","d":"phấn chấn, phấn khởi","e":"She felt elated after receiving the good news about her promotion.","ev":"Cô cảm thấy hạnh phúc sau khi nhận được tin tốt về việc thăng chức.","k":"elated, elation"},{"t":"contemptible","p":"adjective","d":"đáng khinh","e":"His contemptible behavior during the meeting shocked everyone.","ev":"Hành vi đáng khinh của anh trong cuộc họp đã làm mọi người sốc.","k":"contemptible"},{"t":"exacting","p":"adjective","d":"chính xác","e":"The project was exacting and required a lot of attention to detail.","ev":"Dự án này đòi hỏi sự chính xác và cần nhiều sự chú ý đến từng chi tiết.","k":"exacting"},{"t":"Evenhandedness","p":"noun","d":"Sự công bằng","e":"strive for evenhandedness, save us from the errors of partisans and zealots.","ev":"phấn đấu cho sự công bằng, cứu chúng ta khỏi sai lầm của những kẻ theo đảng phái và những kẻ cuồng nhiệt.","k":"evenhandedness"},{"t":"distaste","p":"noun","d":"không ưa, ghê tởm","e":"She felt a deep distaste for dishonesty in any form.","ev":"Cô cảm thấy sự ghê tởm sâu sắc đối với sự không trung thực dưới bất kỳ hình thức nào.","k":"distaste"},{"t":"truculent, \ntruculence","p":"adjective/noun","d":"hung dữ, \nsự hung hãn","e":"The truculent attitude of the player led to several penalties during the game.","ev":"Thái độ hung hãn của cầu thủ đã dẫn đến nhiều hình phạt trong trận đấu.","k":"truculent, truculence"},{"t":"diffident, diffidence","p":"adjective/noun","d":"nhút nhát/tự ti","e":"Her diffident manner made her hesitant to speak up in meetings.","ev":"Cách cư xử nhút nhát của cô khiến cô do dự khi phát biểu trong các cuộc họp.","k":"diffident, diffidence"},{"t":"automaton","p":"noun","d":"một người hành xử như robot","e":"He moved through life like an automaton, going through the motions without passion.","ev":"Anh sống như một người máy, thực hiện mọi việc mà không có đam mê.","k":"automaton"},{"t":"desecration","p":"noun","d":"sự xúc phạm","e":"The desecration of the historic site sparked outrage among the community.","ev":"Hành vi xúc phạm địa điểm lịch sử đã gây ra sự phẫn nộ trong cộng đồng.","k":"desecration"},{"t":"mercenary","p":"noun","d":"lính đánh thuê","e":"The mercenary soldier fought for whoever paid the highest wage.","ev":"Người lính đánh thuê chiến đấu cho bất cứ ai trả lương cao nhất.","k":"mercenary"},{"t":"dupe","p":"verb","d":"lừa gạt, bịp bợm","e":"Don't let him dupe you with his charm.","ev":"Đừng anh ta lừa gạt bạn bằng sự quyến rũ của mình.","k":"dupe"}]},{"n":"Buổi 34","c":[{"t":"slipshod","p":"adjective","d":"cẩu thả","e":"She complained that the carpenter's work had been slipshod.","ev":"Cô ấy phàn nàn rằng sản phẩm của người thợ mộc thật cẩu thả","k":"slipshod"},{"t":"exemplar","p":"noun","d":"hình mẫu","e":"She serves as an exemplar of hard work and dedication for her colleagues.","ev":"Cô ấy là hình mẫu của sự chăm chỉ và cống hiến cho đồng nghiệp của mình.","k":"exemplar"},{"t":"frugal(ity)","p":"adjective","d":"(sự) tiết kiệm","e":"He lived a frugal lifestyle, saving money wherever he could.","ev":"Anh sống một cuộc sống tiết kiệm, tiết kiệm tiền bất cứ khi nào có thể.","k":"frugal(ity)"},{"t":"stock","p":"adjective","d":"khuôn mẫu, lặp lại","e":"The stock response from the spokesperson lacked genuine insight into the issue.","ev":"Phản ứng theo mẫu từ người phát ngôn thiếu sự hiểu biết chân thật về vấn đề.","k":"stock"},{"t":"prattle","p":"verb/noun","d":"chuyện tầm phào","e":"They engaged in prattle, discussing trivial matters instead of the main topic.","ev":"Họ đã nói mấy chuyện tầm phào, bàn về những vấn đề tầm thường thay vì chủ đề chính.","k":"prattle"},{"t":"somber","p":"adjective","d":"ảm đạm","e":"The somber mood at the funeral reflected the loss felt by everyone.","ev":"Bầu không khí u ám tại tang lễ phản ánh nỗi mất mát mà mọi người đều cảm thấy.","k":"somber"},{"t":"enigma(tic)","p":"noun","d":"bí ẩn","e":"The enigma of her disappearance puzzled everyone.","ev":"Bí ẩn về sự biến mất của cô ấy làm mọi người bối rối.","k":"enigma(tic)"},{"t":"conscientious","p":"adjective","d":"tận tâm","e":"She is a conscientious worker who pays attention to every detail.","ev":"Cô là một nhân viên tận tâm, luôn chú ý đến từng chi tiết.","k":"conscientious"},{"t":"steadfast","p":"adjective","d":"kiên định","e":"She remained steadfast in her beliefs, even when challenged.","ev":"Cô giữ vững niềm tin của mình, ngay cả khi bị thách thức.","k":"steadfast"},{"t":"painstaking","p":"adjective","d":"siêng năng, tỉ mỉ","e":"Her painstaking attention to detail made her an excellent editor.","ev":"Sự chú ý tỉ mỉ đến từng chi tiết của cô đã làm cho cô trở thành một biên tập viên xuất sắc.","k":"painstaking"},{"t":"boorish, \nboorishness","p":"noun","d":"thô lỗ, \nsự thô lỗ","e":"His boorish behavior at the dinner party embarrassed everyone.","ev":"Hành vi thô lỗ của anh ấy tại bữa tiệc tối đã làm xấu hổ mọi người.","k":"boorish, boorishness"},{"t":"indict(ment)","p":"verb/noun","d":"cáo trạng","e":"The indictment accused him of multiple counts of fraud.","ev":"Cáo trạng buộc tội anh về nhiều tội danh gian lận.","k":"indict(ment)"},{"t":"contempt(uous)","p":"adjective","d":"khinh miệt","e":"She looked at the critic with a contemptuous expression after the harsh review.","ev":"Cô nhìn người phê bình bằng vẻ mặt khinh bỉ sau bài đánh giá gay gắt.","k":"contempt(uous)"},{"t":"repertory","p":"noun","d":"việc trình diễn lặp đi lặp lại nhiều vở kịch liên tiếp nhau","e":"The repertory theater produces a variety of plays throughout the year.","ev":"Nhà hát sản xuất nhiều vở kịch khác nhau trong suốt cả năm.","k":"repertory"},{"t":"attenuate","p":"verb","d":"giảm bớt","e":"The new law will attenuate the effects of pollution in the city.","ev":"Luật mới sẽ làm giảm tác động của ô nhiễm trong thành phố.","k":"attenuate"},{"t":"exposé","p":"noun","d":"bài báo điều tra","e":"The exposé revealed the truth behind the scandal.","ev":"Bài báo điều tra tiết lộ sự thật về vụ bê bối.","k":"exposé"},{"t":"discern, discerning","p":"verb","d":"phân biệt, sáng suốt","e":"She could discern the subtle differences between the two paintings.","ev":"Cô có thể nhận biết những khác biệt tinh tế giữa hai bức tranh.","k":"discern, discerning"},{"t":"peremptory","p":"adjective","d":"độc đoán","e":"The boss's peremptory order left no room for discussion.","ev":"Mệnh lệnh độc đoán của sếp không chừa lại chỗ cho thảo luận.","k":"peremptory"},{"t":"staunch","p":"adjective","d":"trung thành","e":"He is a staunch supporter of environmental protection policies.","ev":"Anh là một người ủng hộ vững chắc cho các chính sách bảo vệ môi trường.","k":"staunch"},{"t":"zealot","p":"noun","d":"cuồng nhiệt","e":"The zealot could not tolerate any views that opposed his beliefs.","ev":"Người cuồng tín không thể chấp nhận bất kỳ quan điểm nào trái ngược với niềm tin của mình.","k":"zealot"}]},{"n":"Buổi 35","c":[{"t":"opportunist, \nopportunistic","p":"adj/noun","d":"người cơ hội, \ncơ hội","e":"The opportunist took advantage of the situation to advance his own agenda.","ev":"Kẻ cơ hội đã lợi dụng tình huống thúc đẩy chương trình của riêng mình.","k":"opportunist, opportunistic"},{"t":"embitter(ed)","p":"adjective","d":"cay đắng(ed)","e":"Years of resentment had embittered him.","ev":"Nhiều năm oán hận đã làm cho anh ta cay đắng.","k":"embitter(ed)"},{"t":"treatise","p":"noun","d":"chuyên luận","e":"The treatise on philosophy provided a deep analysis of existential questions.","ev":"Luận văn về triết học đã cung cấp một phân tích sâu sắc về các câu hỏi tồn tại.","k":"treatise"},{"t":"lugubrious","p":"adjective","d":"thảm, thảm bi","e":"a lugubrious face","ev":"một khuôn mặt buồn thảm","k":"lugubrious"},{"t":"solace","p":"noun/verb","d":"sự an ủi","e":"He found solace in music during difficult times.","ev":"Anh tìm thấy sự an ủi trong âm nhạc trong những lúc khó khăn.","k":"solace"},{"t":"jocular","p":"adjective","d":"vui tính","e":"His jocular personality made him the life of the party.","ev":"Tính cách vui vẻ của anh đã khiến anh trở thành tâm điểm của bữa tiệc.","k":"jocular"},{"t":"solicitous(ness)","p":"adj/noun","d":"sự quan tâm","e":"She was solicitous about her friend’s well-being after the accident.","ev":"Cô đã rất quan tâm đến sức khỏe của bạn mình sau vụ tai nạn.","k":"solicitous(ness)"},{"t":"compendious","p":"adjective","d":"tổng quát, súc tích","e":"The book provides a compendious overview of modern philosophy in just a few chapters.","ev":"Cuốn sách cung cấp cái nhìn tổng quát ngắn gọn về triết học hiện đại chỉ trong vài chương.","k":"compendious"},{"t":"pronouncement","p":"noun","d":"sự tuyên bố","e":"The pronouncement from the committee shocked everyone in attendance.","ev":"Tuyên bố từ ủy ban khiến mọi người có mặt đều sốc.","k":"pronouncement"},{"t":"depose","p":"verb","d":"hạ bệ","e":"The council decided to depose the corrupt mayor after the investigation.","ev":"Hội đồng quyết định lật đổ thị trưởng tham nhũng sau cuộc điều tra.","k":"depose"},{"t":"wry","p":"adjective","d":"khinh khỉnh","e":"She gave a wry smile when she heard the ironic comment.","ev":"Cô mỉm cười khinh khỉnh khi nghe nhận xét châm biếm.","k":"wry"},{"t":"oversight","p":"noun","d":"bỏ sót","e":"The oversight in the report led to significant errors in the final analysis.","ev":"Sự bỏ sót trong báo cáo đã dẫn đến những sai sót lớn trong phân tích cuối cùng.","k":"oversight"},{"t":"bipartisanship","p":"noun","d":"lưỡng đảng","e":"Bipartisanship is essential for passing significant legislation.","ev":"Sự hợp tác giữa hai đảng là cần thiết thông qua các luật quan trọng.","k":"bipartisanship"},{"t":"obstinate, -acy","p":"adjective","d":"cố chấp","e":"His obstinate refusal to listen caused a rift in their relationship.","ev":"Việc anh cứng đầu từ chối lắng nghe đã gây ra một cuộc rạn nứt trong mối quan hệ của họ.","k":"obstinate, -acy"},{"t":"pacify","p":"verb","d":"làm dịu đi","e":"He tried to pacify the angry crowd with a sincere apology.","ev":"Anh cố gắng làm dịu lòng đám đông giận dữ bằng một lời xin lỗi chân thành.","k":"pacify"},{"t":"demystify","p":"verb","d":"làm sáng tỏ","e":"The goal was to demystify complex theories.","ev":"Mục tiêu là làm rõ những lý thuyết phức tạp.","k":"demystify"},{"t":"irony, ironic","p":"noun","d":"mỉa mai","e":"The irony of the situation was not lost on anyone.","ev":"Sự mỉa mai của tình huống không bị bỏ qua với bất kỳ ai.","k":"irony, ironic"},{"t":"rampant","p":"adjective","d":"tràn lan","e":"The rampant spread of misinformation is a serious issue in today's society.","ev":"Sự lan truyền tràn lan của thông tin sai lệch là một vấn đề nghiêm trọng trong xã hội ngày nay.","k":"rampant"},{"t":"uncouth","p":"adjective","d":"thô lỗ","e":"His uncouth behavior at the formal dinner shocked the guests.","ev":"Hành vi thô lỗ của anh tại bữa tối trang trọng đã làm cho các vị khách sốc.","k":"uncouth"},{"t":"estrange, \nestrangement","p":"verb/noun","d":"ghẻ lạnh,  xa cách","e":"The estrangement between the siblings was painful to witness.","ev":"Sự xa cách giữa các anh chị em thật đau lòng khi chứng kiến.","k":"estrange, estrangement"}]},{"n":"Buổi 36","c":[{"t":"dauntless","p":"adjective","d":"dũng cảm","e":"His dauntless spirit inspired others to face their fears.","ev":"Tinh thần không sợ hãi của anh đã truyền cảm hứng cho người khác đối mặt với nỗi sợ hãi của họ.","k":"dauntless"},{"t":"peevish","p":"adjective","d":"gắt gỏng","e":"She was peevish and irritable after missing her morning coffee.","ev":"Cô trở nên cáu kỉnh và khó chịu sau khi bỏ lỡ ly cà phê buổi sáng.","k":"peevish"},{"t":"glutton(ous)","p":"noun/adj","d":"kẻ háu ăn, ham làm gì","e":"He was a glutton for punishment.","ev":"Anh ta là người thích chịu đựng khổ sở.","k":"glutton(ous)"},{"t":"precarious","p":"adjective","d":"bấp bênh","e":"The precarious situation required careful handling.","ev":"Tình huống không ổn định đòi hỏi sự xử lý cẩn thận.","k":"precarious"},{"t":"tenacious, tenacity","p":"adj/n","d":"sự kiên cường, sự kiên cường","e":"Her tenacious efforts to improve her skills eventually paid off.","ev":"Nỗ lực kiên trì của cô cải thiện kỹ năng cuối cùng đã được đền đáp.","k":"tenacious, tenacity"},{"t":"ineptitude","p":"noun","d":"sự kém cỏi, bất tài","e":"His ineptitude in handling the situation caused further complications.","ev":"Sự bất tài của anh trong việc xử lý tình huống đã gây ra những phức tạp thêm.","k":"ineptitude"},{"t":"erudite, erudition","p":"noun","d":"uyên bác, uyên bác","e":"The erudite professor captivated the students with his extensive knowledge.","ev":"Giáo sư uyên bác đã thu hút sinh viên bằng kiến thức phong phú của mình.","k":"erudite, erudition"},{"t":"florid(ity)","p":"adjective/noun","d":"(sự) hoa mỹ","e":"The author's floridity in writing can make even simple ideas seem extravagant.","ev":"Sự hoa mỹ trong cách viết của tác giả có thể khiến ngay cả những ý tưởng đơn giản cũng trở nên cầu kỳ.","k":"florid(ity)"},{"t":"flummox","p":"verb","d":"thất thường","e":"The unexpected question flummoxed him, leaving him speechless.","ev":"Câu hỏi bất ngờ đã khiến anh bối rối, khiến anh câm lặng.","k":"flummox"},{"t":"foolhardy","p":"adjective","d":"sự liều lĩnh, ngu ngốc","e":"It was foolhardy to attempt such a dangerous climb without proper equipment.","ev":"Thật ngu ngốc khi cố gắng leo núi nguy hiểm như vậy mà không có thiết bị thích hợp.","k":"foolhardy"},{"t":"chagrin","p":"noun","d":"sự thất vọng","e":"To her chagrin, she realized she had forgotten her friend’s birthday.","ev":"Đến nỗi xấu hổ, cô nhận ra rằng mình đã quên sinh nhật của bạn.","k":"chagrin"},{"t":"embroil(ed)","p":"verb","d":"cuốn vào","e":"The company became embroiled in a legal dispute over its new product line.","ev":"Công ty đã bị cuốn vào một tranh chấp pháp lý liên quan đến dòng sản phẩm mới.","k":"embroil(ed)"},{"t":"decimate","p":"verb","d":"tàn sát, tiêu diệt","e":"The disease could decimate the population.","ev":"Bệnh dịch có thể tiêu diệt dân số.","k":"decimate"},{"t":"vindicate, \nvindication","p":"verb/noun","d":"minh oan, \nsự minh oan","e":"The evidence helped to vindicate her after the allegations were made.","ev":"Bằng chứng đã giúp biện minh cho cô sau khi có những cáo buộc được đưa ra.","k":"vindicate, vindication"},{"t":"churlish","p":"adjective","d":"thô lỗ","e":"His churlish remarks during the meeting alienated his colleagues.","ev":"Những nhận xét thô lỗ của anh trong cuộc họp đã làm xa lánh đồng nghiệp.","k":"churlish"},{"t":"stagnant, \nstagnation","p":"adjective/noun","d":"trì trệ, \nsự trì trệ","e":"The stagnant water in the pond was a breeding ground for mosquitoes.","ev":"Nước đọng trong ao là môi trường sinh sản cho muỗi.","k":"stagnant, stagnation"},{"t":"indeterminate","p":"adjective","d":"không xác định","e":"The outcome was indeterminate until the last minute.","ev":"Kết quả không xác định cho đến phút cuối.","k":"indeterminate"},{"t":"recluse, reclusive","p":"noun/adjective","d":"ẩn dật, ẩn dật","e":"He lived as a recluse, rarely leaving his home or interacting with others.","ev":"Anh sống như một người ẩn dật, hiếm khi rời khỏi nhà hoặc giao tiếp với người khác.","k":"recluse, reclusive"},{"t":"disputatious","p":"adjective","d":"gây tranh cãi","e":"Her disputatious nature often led to arguments with her colleagues.","ev":"Tính cách thích tranh cãi của cô thường dẫn đến những cuộc cãi vã với đồng nghiệp.","k":"disputatious"},{"t":"incubate","p":"verb","d":"ấp, ủ","e":"The eggs will incubate for about three weeks before hatching.","ev":"Những quả trứng sẽ được ấp trong khoảng ba tuần trước khi nở.","k":"incubate"}]},{"n":"Buổi 37","c":[{"t":"consternation","p":"noun","d":"sự hoang mang, sửng sốt","e":"The announcement of layoffs caused consternation among the employees.","ev":"Thông báo về việc cắt giảm nhân sự đã gây ra sự hoang mang trong số nhân viên.","k":"consternation"},{"t":"shroud","p":"noun","d":"bức màn, vải che","e":"The fog acted like a shroud over the city.","ev":"Sương mù bao phủ thành phố như một lớp khăn.","k":"shroud"},{"t":"abhor, abhorrence","p":"verb/noun","d":"ghê tởm, ghê tởm","e":"He abhors cruelty to animals and advocates for their protection.","ev":"Anh ấy ghê tởm sự tàn ác đối với động vật và ủng hộ việc bảo vệ chúng.","k":"abhor, abhorrence"},{"t":"redolent","p":"adjective","d":"mùi thơm","e":"The garden was redolent of roses.","ev":"Khu vườn có mùi thơm của hoa hồng.","k":"redolent"},{"t":"luxuriant","p":"adjective","d":"um tùm","e":"The luxuriant gardens were filled with exotic plants and flowers.","ev":"Những khu vườn tươi tốt đầy những loại cây và hoa kỳ lạ.","k":"luxuriant"},{"t":"temporize","p":"verb","d":"tạm thời","e":"They decided to temporize until a decision was made.","ev":"Họ quyết định trì hoãn cho đến khi có quyết định.","k":"temporize"},{"t":"vanquish","p":"verb","d":"đánh bại","e":"They aimed to vanquish their opponents.","ev":"Họ nhằm mục đích đánh bại đối thủ.","k":"vanquish"},{"t":"laggard","p":"noun/adjective","d":"chậm chạp","e":"The laggard student finally turned in his assignment after much delay.","ev":"Sinh viên chậm chạp cuối cùng cũng đã nộp bài tập của mình sau nhiều lần trì hoãn.","k":"laggard"},{"t":"notoriety, \nnotorious","p":"noun/adj","d":"tai tiếng, \nkhét tiếng","e":"The notoriety of the criminal made headlines across the country.","ev":"Sự khét tiếng của tên tội phạm này đã trở thành tiêu đề trên khắp cả nước.","k":"notoriety, notorious"},{"t":"rectify, rectitude","p":"noun","d":"sửa chữa, sự đúng đắn","e":"They tried to rectify the situation.","ev":"Họ đã cố gắng sửa chữa tình huống.","k":"rectify, rectitude"},{"t":"ascetic, asceticism","p":"adj/noun","d":"sự khổ hạnh, sự khổ hạnh","e":"The ascetic monk lived a life of simplicity and self-denial.","ev":"Nhà sư khổ hạnh sống một cuộc đời giản dị và từ chối bản thân.","k":"ascetic, asceticism"},{"t":"altruistic, altruism","p":"adjective","d":"lòng vị tha, lòng vị tha","e":"His altruistic behavior showed a genuine concern for the well-being of others.","ev":"Hành vi vị tha của anh thể hiện sự quan tâm chân thành đến sự phúc lợi của người khác.","k":"altruistic, altruism"},{"t":"reverent","p":"adjective","d":"tôn kính","e":"She spoke in a reverent tone when discussing the contributions of the late professor.","ev":"Cô nói với tông giọng kính trọng khi thảo luận về những đóng góp của giáo sư đã qua đời.","k":"reverent"},{"t":"concur","p":"verb","d":"đồng tình","e":"The committee members concurred that the project should be postponed until further funding is secured.","ev":"Các thành viên trong ủy ban đồng ý rằng dự án nên được hoãn lại cho đến khi có thêm kinh phí.","k":"concur"},{"t":"degradation","p":"noun","d":"suy thoái","e":"The degradation of the environment is a pressing issue for our generation.","ev":"Sự suy thoái của môi trường là một vấn đề cấp bách cho thế hệ của chúng ta.","k":"degradation"},{"t":"aura","p":"noun","d":"hào quang","e":"She had an aura of confidence that drew people to her.","ev":"Cô ấy có một hào quang tự tin thu hút mọi người đến với mình.","k":"aura"},{"t":"fanaticism","p":"noun","d":"sự cuồng tín","e":"Fanaticism can lead to dangerous consequences in any ideology.","ev":"Sự cuồng tín có thể dẫn đến những hậu quả nguy hiểm trong bất kỳ hệ tư tưởng nào.","k":"fanaticism"},{"t":"encumbrance","p":"noun","d":"gánh nặng","e":"He considered his debts an encumbrance.","ev":"Anh ta coi nợ nần của mình là một gánh nặng.","k":"encumbrance"},{"t":"faction","p":"noun","d":"phe phái","e":"The faction within the party was pushing for more radical changes.","ev":"Phe phái trong đảng đang thúc đẩy những thay đổi quyết liệt hơn.","k":"faction"},{"t":"ungainly","p":"adjective","d":"vụng về, lóng ngóng","e":"The ungainly teenager tripped over his own feet while walking.","ev":"Cậu thanh niên vụng về đã vấp ngã vì chính đôi chân của mình khi đi bộ.","k":"ungainly"}]},{"n":"Buổi 38","c":[{"t":"impasse","p":"noun","d":"sự bế tắc","e":"The negotiations reached an impasse, with neither side willing to compromise.","ev":"Các cuộc đàm phán đã đạt đến bế tắc, khi không bên nào sẵn sàng thỏa hiệp.","k":"impasse"},{"t":"sage","p":"noun","d":"hiền nhân","e":"The sage shared his wisdom with those who sought guidance.","ev":"Nhà hiền triết đã chia sẻ trí tuệ của mình với những người tìm kiếm sự hướng dẫn.","k":"sage"},{"t":"jovial","p":"adjective","d":"vui tính","e":"The jovial atmosphere at the family gathering made everyone feel welcome.","ev":"Bầu không khí vui vẻ trong buổi họp mặt gia đình khiến mọi người cảm thấy được chào đón.","k":"jovial"},{"t":"complacency, \ncomplacent","p":"noun/adj","d":"sự tự mãn, \ntự mãn","e":"His complacency about his performance led to a lack of improvement.","ev":"Sự tự mãn của anh về hiệu suất của mình đã dẫn đến việc thiếu cải thiện.","k":"complacency, complacent"},{"t":"inhibit","p":"verb","d":"ức chế","e":"The drug can inhibit the growth of harmful bacteria.","ev":"Thuốc có thể ức chế sự phát triển của vi khuẩn có hại.","k":"inhibit"},{"t":"patronize","p":"verb","d":"đối xử với thái độ kể cả, hạ cố (giúp đỡ)","e":"It’s not polite to patronize someone just because you think you know more than they do.","ev":"Không lịch sự khi hạ thấp ai đó chỉ vì bạn nghĩ rằng bạn biết nhiều hơn họ.","k":"patronize"},{"t":"vying","p":"verb","d":"ganh đua","e":"The two companies are vying for the top position in the market.","ev":"Hai công ty đang cạnh tranh giành vị trí hàng đầu trên thị trường.","k":"vying"},{"t":"motley","p":"noun","d":"nhiều màu, pha tạp","e":"The motley crowd at the festival included people of all ages and backgrounds.","ev":"Đám đông đa dạng tại lễ hội bao gồm người thuộc đủ mọi lứa tuổi và nền tảng khác nhau.","k":"motley"},{"t":"urbane","p":"adjective","d":"tao nhã, lịch thiệp","e":"His urbane manner made him popular among his peers at the social event.","ev":"Cách cư xử lịch thiệp của anh khiến anh trở nên nổi bật trong mắt bạn bè tại sự kiện xã hội.","k":"urbane"},{"t":"decorum, decorous","p":"noun","d":"trang nhã","e":"The decorum maintained at the event was impressive, with everyone behaving appropriately.","ev":"Sự lịch thiệp được duy trì tại sự kiện thật ấn tượng, với mọi người cư xử đúng mực.","k":"decorum, decorous"},{"t":"static","p":"adjective","d":"tĩnh","e":"The static atmosphere in the room made everyone feel uncomfortable.","ev":"Bầu không khí tĩnh lặng trong phòng khiến mọi người cảm thấy không thoải mái.","k":"static"},{"t":"insular(ity)","p":"adj/noun","d":"hẹp hòi, cách biệt","e":"His insularity prevented him from understanding the broader implications of the issue.","ev":"Sự hẹp hòi của ông đã ngăn cản ông hiểu được những hàm ý rộng hơn của vấn đề này.","k":"insular(ity)"},{"t":"apathetic, apathy","p":"adj/noun","d":"thờ ơ, thờ ơ","e":"His apathetic response to the crisis surprised everyone.","ev":"Phản ứng thờ ơ của anh đối với cuộc khủng hoảng đã làm mọi người bất ngờ.","k":"apathetic, apathy"},{"t":"subversive","p":"adjective","d":"lật đổ","e":"The subversive group aimed to undermine the government’s authority.","ev":"Nhóm nổi loạn nhằm mục đích làm suy yếu quyền lực của chính phủ.","k":"subversive"},{"t":"unruly","p":"adjective","d":"ngỗ ngược, ngang ngạnh","e":"The unruly children made it difficult for the teacher to maintain order in the classroom.","ev":"Những đứa trẻ ngang ngạnh đã khiến giáo viên khó giữ trật tự trong lớp học.","k":"unruly"},{"t":"encroaching","p":"verb","d":"tới gần, xâm lấn","e":"The encroaching fog made it difficult to see the road ahead.","ev":"Sương mù đang đến gần khiến việc nhìn đường phía trước trở nên khó khăn.","k":"encroaching"},{"t":"Prophylactic","p":"adjective","d":"Phòng ngừa (bệnh tật)","e":"Some dentists are convinced that the addition of fluoride in water is ineffective as a prophylactic treatment.","ev":"Một số nha sĩ tin rằng việc bổ sung florua vào nước không có hiệu quả trong việc phòng ngừa.","k":"prophylactic"}]}]});
